addSet('iot',202500,{"title": "", "label": "2025 · Week 0", "tag": "’25 W0", "group": "2025", "questions": [{"q": "Which of the following allows us to identify objects and extract information?", "o": ["RFID", "Sensors", "Actuators", "IoT Nodes"], "a": 0, "s": ["RFID Technology allows us to automatically identify and track tags that are attached to the objects. It extracts information from the tags through electromagnetic fields."], "r": "See lecture 1 @ 12:57"}, {"q": "How many layers does Zigbee consist of?", "o": ["1", "2", "3", "4"], "a": 3, "s": ["Zigbee consists of 4 layers: Physical, Medium Access Control, Network, and Application."], "r": "See lecture 48 @ 16:11"}, {"q": "Which of the following is not a component of cloud computing?", "o": ["Clients", "Local Servers", "Services", "Applications"], "a": 1, "s": ["Cloud computing components include clients, services, applications, platform, storage, and infrastructure."], "r": "See lecture 37 @ 23:29"}, {"q": "Which of the following is a distance measuring sensor module?", "o": ["DHT22", "HC-SR04", "TSL2591", "HC-SR505"], "a": 1, "s": ["HC-SR04 is the distance measuring module ultrasonic sensor, which measures the distance between 2cm~450cm."], "r": "See lecture 3 @ 5:00"}, {"q": "Which of the following is a component in a typical sensor network?", "o": ["Sink", "Gateway", "Router", "All of these"], "a": 3, "s": ["A typical sensor network comprises of sensor nodes, routers, gateway, and sink."], "r": ""}, {"q": "Which of the following sensors are responsible for measuring orientation and angular velocity?", "o": ["Accelerometer", "GPS", "Temperature", "None of these"], "a": 3, "s": ["A gyroscope is responsible for measuring orientation and angular velocity."], "r": "See lecture 59 @ 15:41"}, {"q": "“ISA 100.11A” is a wireless networking technology standard. ISA stands for _______.", "o": ["International Society of Automation", "International Society of Advancement", "Industrial Society of Automation", "Industrial Society of Advancement"], "a": 0, "s": ["ISA100.11a is a wireless networking technology standard developed by the International Society of Automation (ISA)."], "r": "See lecture 13@ 15:55"}, {"q": "Which of the following is not a difference between traditional data center and cloud computing?", "o": ["Scalability", "Flexibility", "Elasticity", "Storage"], "a": 3, "s": ["Major differences between traditional data center and cloud computing include scalability, flexibility, elasticity, automation, running costs, and security"], "r": "See lecture 39 @ 11:02"}, {"q": "Smart grid is also known as the energy internet.", "o": ["True", "False"], "a": 0, "s": ["Smart grid is also known as the energy internet."], "r": "See lecture 51 @ 7:51"}, {"q": "Can a point of node failure result in the partition of the network in the stationary sensor network?", "o": ["Yes", "No"], "a": 0, "s": ["If there is a failure in the stationary sensor network then it is likely that the point of failure can partition the network into two or more fragments."], "r": "See lecture 18 @ 01:10"}]});
addSet('iot',202501,{"title": "", "label": "2025 · Week 1", "tag": "’25 W1", "group": "2025", "questions": [{"q": "IoT stands for ____________.", "o": ["Internet of Tasks", "Internet of Tuples", "Internet of Things", "None of these"], "a": 2, "s": ["The full form of IoT is “Internet of Things”"], "r": "See lecture 1 (Introduction to IoT – Part - I) @ 1:30"}, {"q": "Which of the following technologies have unified and has resulted in the evolution of IoT?", "o": ["High-power embedded systems", "Super Computing", "Engine Technology", "None of these"], "a": 3, "s": ["Unification of technologies which has resulted in the advancement of IoT are – a. Low-power embedded systems b. Cloud Computing c. Big Data d. Machine Learning e. Networking"], "r": "See lecture 1 (Introduction to IoT – Part - I) @ 5:54"}, {"q": "Which of the following are the enables of IoT?", "o": ["RFID", "Nanotechnology", "Sensors", "All of these"], "a": 3, "s": ["The enables of IoT are – a. RFID b. Nanotechnology c. Sensors d. Smart Networks"], "r": "See lecture 2 (Introduction to IoT – Part - I) @ 12:50"}, {"q": "Which of the following is NOT a function of an IoT LAN?", "o": ["Long range communication, global", "World wide connections", "Both (a) and (b)", "Neither (a) Nor (b)"], "a": 2, "s": ["The functionalities of an IoT Gateway are – a. Local, short-range communication b. Spreads across buildings or organization"], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 3:09"}, {"q": "State whether the following statement is True or False. Statement: The integration of existing devices, smart devices, and constrained nodes in a singular framework is one of the reasons for the address crunch in IoT.", "o": ["True", "False"], "a": 0, "s": ["The integration of existing devices, smart devices, and constrained nodes in a singular framework is one of the reasons for the address crunch in IoT."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 02:35"}, {"q": "State True or False. Statement: “In Multi-homing, a node/network is connected to a single network for improved reliability.", "o": ["True", "False"], "a": 1, "s": ["In multi-homing, a node/network is connected to multiple networks for improved reliability."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 15:22"}, {"q": "Which of the following is/are the approach/approaches for multi-homing?", "o": ["Proxy-based approach", "Gateway-based approach", "Both (a) and (b)", "None of these"], "a": 2, "s": ["The following are the approaches for multi-homing – 1. Proxy-based approach 2. Gateway-based approach"], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 16:10"}, {"q": "IPv6 uses ____________ notation for its representation.", "o": ["Hexadecimal", "Binary", "Decimal", "None of these"], "a": 0, "s": ["IPv6 uses Hexadecimal notation for its representation."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 17:00"}, {"q": "State True or False. The parameters sensed by a sensor may be sent to the cloud for further processing.", "o": ["False", "True"], "a": 1, "s": ["The parameters sensed by a sensor may be sent to the cloud for further processing."], "r": "See lecture 3 (Sensing) @ 01:15"}, {"q": "The IPv6 notation uses ___________________ number of bits to represent an address.", "o": ["64", "128", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 1, "s": ["The IPv6 notation uses 128 bits to represent an address."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 16:33"}, {"q": "A sensor is -", "o": ["Only sensitive to the measured property", "Insensitive to any other property that what the sensor is made to sense", "Both (a) and (b)", "None of these"], "a": 2, "s": ["a. Only sensitive to the measured property b. Insensitive to any other property that what the sensor is made to sense"], "r": "See lecture 3 (Sensing) @ 12:30"}, {"q": "We classify sensors based on -", "o": ["Output", "Data type", "Both (a) and (b)", "None of these"], "a": 3, "s": ["We classify sensors based on - a. Output b. Data type"], "r": "See lecture 3 (Sensing) @ 13:30"}, {"q": "Which of the following is correct statement", "o": ["Controlling AC loads using low DC signals", "Relays are electromechanical", "Relays are actuators", "All of these"], "a": 3, "s": ["All the statements given are correct."], "r": ""}, {"q": "Based on the output, sensors are classified as _______________________.", "o": ["Analog", "Digital", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 2, "s": ["Based on the output, sensors are classified as Digital and Analog."], "r": "See lecture 3 (Sensing) @ 13:05"}, {"q": "Soft actuators are -", "o": ["Polymer-based", "Mechanical", "Electromechanical", "None of these"], "a": 0, "s": ["Soft actuators are polymer based. Lecture 4, @ 15:00"], "r": ""}]});
addSet('iot',202502,{"title": "", "label": "2025 · Week 2", "tag": "’25 W2", "group": "2025", "questions": [{"q": "Based on functionality, MQTT is a _______ protocol.", "o": ["Transport", "Data", "Semantic", "None of these"], "a": 1, "s": ["MQTT is a Data Protocol."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 01:30"}, {"q": "MQTT is designed for -", "o": ["Remote connections", "Limited bandwidth", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 2, "s": ["MQTT is designed for – 1. Remote connections 2. Limited bandwidth"], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 03:50"}, {"q": "MQTT protocol follows _____________ paradigm for exchanging messages.", "o": ["Client-Server", "Publish-Subscribe", "Both (a) and (b)", "None of these"], "a": 1, "s": ["MQTT follows the publish-subscribe paradigm."], "r": ""}, {"q": "State True or False. Statement: “In MQTT, the Subscribers are Lightweight Sensors.”", "o": ["True", "False"], "a": 1, "s": ["In MQTT, the Publishers are lightweight sensors."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 04:49"}, {"q": "Which of the following is MQTT component?", "o": ["Middleman", "Mules", "Both (a) and (b)", "None of these"], "a": 3, "s": ["Components of MQTT are – 1. Publishers 2. Subscribers 3. Beokers"], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 04:50"}, {"q": "State True or False. A topic in MQTT can only be numbers.", "o": ["False", "True"], "a": 0, "s": ["A topic in MQTT is a string. Book - Introduction to IoT, Authors – Sudip Misra, Anandarup Mukherjee, and Arijit Roy, Publisher – Cambridge University Press, Edition – 1 (2021)"], "r": ""}, {"q": "State True or False. There are only two methods specified by the MQTT protocol.", "o": ["False", "True"], "a": 0, "s": ["There are 5 number of methods in MQTT protocol."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 05:49"}, {"q": "The Publish/Subscribe architecture in MQTT is _____________ driven.", "o": ["Event", "Pulse", "Sound", "None of these"], "a": 0, "s": ["Publish/Subscribe in MQTT is event-driven and enables messages to be pushed to clients."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 08:32"}, {"q": "State True or False. The topic is the routing information for the broker.", "o": ["True", "False"], "a": 0, "s": ["The topic is the routing information for the broker."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 08:30"}, {"q": "CoAP is _____________ and ____________.", "o": ["Based on HTTP", "Is designed for M2M applications", "None of these", "Both (a) and (b)"], "a": 3, "s": ["CoAP is based on HTTP and is designed for M2M applications."], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 00:49"}, {"q": "In CoAP, client-server interaction is asynchronous over a datagram transport protocol such as ____________.", "o": ["UDP", "TCP", "IP", "XMP"], "a": 0, "s": ["In CoAP, client-server interaction is asynchronous over a datagram transport protocol such as UDP."], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 00:50"}, {"q": "What is the full form of AMQP?", "o": ["Advanced Message Querying Protocol", "Advanced Message Quality Protocol", "Advanced Message Queuing Protocol", "None of these"], "a": 2, "s": ["Advanced Message Queuing Protocol"], "r": "See lecture 7 (Basics of IoT Networking – Part IV) @ 0:55"}, {"q": "AMQP has _______ number of frame types.", "o": ["6", "3", "5", "9"], "a": 3, "s": ["In AMQP there are nine frame types.."], "r": "See lecture 8 (Basics of IoT Networking – Part IV) @ 07:20"}, {"q": "State True or False. Statement: “The OSI model has 7 layers.”", "o": ["True", "False"], "a": 0, "s": ["The OSI model is a conceptual framework that divides any networked communication system into seven layers. See Page number – 10, Chapter - 1, Book - Introduction to IoT, Authors – Sudip Misra, Anandarup Mukherjee, and Arijit Roy, Publisher – Cambridge University Press, Edition – 1 (2021)"], "r": ""}, {"q": "The “Destination Address” in the IPv4 packet represents which of the following?", "o": ["The source node address of the packet", "The intermediate hop in the network", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 3, "s": ["The “Destination Address” in the IPv4 packet represents the address of the destination node in the network. See Page number – 18, Chapter - 1, Book - Introduction to IoT, Authors – Sudip Misra, Anandarup Mukherjee, and Arijit Roy, Publisher – Cambridge University Press, Edition – 1 (2021)"], "r": ""}]});
addSet('iot',202503,{"title": "", "label": "2025 · Week 3", "tag": "’25 W3", "group": "2025", "questions": [{"q": "State True or False. Statement: “WirelessHART is the latest release of Highway Addressable Remote Transducer protocol.”", "o": ["True", "False"], "a": 0, "s": ["WirelessHART is the latest release of Highway Addressable Remote Transducer protocol."], "r": "See lecture 11 (Connectivity Technologies-III) @ 01:42"}, {"q": "State True or False. Statement: “Wired HART has a network layer.”", "o": ["True", "False"], "a": 1, "s": ["Wired HART does not have a network layer."], "r": "See lecture 11 (Connectivity Technologies-III) @ 04:25"}, {"q": "State true or false: “WirelessHART physical layer is derived from 802.15.2 protocol”", "o": ["False", "True"], "a": 0, "s": ["WirelessHART physical layer is derived from 802.15.4 protocol."], "r": "See lecture 11 (Connectivity Technologies-III) @ 06:00"}, {"q": "WirelessHART operates only in __________ GHz ISM band.", "o": ["3.7", "4.8", "4.8", "2.4"], "a": 3, "s": ["HART operates only in the 2.4 GHz ISM band."], "r": "See lecture 11 (Connectivity Technologies-III) @ 06:00"}, {"q": "HART standard was developed from _____________ smart field devices.", "o": ["amplified", "diminished", "isolated", "networked"], "a": 3, "s": ["HART standard was developed for networked smart field devices."], "r": "See lecture 11 (Connectivity Technologies-III) @ 02:36"}, {"q": "Main difference between wired and unwired versions is in the physical, data link, and ______ layers.", "o": ["Data link", "Network", "Transport", "None of these"], "a": 1, "s": ["Main difference between wired and unwired versions is in the physical, data link, and network layers."], "r": "See lecture 11 (Connectivity Technologies-III) @ 05:05"}, {"q": "State true or false “Collision free and deterministic communication is achieved in HART’s data link layer.”", "o": ["True", "False"], "a": 0, "s": ["Collision free and deterministic communication is achieved in HART’s data link layer."], "r": "See lecture 11 (Connectivity Technologies-III) @ 06:37"}, {"q": "Channel hopping is incorporated in which layer of HART?", "o": ["Data link layer", "Physical layer", "Application layer", "Transport layer"], "a": 0, "s": ["Channel hopping is incorporated in the data link layer of HART."], "r": "See lecture 11 (Connectivity Technologies-III) @ 08:21"}, {"q": "State True or False. “The HART application layer is responsible for extracting commands from a message, executing it and generating responses.”", "o": ["True", "False"], "a": 0, "s": ["The HART application layer is responsible for extracting commands from a message, executing it and generating responses."], "r": "See lecture 11 (Connectivity Technologies-III) @ 10:26"}, {"q": "NFC is designed for use by devices within ________________ to each other.", "o": ["Anywhere on the globe", "A small building", "Both (a) and (b)", "None of these"], "a": 3, "s": ["NFC is designed for use by devices within close proximity to each other."], "r": "See lecture 11 (Connectivity Technologies-III) @ 17:47"}, {"q": "Passive NFC devices ___________ information which is _____________ by other devices.", "o": ["contain, read", "read, contain", "contain, contain", "None of these"], "a": 0, "s": ["Passive NFC devices contain information which is read by other devices."], "r": "See lecture 11 (Connectivity Technologies-III) @ 18:34"}, {"q": "State True or False. “NFC devices work on the principle of magnetic induction.”", "o": ["True", "False"], "a": 0, "s": ["NFC devices work on the principle of magnetic induction."], "r": "See lecture 11 (Connectivity Technologies-III) @ 21:47"}, {"q": "Bluetooth technology is based on _________________.", "o": ["HART", "ZigBee", "All of these", "None of these"], "a": 3, "s": ["Bluetooth technology is based on Ad-hoc piconets."], "r": "See lecture 12 (Connectivity Technologies-IV) @ 02:30"}, {"q": "State whether the following statement is true or false. Statement: The Link Manager Protocol in Bluetooth manages the only establishment and authentication.", "o": ["True", "False"], "a": 1, "s": ["The Link Manager Protocol in Bluetooth manages the establishment, authentication, link configuration. See Page number – 157, Chapter - 7, Book - Introduction to IoT, Authors – Sudip Misra, Anandarup Mukherjee, and Arijit Roy, Publisher – Cambridge University Press, Edition – 1 (2021)"], "r": ""}, {"q": "Zigbee commonly uses __________data rate.", "o": ["260 bps", "260 kbps", "260 Mbps", "None of these"], "a": 3, "s": ["Zigbee commonly uses a 250-kbps data rate. See Page number – 131, Chapter - 7, Book - Introduction to IoT, Authors – Sudip Misra, Anandarup Mukherjee, and Arijit Roy, Publisher – Cambridge University Press, Edition – 1 (2021)"], "r": ""}]});
addSet('iot',202504,{"title": "", "label": "2025 · Week 4", "tag": "’25 W4", "group": "2025", "questions": [{"q": "State whether the following statement is true or false. Statement: In “AID”, a set of sensor nodes are deployed over an agricultural field.", "o": ["True", "False"], "a": 0, "s": ["In “AID”, a set of sensor nodes are deployed over a agricultural field"], "r": "See lecture 16 (Sensor Networks-III) @ 13:16"}, {"q": "State True or False. Statement: Ultrasonic sensor senses the distance at which an object is located.", "o": ["True", "False"], "a": 0, "s": ["Ultrasonic sensor senses the distance at which an object is located."], "r": "See lecture 16 (Sensor Networks-III) @ 13:18"}, {"q": "State true or false. In case of static sensors, where to deploy and/or activate sensors in WSN is a coverage problem.", "o": ["True", "False"], "a": 0, "s": ["In case of static sensors, where to deploy and/or activate sensors in WSN is a coverage problem."], "r": "See lecture 17 (Sensor Networks-IV) @ 07:11"}, {"q": "State whether the following statement is true or false. Statement: Objective of coverage in WSN is to use maximum number of sensors and minimize network lifetime.", "o": ["True", "False"], "a": 1, "s": ["The objective of coverage in WSN is to use minimum number of sensors and maximize the network lifetime."], "r": "See lecture 17 (Sensor Networks-IV) @ 08:47"}, {"q": "State whether the following statement is true or false. Statement: “A crossing is covered if it is in the interior of at least one node’s coverage disk.”", "o": ["True", "False"], "a": 0, "s": ["A crossing is covered if it is in the interior of at least one node’s coverage disk."], "r": "See lecture 17 (Sensor Networks-IV) @ 18:58"}, {"q": "State which of the following is/are correct for stationary wireless sensor networks.", "o": ["Topology cannot be changed automatically.", "Node failure may result in partition of networks.", "Both (a) and (b)", "None of these"], "a": 2, "s": ["Topology cannot be changed automatically. And Node failure may result in partition of networks. Are correct."], "r": "See lecture 18 (Sensor Networks-V) @ 00:43"}, {"q": "Most problems in static WSN can be classified as -", "o": ["No coverage", "More coverage", "Both (a) and (b)", "None of these"], "a": 3, "s": ["Most problems in static WSN can be classified as - a. Area coverage b. Point coverage c. Barrier coverage"], "r": "See lecture 18 (Sensor Networks-V) @ 11:30"}, {"q": "Which of the following is/are correct with respect UAV networks?", "o": ["Multi-tasking", "Large coverage area", "Both (a) and (b)", "None of these"], "a": 2, "s": ["Multi-tasking and Large coverage area are correct."], "r": "See lecture 19 (Sensor Networks-V) @ 05:19"}, {"q": "State True or False. Statement: UAV networks are scalable.", "o": ["True", "False"], "a": 0, "s": ["UAV networks are scalable."], "r": "See lecture 19 (UAV Networks-V) @ 09:00"}, {"q": "In Mobile WSN, the Data Mules", "o": ["Collect the data from sensor nodes", "Goes to the sink and delivers the collected data", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 2, "s": ["In Mobile WSN, the Data Mules a. Collect the data from sensor nodes b. Goes to the sink and delivers the collected data"], "r": "See lecture 18 (Sensor Networks-V) @ 07:15"}, {"q": "The full form of AUV is -", "o": ["Antenna Used Vehicle", "Autonomous Underwater Vehicle", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 1, "s": ["Autonomous Underwater Vehicle (AUV)"], "r": "See lecture 18 (Sensor Networks-V) @ 08:35"}, {"q": "Humans carry their devices and move around. Sensors embedded within the devices record readings. Sensory readings are then transmitted for processing. This paradigm of sensing is known as –", "o": ["Machine Centric Sensing", "Device Centric Sensing", "Human Centric Sensing", "None of these"], "a": 2, "s": ["Humans carry their devices and move around. Sensors embedded within the devices record readings. Sensory readings are then transmitted for processing. This paradigm of sensing is known as Human Centric Sensing."], "r": "See lecture 18 (Sensor Networks-V) @ 11:37"}, {"q": "State True or False. Energy of Devices and Participant selection are not two major problems in Human Centric Sensing.", "o": ["True", "False"], "a": 1, "s": ["Energy of Devices and Participant selection are not two major problems in Human Centric Sensing."], "r": "See lecture 18 (Sensor Networks-V) @ 12:45"}, {"q": "Which of the following network topologies is used in UAV networks?", "o": ["Bus", "Star", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 1, "s": ["UAV networks use the mesh and star network topologies."], "r": "See lecture 19 (UAV Networks) @ 02:43"}, {"q": "State true of false. The M2M Application Platform provides integrated services based on device collected data-sets.", "o": ["True", "False"], "a": 0, "s": ["The M2M Application Platform provides integrated services based on device collected data-sets."], "r": "See lecture 20 (Machine to Machine Communication) @ 18:00"}]});
addSet('iot',202505,{"title": "", "label": "2025 · Week 5", "tag": "’25 W5", "group": "2025", "questions": [{"q": "Which of the following is/are current challenges in IoT?", "o": ["Large scale of co-operation", "Global heterogeneity", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 2, "s": ["Large scale of co-operation and Global heterogeneity are current challenges in IoT."], "r": "See lecture 21 (Interoperability in Internet of Things) @ 03:41."}, {"q": "State True or False. Statement: “Interoperability is not a characteristic of a product or system.”", "o": ["True", "False"], "a": 1, "s": ["Interoperability is a characteristic of a product or system."], "r": "Refer Lecture 21@5:51"}, {"q": "Interoperability is required because", "o": ["There are different programming languages", "There are different communication protocols", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 2, "s": ["Interoperability is required because a) There are different programming languages b) There are different communication protocols"], "r": "Refer Lecture 21@08:30"}, {"q": "State whether the following statement is true or false Statement: “Use of different programming languages such as JavaScript, Python, JAVA, and others is an example of heterogeneity in IoT. This brings in the need for interoperability.”", "o": ["False", "True"], "a": 1, "s": ["Use of different programming languages such as JavaScript, Python, JAVA, and others is an example of heterogeneity in IoT. This brings in the need for interoperability (Please refer Lecture 21@09:12)"], "r": ""}, {"q": "State True or False. Statement: “The interoperability between devices and device users in terms of message formats is called Systematic Interoperability.”", "o": ["True", "False"], "a": 1, "s": ["The interoperability between devices and device users in terms of message formats is called Syntactic Interoperability."], "r": "Refer Lecture 21@17:06."}, {"q": "What is the full form of UMB in IoT interoperability?", "o": ["Universal Meta Bridge", "Universal Main Bridge", "Universal Main Bracket", "None of these"], "a": 3, "s": ["UMB stands for Universal Middleware Bridge."], "r": "Refer Lecture 21@22:16."}, {"q": "State true of false Arduino is an open-source electronic programmable board.", "o": ["True", "False"], "a": 0, "s": ["Arduino is an open-source electronic programmable board."], "r": "Refer Lecture 22@05:17"}, {"q": "State true or false Additional electronic circuits are essential to load a program into the Arduino controller board.", "o": ["True", "False"], "a": 1, "s": ["No additional electronic circuits are essential to load a program into the Arduino controller board."], "r": "Refer Lecture 22@05:17."}, {"q": "Arduino UNO has _________ number of Digital I/O pins.", "o": ["8", "13", "14", "None of these"], "a": 2, "s": ["Arduino UNO has 14 number of Digital I/O pins."], "r": "Refer Lecture 22@07:08."}, {"q": "What does the following code do? int ledPin = 13; void setup() { pinMode(ledPin, OUTPUT); for (int i = 0; i &lt; 3; i++) { digitalWrite(ledPin, HIGH); delay(1000); digitalWrite(ledPin, LOW); delay(500); } } void loop() { // Do nothing }", "o": ["Blink 3 times with 1000ms ON and 500ms OFF", "Blink 3 times with 500ms ON and 500ms OFF", "Blink 3 times with 1000ms ON and 1000ms OFF", "Stay ON continuously"], "a": 0, "s": ["The LED is turned ON for 1000ms using delay(1000). The LED is turned OFF for 500ms using delay(500). This process repeats 3 times in the for loop. Thus, the LED blinks 3 times with 1000ms ON and 500ms OFF."], "r": ""}, {"q": "How many types of loops will you find in Arduino Programming?", "o": ["1", "2", "3", "4"], "a": 2, "s": ["Like C programming Arduino sketches also have 3 types of loops, for, while and do-while loops."], "r": ""}, {"q": "Choose the right option for if/conditional operator.", "o": ["Val = (condition)?(Statement 1):(Statement 2)", "Val = (condition)?(Statement 2):(Statement 1)", "Val = (condition):(Statement 1)?(Statement 2)", "Val = (condition):(Statement 2)?(Statement 1)"], "a": 0, "s": ["Conditional operator may also be written as Val = (condition)?(Statement 1):(Statement 2). (Please refer Lecture 23@2:01)"], "r": ""}, {"q": "What is the purpose of calling dht.begin(); in the setup() function?", "o": ["To initialize the Serial Monitor", "To start communication with the DHT sensor", "To set the temperature and humidity values to zero", "To define the data pin for the sensor"], "a": 1, "s": ["Calling dht.begin(); in the setup() function starts communication with the DHT sensor."], "r": "Refer Lecture 24@ 17:25."}, {"q": "What function is used to read the humidity value from the DHT sensor?", "o": ["dht.getHumidity();", "dht.readTemp();", "dht.readHumidity();", "dht.getTemperature();"], "a": 2, "s": ["dht.readHumidity(); function is used to read the humidity value from the DHT sensor Lecture 24@17:25."], "r": ""}, {"q": "What function is used to set the servo motor to a specific angle?", "o": ["ServoDemo.move()", "ServoDemo.rotate()", "ServoDemo.write()", "ServoDemo.setAngle()"], "a": 2, "s": ["ServoDemo.write() function is used to set the servo motor to a specific angle."], "r": "Refer Lecture 25@18:47."}]});
addSet('iot',202506,{"title": "", "label": "2025 · Week 6", "tag": "’25 W6", "group": "2025", "questions": [{"q": "State True or False. Statement: “Python is popular for embedded application development as it is a very lightweight programming language.”", "o": ["True", "False"], "a": 0, "s": ["Python is popular for embedded application development as it is a very lightweight programming language. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I @ 1:22 )"], "r": ""}, {"q": "State True or False. Adafruit provides a library to work with DHT22 Sensor.", "o": ["True", "False"], "a": 0, "s": ["Adafruit provides a library to work with DHT22 Sensor. (Please refer to lecture Implementation of IoT with Raspberry Pi- II @ 4:41)"], "r": ""}, {"q": "Consider the following piece of Python code. What is the output? x = [4, 5, 6] y = [str(x[0] + 1), str(len(x) * 2) + '&amp;Code'] z = y[1].split('&amp;') print(z[1])", "o": ["5", "12", "Code", "&amp;Code"], "a": 2, "s": ["1. x = [4, 5, 6]: A list with three elements. 2. y = [str(x[0] + 1), str(len(x) * 2) + '&amp;Code']: o x[0] is 4, so x[0] + 1 is 5, and str(x[0] + 1) becomes \"5\". o len(x) is 3, so len(x) * 2 is 6, and str(len(x) * 2) + '&amp;Code' becomes \"6&amp;Code\". o Therefore, y = [\"5\", \"6&amp;Code\"]. 3. z = y[1].split('&amp;'): o y[1] is \"6&amp;Code\". o Splitting \"6&amp;Code\" by '&amp;' gives ['6', 'Code']. 4. z[1] is 'Code'. Thus, the print(z[1]) statement outputs Code."], "r": ""}, {"q": "State True or False. Statement: “To indicate different blocks of code, Python follows rigid indentation.”", "o": ["True", "False"], "a": 0, "s": ["To indicate different blocks of code, Python follows rigid indentation . (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I @ 7::29)."], "r": ""}, {"q": "What is the output of the following line of code in Python? &gt;&gt;&gt; print “Hi, Welcome to python!”", "o": ["Hi, Welcome to python!", "“Hi, Welcome to python!”", "Hi, Welcome to python", "None of these"], "a": 0, "s": ["The output of the following line of code in Python - &gt;&gt;&gt; print “Hi, Welcome to python!” Output: Hi, Welcome to python! (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- II @ 07 : 3 1 )"], "r": ""}, {"q": "During remote server access by a Raspberry Pi, where the Raspberry Pi acts as a client, the client needs the following?", "o": ["Only IP address of server", "Only port number", "Both server IP address and port number", "Client’s IP address"], "a": 2, "s": ["A client can communicate with a server only if both IP address and port numbers are known. (Please refer Lecture 31@14:13)"], "r": ""}, {"q": "State whether the following command to install the PIL library is correct or not. sudo pip install pillow", "o": ["Correct", "Incorrect"], "a": 0, "s": ["The command to install the PIL library is sudo pip install pillow . (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- II @ 17 : 4 0 )"], "r": ""}, {"q": "What is the purpose of the \"w\" mode in the open() function in Python?", "o": ["To read a file", "To write data to a file, overwriting existing content", "To append data to a file", "To open a file in read and write mode"], "a": 1, "s": ["“w” mode is used to write data to a file, overwriting existing content (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- II @ 05:05 ) ."], "r": ""}, {"q": "What will be the output of the given Python program when reading from the file? with open(\"PythonProgram.txt\", \"w\") as file: file.write(\"Writing data\") with open(\"PythonProgram.txt\", \"r\") as file: f = file.read() print('Reading from the file\\n') print(f)", "o": ["Writing data", "Reading from the file Writing data", "Error: File not found", "None of the above"], "a": 1, "s": ["Reading from the file Writing data (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING-II @05:05)."], "r": ""}, {"q": "Can we configure Raspberry Pi as a File Server?", "o": ["Yes", "No"], "a": 0, "s": ["We can configure Raspberry Pi as a File Server."], "r": "See lecture INTRODUCTION TO RASPBERRY PI-I @ 02: 4 6"}, {"q": "Which command is used to configure the Raspberry Pi for the camera module?", "o": ["sudo camera-config", "sudo raspi-config", "sudo enable-camera", "sudo pi-setup"], "a": 1, "s": ["sudo raspi-config is used to configure the Raspberry Pi for the camera module"], "r": "See lecture INTRODUCTION TO RASPBERRY PI-II @ 18:44"}, {"q": "What is the final step after enabling the camera in the Raspberry Pi configuration?", "o": ["Restart the camera service", "Run a camera test command", "Reboot the Raspberry Pi", "Reinstall the Raspberry Pi OS"], "a": 2, "s": ["after enabling the camera in the Raspberry Pi configuration, reboot."], "r": "See lecture IMPLEMENTATION OF IOT WITH RASPBERRY PI-II @ 18:44"}, {"q": "Which command Exits the nano editor?", "o": ["Ctrl + X", "Ctrl + O", "Ctrl + K", "None of these"], "a": 0, "s": ["Ctrl + O exits the nano editor."], "r": "See lecture IMPLEMENTATION OF IOT WITH RASPBERRY PI-II @ 10:20"}, {"q": "In a temperature-controlled fan system using a relay, when should the fan turn on?", "o": ["When the relay is manually triggered", "When the surrounding temperature is lower than a predefined threshold", "When the surrounding temperature exceeds a predefined threshold", "When the battery voltage drops below a certain level"], "a": 2, "s": ["In a temperature-controlled fan system using a relay, the fand should turn on when the surrounding temperature exceeds a predefined threshold. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- II @ 11 : 1 8 )"], "r": ""}, {"q": "What does the following line of code do? raspistillcapture -o image.jpg", "o": ["Captures video feed", "Captures still image", "Both (a) and (b)", "None of these"], "a": 3, "s": ["Command is wrong. (Please refer to lecture INTRODUCTION TO RASPBERYY PI-II @ 19 : 29 )"], "r": ""}]});
addSet('iot',202507,{"title": "", "label": "2025 · Week 7", "tag": "’25 W7", "group": "2025", "questions": [{"q": "In Python socket programming, while defining a socket, SOCK_STREAM refers to a type of", "o": ["SocketFamily", "SocketType", "SocketName", "SocketProtocol"], "a": 1, "s": ["Refer Lecture 31@6:27"], "r": ""}, {"q": "If you want to change the label of the Y-axis while plotting a graph using matplotlib in Python, what among the following functions do you use? Suppose you have imported matplotlib as plt", "o": ["plt.show()", "plt.plot()", "plt.ylabel()", "plt.yaxis()"], "a": 2, "s": ["Refer Lecture 32@12:39."], "r": ""}, {"q": "In Socket programming, the parameter AF_INET stands for ___________.", "o": ["Unix protocols", "Internet Protocol (IP)", "File sharing", "Time slicing"], "a": 1, "s": ["The AF_INET specifies the rules and standards of the Internet protocol, hence the socket acts as an IP socket. (Please refer Lecture 31@14:13)"], "r": ""}, {"q": "Suppose a Python server is receiving data from a socket as follows, data, addr = sock.recvfrom(1024) What kind of socket ‘sock’ is being considered here.", "o": ["TCP socket", "UDP socket", "TAP socket", "None of the given"], "a": 1, "s": ["sock.recvfrom() is the form used to receive data from UDP sockets. Refer to any standard socket programming documentations."], "r": ""}, {"q": "What is the use of the Mobi-Flow protocol?", "o": ["Enabling static SDN", "Enabling SDN to incorporate mobility", "Enabling Odin Master", "Enabling traditional BGP"], "a": 1, "s": ["Refer Lecture 34@14:41."], "r": ""}, {"q": "During remote server access using socket programming what is the utility of the &lt;socket_name&gt;.listen() function?", "o": ["To create a new socket", "To bind the socket to connection", "To wait for clients to connect", "To close the connection"], "a": 2, "s": ["listen() function makes the server wait for incoming client connections (Refer Lecture 31 ppt no 13)"], "r": ""}, {"q": "Which among the following is the correct direction for PACKET_OUT type messages in SDN?", "o": ["From controller to switch", "From switch to controller", "Between two switches", "Between two controllers"], "a": 0, "s": ["PACKET_OUT messages are sent from switches to the controller upon receipt of new unknown packets. Refer lecture 33, ppt no 20."], "r": ""}, {"q": "Which among the following is a limitation of the traditional non-SDN networks?", "o": ["Switches do not possess routing table", "Switches are unable to forward traffic", "Switches do not have a global view of the network.", "All of the given"], "a": 2, "s": ["Refer Lecture 33@6:53."], "r": ""}, {"q": "During remote server access by a Raspberry Pi, where the Raspberry Pi acts as a client, the client needs the following?", "o": ["Only IP address of server", "Only port number", "Both server IP address and port number", "Client’s IP address"], "a": 2, "s": ["A client can communicate with a server only if both IP address and port numbers are known. (Please refer Lecture 31@14:13)"], "r": ""}, {"q": "With respect to the concept of soft time-out and hard time-out in SDN switches, which of the following relations hold?", "o": ["Soft time-out &gt; = hard time-out", "Hard time-out &gt;= soft time-out", "Soft time-out = hard time-out always", "None of the given"], "a": 1, "s": ["Hard time-outs of flow rules are always greater than soft time-outs, not the other way round. Refer lecture 33, OpenFlow Protocol III"], "r": ""}, {"q": "Which of the following is true?", "o": ["Traditional Network: Routing Table, Software Defined Network: Routing Table", "Traditional Network: Flow Table, Software Defined Network: Routing Table", "Traditional Network: Routing Table, Software Defined Network: Flow Table", "Traditional Network: Flow Table, Software Defined Network: Flow Table"], "a": 2, "s": ["All switches in traditional network have routing tables and those in Software Defined Network have flow tables (Please refer Lecture 33@17:15)"], "r": ""}, {"q": "Consider the following figure below. To which issue of SDN does this particular figure can be related to?", "o": ["Controller placement issue", "Flow Rule placement issue", "Hardware placement issue", "Analysis placement issue"], "a": 1, "s": ["The given figures shows the tabular structure of how flow rules are installed within SDN switches, so it pertains to flow rule placement issues. Refer Lecture 33@18:54, Rule Placement."], "r": "", "img": "assets/iot/2025-w7-q12-1.png"}, {"q": "With respect to the directional APIs in SDN, what is the functionality of East-Westbound APIs?", "o": ["To communicate between the controller and switches", "To communicate among multiple controllers", "East-Westbound APIs do not exist", "To communicate between switches themselves."], "a": 1, "s": ["Refer Lecture 34@2:10."], "r": ""}, {"q": "Hierarchical SDN architecture is also known as __________ architecture.", "o": ["Tree", "Flat", "Mesh", "Line"], "a": 0, "s": ["Refer Lecture 34@6:12"], "r": ""}, {"q": "Integrating SDN with IoT is not recommended and is not a suitable approach to follow", "o": ["False", "True"], "a": 0, "s": ["SDN integration with IoT is highly recommended for efficient delivery of services. Refer Lecture 35."], "r": ""}]});
addSet('iot',202508,{"title": "", "label": "2025 · Week 8", "tag": "’25 W8", "group": "2025", "questions": [{"q": "What is Sensor Openflow?", "o": ["A traditional routing protocol", "A queue management protocol", "An SDN protocol tailored for IoT devices", "A physical connectivity protocol."], "a": 2, "s": ["Refer Lecture 36@1:38"], "r": ""}, {"q": "With respect to Mobi-Flow, how does Mobi-Flow fare in comparison to Conventional networking in terms of message overhead?", "o": ["Mobi-Flow &gt; Conventional", "Mobi-Flow &lt; Conventional", "Mobi-Flow = Conventional", "None of the given"], "a": 1, "s": ["Refer Lecture 36@16:08."], "r": ""}, {"q": "Virtual Machines came before Cloud Computing.", "o": ["True", "False"], "a": 0, "s": ["Virtual Machines came before Cloud Computing. Refer Lecture 37@8:00"], "r": ""}, {"q": "Private cloud services cannot provide Software-as-a-Service (SaaS).", "o": ["True", "False"], "a": 1, "s": ["Any cloud deployment model can provide any cloud service model. Refer Lecture 37@14:36."], "r": ""}, {"q": "Which among the following is a solution for mobility-aware flow rule placement in SDIoT?", "o": ["Mobility-Flow", "Mobile-Flow", "Mobi-Flow", "M-Flow"], "a": 2, "s": ["Detailed Answer: Mobi-Flow has been proposed to provide a solution for mobility-aware flow rule placement. Refer Lecture 36@13:09 onwards"], "r": ""}, {"q": "An organization A wants to deploy a cloud infrastructure, whereby it wants to push majority of the data to a cloud whose servers can be situated anywhere within the globe, but it wants certain private data to be pushed only to cloud servers that are present on-premise and are accessible by only authenticated members of the organization. In this context which among the following deployment model should be used?", "o": ["Private Cloud", "Public Cloud", "Hybrid Cloud", "Any of these"], "a": 2, "s": ["Hybrid cloud deployment model supports both the features of public and private cloud. Refer lecture 37, ppt No. 18."], "r": ""}, {"q": "Which among the following is the most on-premise cloud deployment model?", "o": ["Private Cloud", "Public cloud", "IaaS", "PaaS"], "a": 0, "s": ["Refer Lecture 37@33:31."], "r": ""}, {"q": "Which of the following type of client requires constant communication/connection with the cloud server?", "o": ["Thin client", "Thick client", "Both thin and thick clients", "None of these"], "a": 0, "s": ["Detailed Answer : A thin client is a network computer without a hard disk drive and high configurations. They act as simple terminals and require constant communication with the servers. (Please refer Lecture 37@20:00)"], "r": ""}, {"q": "What does ‘CIA’ in cloud data security stand for?", "o": ["Confidentiality, Integrity, Availability", "Confidentiality, Inheritance, Automation", "Congestion, Integrity, Authentication", "Criticality, Integrity, Accountability"], "a": 0, "s": ["‘CIA’ stands for ‘Confidentiality, Integrity and Availability’. (Please refer Lecture 39@21:01)"], "r": ""}, {"q": "When you are accessing Spotify online for listening to music from your browser without specifically installing them, which among the following cloud service models is the most appropriate one that you are using.", "o": ["SaaS", "PaaS", "IaaS", "DaaS"], "a": 0, "s": ["This is an example of SaaS, since you are accessing a word/document processing software as a client over the network. The actual software itself runs on some remote cloud server (Please refer Lecture 37@26:14 AND 38@13:16)"], "r": ""}, {"q": "With respect to Cloud Computing security, which of the following are necessary", "o": ["Network Level Security but not Host Level Security", "Application Level Security but not Host Level Security", "Host Level Security but not Network Level Security", "All of Network, Host and Application Level Security."], "a": 3, "s": ["Refer Lecture 39 Cloud Security."], "r": ""}, {"q": "Data security and client authentication is an issue in which of the following cloud service models?", "o": ["SaaS", "SaaS and PaaS", "IaaS", "All of them"], "a": 3, "s": ["Security is a pertinent issue in all of the cloud service models, which includes SaaS, PaaS and IaaS. Refer to any standard discussion on challenges and issues on cloud computing and Lecture 39."], "r": ""}, {"q": "What is the role of a Hypervisor (most probable answer)?", "o": ["To facilitate installation of a router", "To provide a platform for executing virtual machines", "To facilitate sensor fabrication", "To communicate between switches themselves."], "a": 1, "s": ["Refer Lecture 38@5:40."], "r": ""}, {"q": "Which of the following is a limitation of SaaS?", "o": ["Remote software execution", "Platform independence", "Centralized control", "None of these."], "a": 2, "s": ["Refer Lecture 38@15:58."], "r": ""}, {"q": "Fill in the blank. ____________ means independent of device or location.", "o": ["Scalable", "Reliability", "Agile", "Ubiquitous"], "a": 3, "s": ["Ubiquitous means independent of device or location. (Please refer Lecture 37@18:06)"], "r": ""}]});
addSet('iot',202509,{"title": "", "label": "2025 · Week 9", "tag": "’25 W9", "group": "2025", "questions": [{"q": "Which of the following is/are the advantages of cloud computing?", "o": ["Elasticity", "Pay-per-use", "Self Service", "All of the above"], "a": 3, "s": ["The advantages of cloud computing include Elasticity, Pay-per-use and Self-Service. (Please refer Lecture 42@6:45)"], "r": ""}, {"q": "Fill in the blanks. Fog computing is an intermediate layer between __________ and _________.", "o": ["Dew and devices", "Cloud and devices", "Cloud and server", "None of these"], "a": 1, "s": ["Fog computing is an intermediate layer between Cloud and devices. (Please refer Lecture 44@6:40)"], "r": ""}, {"q": "The managerial role is played by __________ in sensor-cloud architecture.", "o": ["End-users", "Sensor-Cloud Service Provider", "Neither a nor b", "Both a and b"], "a": 1, "s": ["Sensor-Cloud Service Provider plays the managerial role in sensor-cloud architecture. (Please refer Lecture 42@14:29)"], "r": ""}, {"q": "Which of the following is not a component of OpenStack?", "o": ["Suse", "Nova", "Swift", "All of these"], "a": 0, "s": ["Nova and Swift are two of the many components of OpenStack (Please refer Lecture 41@3:18)"], "r": ""}, {"q": "Who coined the term Fog computing?", "o": ["IBM", "CISCO", "All of these", "None of these"], "a": 1, "s": ["CISCO coined the term Fog computing. (Please refer Lecture 44@4:18)"], "r": ""}, {"q": "Fill in the blank. The concept of ________ enables physical hardware to be shared among multiple entities.", "o": ["Hardware virtualization", "Software virtualization", "Module virtualization", "All of these"], "a": 0, "s": ["The concept of hardware virtualization enables physical hardware to be shared among multiple entities. (Please refer to Page 262, Chapter 11, Introduction to IoT. S. Misra, A. Mukherjee, and A. Roy, 2020. Cambridge University Press.)"], "r": ""}, {"q": "Openstack is a free open source software for cloud framework simulation and experimentation with various cloud applications.", "o": ["True", "False"], "a": 0, "s": ["Openstack is a free open source software for cloud framework simulation and experimentation with various cloud applications. It can be downloaded and installed for free. Refer Lecture 41."], "r": ""}, {"q": "In IoT, temporal sensitivity of data DOES NOT play an important role", "o": ["True", "False"], "a": 1, "s": ["IoT data can be classified in to time sensitive data, less time sensitive data and data not sensitive to time. Hence time sensitivity plays a big role in IOT data classification. Refer lecture 44 on Fog Computing"], "r": ""}, {"q": "Which among the following is NOT a component of OpenStack.", "o": ["Horizon", "Heat", "Stellar", "Neutron"], "a": 2, "s": ["Stellar is not a component of OpenStack. The rest are various components, including Nova, Glance, Swift etc. Refer lecture 41, ppt No. 4"], "r": ""}, {"q": "Which among the following is the principal feature of sensor clouds, with respect to sensor nodes?", "o": ["Sensor monitoring", "Sensor instantiation", "Sensor virtualization", "Sensor collection"], "a": 2, "s": ["Sesnor virtualization is the principal feature of sensor clouds and their utility. Refer lecture 42 and 43 on Sensor cloud"], "r": ""}, {"q": "The optimal composition of __________ is a management issue in sensor-cloud.", "o": ["Logistics", "Pricing", "Caching", "Virtual sensor nodes"], "a": 3, "s": ["The optimal composition of Virtual sensor nodes is a management issue in sensor-cloud. (Please refer Lecture 43@4:39)"], "r": ""}, {"q": "How many different types of caching mechanism are there in sensor cloud?", "o": ["1", "4", "2", "3"], "a": 2, "s": ["Detailed Answer: Internal Cache (IC) and External Cache (EC) are two different types of caching mechanisms used in sensor cloud. Refer lecture 43, ppt No. 13"], "r": ""}, {"q": "Data from an IoT device is transferred to cloud via a network, which is then processed at the cloud and then a response is sent back to the IoT device from the cloud after processing. The time it takes for one- way data transfer between the node and cloud is 10s and the data processing time at the cloud is ‘x’ seconds. It takes a total of 25s for the entire to and fro transfer of data between the sensor and cloud along with processing at the cloud. What is the value of x?", "o": ["10s", "5s", "15s", "20s"], "a": 1, "s": ["Time taken for one-way data transfer between the node and cloud is 10s. Total time taken for the data transfer is 25s. So 25=10+x+10 (transfer from node to cloud+processing at cloud+transfer from cloud to node). Thus x=5s."], "r": ""}, {"q": "Which among the following is true?", "o": ["Fog computing acts as a complement to cloud computing.", "Fog computing is a replacement for cloud computing.", "Fog computing and cloud computing are the same.", "Fog computing is more powerful than cloud computing (with respect to resources)."], "a": 0, "s": ["Fog computing and cloud computing are complementary technologies. Fog helps in bringing the cloud closer to the IoT devices. (Please refer Lecture 45@1:06)"], "r": ""}, {"q": "Which component of OpenStack do you use to access all the other components?", "o": ["Horizon", "Glance", "Neutron", "None of these"], "a": 0, "s": ["Horizon is the dashboard of OpenStack which provides the GUI and from where you can access other components. Please refer Lecture 41@3:54"], "r": ""}]});
addSet('iot',202510,{"title": "", "label": "2025 · Week 10", "tag": "’25 W10", "group": "2025", "questions": [{"q": "Which among the following are active connected entities in a holistic smart city environment?", "o": ["Police station", "Banks", "Transport centers", "All of the above"], "a": 3, "s": ["Refer Lecture 46@4:45."], "r": ""}, {"q": "With the help of ICT tools, it is possible to increase and improve citizen participation for a good governance based smart city", "o": ["True", "False"], "a": 0, "s": ["Refer Lecture 46@11:20."], "r": ""}, {"q": "Which among the following is a possible challenge with respect to smart parking lots?", "o": ["Efficient auto-routing of vehicles", "Locating current vacant spots", "Auto-charging of vehicles", "All of the given"], "a": 3, "s": ["All of the given options are indeed potential challenges as well. Refer Lecture 46@24:37."], "r": ""}, {"q": "What refers to combining information from multiple sensor sources?", "o": ["Information Collection", "Multi-sensor deployment", "Multi-sensor dissemination", "Multi-sensor data fusion"], "a": 3, "s": [""], "r": ""}, {"q": "Which of the following is one of the theory of evidence-based mathematical methods of data fusion?", "o": ["Belief function", "Bayesian analysis", "ANN", "None of these"], "a": 0, "s": ["Belief function is one of the theory of evidence-based mathematical methods of data fusion . (Please refer Lecture 47 @11:49)"], "r": ""}, {"q": "With respect to data fusion from multiple IoT sensors, does outlier data present with a challenge?", "o": ["No", "Yes"], "a": 1, "s": ["Refer Lecture 47@8:13."], "r": ""}, {"q": "Which of the following is a phase of ICV development?", "o": ["Based on 2G", "Based on 4G LTE", "Vehicles connected to cloud", "All of these"], "a": 3, "s": ["The phases of ICV development: Phase 1: Based on 2G, Phase 2: Based on 4G LTE, Phase 3: Vehicles connected to cloud (Please refer Lecture 50@12:28)"], "r": ""}, {"q": "With which of the following can the decision-making gap between the sensors and the actuators be bridged.", "o": ["SDN", "OpenStack Horizon", "Artificial Intelligence (AI)", "Arduino IDE"], "a": 2, "s": ["Refer Lecture 47@12:14 onwards."], "r": ""}, {"q": "Which of the following statements are true about the HAN standards? Statement I: Physical and MAC layers are defined by IEEE802.15.4. Statement II: Network layer is defined by Zigbee. Statement III: Application layer is defined by IEEE802.15.4", "o": ["Statements I and II", "Statements I and III", "Statements II and III", "Statements I, II and III"], "a": 0, "s": ["Physical and MAC layers are defined by IEEE802.15.4. Network layer and Application layers are defined by Zigbee. (Please refer Lecture 48@16:11)"], "r": ""}, {"q": "What is UPnP?", "o": ["Uninterrupted Post-messaging", "Universal Pull Streaming", "Universal Plug and Play", "Unhindered Public Networking"], "a": 2, "s": ["Refer Lecture 48@12:53."], "r": ""}, {"q": "What are the disadvantages of V2X communication?", "o": ["Increased traffic safety", "Tracking of movement", "Efficient use of fuel", "None of these"], "a": 1, "s": ["Disadvantages of V2X communication includes tracking of movement, violation of privacy, loss of data control, etc. (Please refer Lecture 50@21:04)"], "r": ""}, {"q": "Mobility of vehicles in a V2X environment limit which of the following that restricts the use of TCP/IP for V2X communication?", "o": ["Communication between vehicular infrastructure", "Localization of data", "Backbone routing in IP core networks", "Human-vehicle interaction"], "a": 1, "s": ["Detailed Answer: TCP/IP works best with localized data, which is not present in V2X environments. This restricts the use of TCP/IP for V2X communication. Refer Lecture 49@12:33 onward."], "r": ""}, {"q": "In VANET, link durations are long and easily scaled-up to include all the vehicles on the road?", "o": ["True", "False"], "a": 1, "s": ["Link durations are short due to the highly dynamic nature of VANETs. (Please refer Lecture 49 @18:00)"], "r": ""}, {"q": "CCN is derived from ICN architecture.", "o": ["True", "False"], "a": 0, "s": ["CCN (Content Centric Networking) is derived from Information Centric Networking (ICN) (Please refer Lecture 49@15:32)."], "r": ""}, {"q": "In an ICV environment, efficient cooperation between different vehicles on a highway can lead to a safer scenario with respect to collision and avoiding incoming traffic.", "o": ["True", "False"], "a": 0, "s": ["Refer Lecture 50@2:00."], "r": ""}]});
addSet('iot',202511,{"title": "", "label": "2025 · Week 11", "tag": "’25 W11", "group": "2025", "questions": [{"q": "Which among the following is the most probable application scenario for a smart grid?", "o": ["Home automation", "Hospital networks", "Intelligent power plants", "Crop monitoring"], "a": 2, "s": ["Refer Lecture 51@4:20."], "r": ""}, {"q": "With respect to a smart grid, which stakeholders are potentially benefitted?", "o": ["Energy Service providers", "Energy consumers/customers", "Both energy service provides and consumers", "Neither energy service providers nor consumers."], "a": 2, "s": ["Refer Lecture 51@13:20."], "r": ""}, {"q": "It is not possible to perform load forecasting using a smart grid.", "o": ["True", "False"], "a": 1, "s": ["Load forecasting is possible in a smart grid. Refer Lecture 51@22:00."], "r": ""}, {"q": "With respect to the following Smart Grid architecture, which among the following is the most probable utility of the IP network?", "o": ["IP network has no utility", "IP network is used to connect smart grid components globally for seamless data transfer", "IP network is used for multimedia video streaming only", "IP network is used to induce more congestion"], "a": 1, "s": [""], "r": "", "img": "assets/iot/2025-w11-q4-1.png"}, {"q": "Smart Home is an isolated concept and is not integrable with smart grid?", "o": ["False", "True"], "a": 0, "s": ["Refer Lecture 51@28:01"], "r": ""}, {"q": "Which of the following is a cloud application of smart grid?", "o": ["Information management", "Energy management", "Security", "All of these"], "a": 3, "s": ["Energy management, information management and security are all the cloud applications in smart grid (Please refer Lecture 52@21:55)"], "r": ""}, {"q": "Which of the following is not a vulnerability of Smart Grid?", "o": ["Integrity", "Physical threats", "Dynamic system attacks", "None of these"], "a": 3, "s": ["Integrity, physical threats and dynamic system attacks are all the vulnerabilities of smart grids (Please refer Lecture 52@16:56)"], "r": ""}, {"q": "IIoT corresponds to which industrial revolution?", "o": ["1st", "2nd", "3rd", "4th"], "a": 3, "s": ["Refer Lecture 53@10:00 onwards."], "r": ""}, {"q": "IIoT is inherently data intensive.", "o": ["Yes", "No"], "a": 0, "s": ["In IIoT, big data analytics plays an important part, hence it is inherently data intensive. Refer Lecture 53@16:28 onward."], "r": ""}, {"q": "Which among the following is one of the requirements and utility of IIoT?", "o": ["Power plant interruption", "Power plant virtualization", "Power plant decentralization", "Power plant denotification"], "a": 1, "s": ["Refer Lecture 53@20:17."], "r": ""}, {"q": "Smart Grid follows which type of flow of energy?", "o": ["Bidirectional", "Unidirectional", "Both a and b", "Neither a nor b"], "a": 0, "s": ["Smart grid follows bidirectional flow of energy. (Please refer Lecture 51@ 5 :4 1 )"], "r": ""}, {"q": "What is the Flow of data?", "o": ["Acquisition&gt;Generation&gt;Storage&gt;Analysis", "Generation&gt;Storage&gt;Analysis&gt;Acquisition", "Generation&gt;Acquisition&gt;Storage&gt;Analysis", "None of these"], "a": 2, "s": ["The flow of the data is Generation, Acquisition, Storage and Analysis ( Please refer Lecture 55@19:29)"], "r": ""}, {"q": "Intelligent transport system is least likely to render which of the following connectivity?", "o": ["Vehicle-to-vehicle connectivity", "Vehicle-to-sensor connectivity", "Vehicle-to-road infrastructure", "Vehicle-to-home connectivity"], "a": 3, "s": ["ITS provides Vehicle-to-vehicle connectivity, Vehicle-to-sensor connectivity, Vehicle-to-road infrastructure and Vehicle-to-internet connectivity. (Please refer Lecture 54@4:19)"], "r": ""}, {"q": "Approximately around ________ of the total data available currently in the world is unstructured.", "o": ["20 %", "40 %", "60 %", "80%"], "a": 3, "s": ["Unstructured data accounts for 80% of the total data available today in the world. (Please refer Lecture 55@9:23)"], "r": ""}, {"q": "SQL manages ________________ data.", "o": ["Unstructured", "Corrupt", "Structured", "Non-organized"], "a": 2, "s": ["Refer Lecture 55@8:56."], "r": ""}]});
addSet('iot',202512,{"title": "", "label": "2025 · Week 12", "tag": "’25 W12", "group": "2025", "questions": [{"q": "Qualitative analysis refers to the process by which numerical data is analyzed?", "o": ["True", "False"], "a": 1, "s": ["Refer Lecture 56@2:46."], "r": ""}, {"q": "Which of the following data analysis technique involve the use of study of difference of variance?", "o": ["ARIMA", "ANOVA", "DNN", "OpenFlow"], "a": 1, "s": ["Refer Lecture 56@10:42 onward."], "r": ""}, {"q": "Given that you have an independent variable and that you want to predict the dependent variable based on the relationship between the two variables. Which among the following technique would you use?", "o": ["ANOVA", "ARIMA", "Regression Analysis", "Pre-analysis"], "a": 2, "s": ["Refer Lecture 56@15:13 onwards."], "r": ""}, {"q": "With respect to AgriSens, how many logical layers are there in its architecture?", "o": ["Perception Layer", "Processing Layer", "Application Layer", "All of the given"], "a": 3, "s": [""], "r": ""}, {"q": "AgriSens supports real-time monitoring of soil moisture conditions and instant reporting to a dashboard.", "o": ["False", "True"], "a": 1, "s": ["Refer Lecture 57, practical AgriSens deployment."], "r": ""}, {"q": "What is the data aggregator is also known as in the context of IoT in smart healthcare?", "o": ["CPU", "LPU", "APU", "PPU"], "a": 1, "s": ["Refer Lecture 58@9:23."], "r": ""}, {"q": "Fill in the blanks. The effect size for determining statistical significance is the standardized _________ difference between two groups.", "o": ["Median", "Mean", "Inter quartile range", "None of the above"], "a": 1, "s": ["The effect size is the standardized mean difference between two groups. (Please refer lecture Data Handling and Analytics- Part II @ 17:15)"], "r": ""}, {"q": "Processing the sensed data on the device itself is known as __________ approach.", "o": ["Network based", "In-place", "Out of the place", "None of these"], "a": 1, "s": ["Processing the sensed data on the device itself is known as in-place approach. (Please refer lecture Activity monitoring Case Study - I @ 20:19)."], "r": ""}, {"q": "Fill in the blank. Processing the handheld activity device data with artificial intelligence can be used for ________.", "o": ["Fall detection", "Heart rate detection", "Vehicle detection", "All of these"], "a": 0, "s": ["Processing the handheld activity device data with artificial intelligence can be used for detecting sudden fall of a person. (Please refer Lecture 60@11:56)"], "r": ""}, {"q": "Which of the following is an assumption of ANOVA?", "o": ["Homogeneity of variances", "Normally distributed response variable", "Independence of observations", "All of these"], "a": 3, "s": ["ANOVA assumes the following: Homogeneity of variances: The variances within each group should be approximately equal. Normality: The response variable should follow a normal distribution within groups. Independence: Observations should be independent of each other. These assumptions are critical for the validity of ANOVA results. (Refer to Lecture 56 @ 12:30)."], "r": ""}, {"q": "Select the statement(s) that denote the type of ANOVA. Statement I: One way analysis Statement II: Two way analysis Statement III: K-way analysis", "o": ["Statement I", "Statement II", "Statements I, II, and III", "None of these"], "a": 2, "s": ["The types of ANOVA includes One way analysis, Two way analysis and K-way analysis (Please refer Lecture 56@11:57)"], "r": ""}, {"q": "AmbuSense is a privacy-aware system", "o": ["True", "False"], "a": 0, "s": ["The AmbuSense is a strictly privacy-aware system with patient-identity masking. (Please refer Lecture 58@24:12)"], "r": ""}, {"q": "The two most relevant sensors directly used in agriculture are __________.", "o": ["Soil moisture and ECG sensor", "Soil moisture and water level sensor", "ECG sensor and water level sensor", "All of these"], "a": 1, "s": ["Soil moisture and water level sensors are the necessary sensors generally used in agriculture. (Please refer Lecture 57@13:11)"], "r": ""}, {"q": "Examples of dispersion measures include _______ and ______.", "o": ["Discrete, categorical", "Continuous, quantitative", "Discrete, quantitative", "Range, Variance"], "a": 3, "s": ["Examples of dispersion measures include Range and Variance (Please"], "r": "refer Lecture 56@13:51)"}, {"q": "Suppose that your smartphone tilts by an angle of 15 degrees. Which among the following sensors will detect this tilt?", "o": ["HC-SR04", "Gyroscope", "Accelerometer", "Monometer"], "a": 1, "s": ["Refer Lecture 60@3:06."], "r": ""}]});
addSet('iot',202401,{"title": "", "label": "2024 · Week 1", "tag": "’24 W1", "group": "2024", "questions": [{"q": "Which of the following is/are the characteristics of IoT?", "o": ["Efficient, scalable and associated architecture.", "Unambiguous naming and addressing.", "Abundance of sleeping nodes, mobile and non-IP device.", "All of the these"], "a": 3, "s": ["Characteristics of IoT are – a. Efficient, scalable and associated architecture. b. Unambiguous naming and addressing. c. Abundance of sleeping nodes, mobile and non-IP device."], "r": "See lecture 1 (Introduction to IoT – Part - I) @ 16:06"}, {"q": "A ___________ allows us to use our smartphones to lock and unlock our door remotely at our homes or our businesses.", "o": ["Smart Meter", "ATM", "Digital Lock", "Web"], "a": 2, "s": ["Smartphones can be used to lock and unlock doors remotely, and business owners can change key codes rapidly to grant or restrict access to employees and guests."], "r": "See lecture 1 (Introduction to IoT – Part - I) @ 25:35"}, {"q": "The function/functions of an IoT Gateway is/are to?", "o": ["Forward packets between LAN and WAN and on the IP layer", "Connect IoT LAN to a WAN", "Both (a) and (b)", "None of these"], "a": 2, "s": ["An IoT Gateway is a router connecting the IoT LAN to a WAN to the Internet, can implement several LAN and WAN, Forwards packets between LAN and WAN and on the IP layer."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 04:44"}, {"q": "Multi-homing is the concept where a node can be connected to multiple networks for _________.", "o": ["Reduced Reliability", "Improved Reliability", "None of these", "Both (a) and (b)"], "a": 1, "s": ["Multi-homing is a concept where a node or an IoT device or a sub- network can be connected to multiple networks for improving the reliability."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 15:27"}, {"q": "A Passive Infrared Ray (PIR) sensor is used for ____________?", "o": ["Humidity Detection", "Tilt Detection", "Obstacle Detection", "Smoke Detection"], "a": 2, "s": ["Passive Infrared Ray (PIR) sensor can be used to detect if there is any obstacle."], "r": "See lecture 3 (Sensing) @ 04:13"}, {"q": "For which of the following, Vector Sensors are required to measure or sense them?", "o": ["Color, Pressure, Temperature", "Orientation, Image", "None of these", "Both (a) and (b)"], "a": 1, "s": ["Vector Sensors produce output signal or voltage which is generally proportional to the magnitude, direction, as well as the orientation of the quantity being measured. Physical quantities such as sound, image, velocity, acceleration, orientation, etc. are all vector quantities, as only their magnitude is not sufficient to convey the complete information."], "r": "See lecture 3 (Sensing) @ 16:14"}, {"q": "The sensitivity of a sensor under real conditions may differ from the value specified. This is called _____________?", "o": ["Maximal Error", "Minimal Error", "Median Error", "Sensitivity Error"], "a": 3, "s": ["The sensitivity of a sensor under real conditions may differ from the value specified. This is called sensitivity error."], "r": "See lecture 3 (Sensing) @ 19:33"}, {"q": "A random deviation of the signal that varies in time is called ____________.", "o": ["Noise", "Sound", "Bias", "None of these"], "a": 0, "s": ["Noise is a random deviation of the signal that varies in time."], "r": "See lecture 3 (Sensing) @ 22:42"}, {"q": "A Relay Switch is an example of _____________.", "o": ["A Sensor", "An Actuator", "A Transducer", "None of These"], "a": 1, "s": ["Relay Switch is an example of an actuator. It is an electromechanical switch that can be used to perform On/Off operations of electrical appliances."], "r": "See lecture 4 (Actuation) @ 01:37"}, {"q": "What is a Pneumatic Actuator?", "o": ["It is a type of actuator driven by compressed air or vacuum", "It is a type of actuator driven by fluid", "It is a type of actuator driven by solid", "None of these"], "a": 0, "s": ["A pneumatic actuator converts energy formed by vacuum or compressed air at high pressure into either linear or rotary motion."], "r": "See lecture 4 (Actuation) @ 07:55"}, {"q": "Which type of actuators tend to be compact, lightweight, economical, and with high power density?", "o": ["Thermal or Magnetic Actuators", "Hydraulic Actuators", "Both (a) and (b)", "None of these"], "a": 0, "s": ["Thermal or Magnetic Actuators can be actuated by applying thermal or magnetic energy. They tend to be compact, lightweight, economical, and with high power density."], "r": "See lecture 4 (Actuation) @ 11:46"}, {"q": "Polymer based actuators designed to handle fragile objects like fruit harvesting in agriculture or manipulating internal organs in biomedicine are called?", "o": ["Pneumatic Actuators", "Soft Actuators", "Software Actuators", "Hardware Actuators"], "a": 1, "s": ["Soft Actuators are polymer-based actuators designed to handle fragile objects like fruit harvesting in agriculture or manipulating internal organs in biomedicine."], "r": "See lecture 4 (Actuation) @ 14:55"}, {"q": "Full form of SMP is _______________________?", "o": ["Soft Memory Polymer", "Shape Memory Polymer", "Software Memory Polymer", "None of these"], "a": 1, "s": ["Shape Memory Polymer (SMP) actuators function similar to our muscles, even providing a response to a range of stimuli such as light, electrical, magnetic, heat, pH, and moisture changes."], "r": "See lecture 4 (Actuation) @ 15:16"}, {"q": "Duty Cycling of the sensors is managed by which component of IoT?", "o": ["Application", "Real-Time Kernel", "Radios", "Power Management Unit"], "a": 3, "s": ["Power Management Unit does things like duty cycling of sensors that is how much time they are to be powered on and how much time they will be off."], "r": "See lecture 5 (Basics of IoT Networking – Part - I) @ 13:39"}, {"q": "Which of the following are challenges of IoT", "o": ["Security", "Complexity Management", "Modeling and Analysis", "All of these"], "a": 3, "s": ["IoT Challenges are –<br>• Security<br>• Modeling and Analysis<br>• Complexity Management<br>• Scalability<br>• Energy Efficiency<br>• Interfacing<br>• Interoperability<br>• Data Storage<br>• Data Analytics"], "r": "See lecture 5 (Basics of IoT Networking – Part - I) @ 24:40"}]});
addSet('iot',202402,{"title": "", "label": "2024 · Week 2", "tag": "’24 W2", "group": "2024", "questions": [{"q": "Which of the following is based on the publish-subscribe model?", "o": ["MQTT", "HTTP", "HTTPS", "All of these"], "a": 0, "s": ["Message Queue Telemetry Transport (MQTT) is a publish-subscribe based lightweight messaging protocol for use in conjunction with TCP/IP protocol."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 01:51"}, {"q": "In MQTT, a topic to which a client is subscribed is updated in the form of messages and distributed by the ____________________?", "o": ["Publishers", "Message Broker", "Subscribers", "All of these"], "a": 1, "s": ["A topic to which a client is subscribed is updated in the form of messages and distributed by the message broker."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 03:33"}, {"q": "Which of the following is used when more than one level needs to be subscribed, such as the entire sub-tree, i.e., a multilevel wildcard?", "o": ["+", "#", "\\", "None of these"], "a": 1, "s": ["If more than one level needs to be subscribed, such as the entire sub- tree, there is also a multilevel wildcard (#). It allows to subscribe to all underlying hierarchy levels. For example house/# is subscribing to all topics beginning with house."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 12:40"}, {"q": "The CoAP protocol is designed for -.", "o": ["Heavy Web Application", "Publish-Subscribe Applications", "Machine-to-Machine (M2M) applications", "Both (a) and (b)"], "a": 2, "s": ["CoAP – Constrained Application Protocol. It is a web transfer protocol for use with constrained nodes and networks. Designed for Machine-to-Machine (M2M) applications such as smart energy and building automation. Based on Request-Response model between end-points."], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 00:35"}, {"q": "Statement I – The messaging sub-layer of CoAP, is responsible for reliability and duplication of messages. Statement II – The request/response sub-layer is responsible for communication. Which of the above statement/statements is/are correct?", "o": ["Only Statement I", "Only Statement II", "Both Statement I and II", "Statement I Correct but Statement II Incorrect"], "a": 2, "s": ["The messaging sub-layer of CoAP, is responsible for reliability and duplication of messages while the request/response sub-layer is responsible for communication."], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 04:19"}, {"q": "Which of the following is a messaging mode in CoAP?", "o": ["Append", "Substitute", "Attempt", "Separate"], "a": 3, "s": ["CoAP has four messaging modes<br>• Confirmable<br>• Non-Confirmable<br>• Piggyback<br>• Separate"], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 05:29"}, {"q": "Which of the following provides for the discovery of services residing locally or across a network?", "o": ["Internet", "SMQTT", "XMPP", "CoAP"], "a": 2, "s": ["XMPP provides for the discovery of services residing locally or across a network, and the availability information of these services."], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 12:03"}, {"q": "AMQP is a protocol of which layer?", "o": ["Transport Layer", "Application Layer", "Network Layer", "Session Layer"], "a": 1, "s": ["AMQP is an Application Layer protocol."], "r": "See lecture 8 (Basics of IoT Networking – Part IV) @ 01:41"}, {"q": "Which of the following is NOT a feature of the AMQP protocol?", "o": ["Closed Standard", "Security", "Reliability", "Routing"], "a": 0, "s": ["Features of AMQP are –<br>• Security<br>• Reliability<br>• Interoperability<br>• Routing<br>• Queuing<br>• Open Standard"], "r": "See lecture 8 (Basics of IoT Networking – Part IV) @ 04:54"}, {"q": "There are a total of _________ number of AMQP frame types are defined that are used to initiate, control, and tear down the transfer of messages between two peers.", "o": ["Seven", "Eight", "Nine", "None of these"], "a": 2, "s": ["Nine AMQP frame types are defined that are used to initiate, control, and tear down the transfer of messages between two peers."], "r": "See lecture 8 (Basics of IoT Networking – Part IV) @ 06:34"}, {"q": "The function/functions of the Queue component of the AMQP protocol is/are -", "o": ["Receive messages and route them to queues", "Separate queues for separate business process", "Consumer receive messages from queues", "Both (b) and (c)"], "a": 3, "s": ["The functions of the Queue components are to –<br>• Separate queues for separate business process<br>• Consumer receive messages from queues"], "r": "See lecture 8 (Basics of IoT Networking – Part IV) @ 08:05"}, {"q": "Which of the following statements is/are false? Statement – I: IEEE 802.15.4 is a well-known standard for low data-rate Wireless Personal Area Network (WPAN). Statement – II: IEEE 802.15.4 standard operates in the ISM band.", "o": ["Statement - II", "Statement - I", "Both Statement I and II", "None of these"], "a": 3, "s": ["IEEE 802.15.4 is a well known standard for low data-rate Wireless Personal Area Network (WPAN). It operates in the ISM band."], "r": "See lecture 9 (Connectivity Technologies – Part-I) @ 03:00"}, {"q": "The IEEE 802.15.4 establishes functionalities in which layers?", "o": ["Application and Session Layers", "Transport and Data Link Layers", "Network and Session Layers", "Physical and Data Link Layers"], "a": 3, "s": ["The IEEE 802.15.4 is useful for establishing functionalities in the Physical and Data Link Layers."], "r": "See lecture 9 (Connectivity Technologies – Part-I) @ 17:27"}, {"q": "Which is not a purpose of the ZigBee Device Object (ZDO)?", "o": ["Device Management", "Interfacing and Control Services", "Security", "Policies"], "a": 1, "s": ["The functions of the ZigBee Device Object (ZDO) are –<br>• Device Management<br>• Security<br>• Policies"], "r": "See lecture 9 (Connectivity Technologies – Part-I) @ 18:06"}, {"q": "State whether the following statement is True or False. Statement: Similar to traditional barcodes and QR codes, RFID tag data cannot be read outside the line-of-sight.", "o": ["False", "True"], "a": 0, "s": ["As compared to traditional barcodes and QR codes, RFID tag data can be read outside the line-of-sight."], "r": "See lecture 10 (Connectivity Technologies – Part-II) @ 17:33"}]});
addSet('iot',202403,{"title": "", "label": "2024 · Week 3", "tag": "’24 W3", "group": "2024", "questions": [{"q": "Choose the correct option based on the following two statements on the HART Physical Layer. Statement-I: It is derived from the IEEE 802.15.4 protocol. Statement-II: It operated only in the 2.4 GHz ISM band.", "o": ["Statement-I True and Statement-II False", "Statement-I False and Statement-II True", "Both Statements I and II are False", "Both Statements I and II are True"], "a": 3, "s": ["HART Physical Layer is derived from the IEEE 802.15.4 protocol. It operated in the 2.4 GHz ISM band."], "r": "See lecture 11 (Connectivity Technologies-III) @ 05:44"}, {"q": "Which of the following characteristic of HART Data Link Layer helps to increase reliability and security?", "o": ["Channel Hopping and Channel Blacklisting", "Channel Crunching and Jamming", "Scattering", "All of these"], "a": 0, "s": ["HART Data Link Layers incorporates channel hopping and channel blacklisting to increase reliability and security."], "r": "See lecture 11 (Connectivity Technologies-III) @ 06:23"}, {"q": "State True or False Statement: Channel blacklisting in HART identifies channels consistently affected by interference and removes them from use.", "o": ["True", "False"], "a": 0, "s": ["Channel blacklisting in HART identifies channels consistently affected by interference and removes them from use."], "r": "See lecture 11 (Connectivity Technologies-III) @ 08:27"}, {"q": "At the MAC layer – Statement-I: WirelessHART utilizes Time Division Multiple Access (TDMA). Statement-II: ZigBee applies Carrier Sense Multiple Access with Collision Detection (CSMA/CD).", "o": ["Statement-I True and Statement-II False", "Statement-I False and Statement-II True", "Both Statements I and II are False", "Both Statements I and II are True"], "a": 3, "s": ["At the MAC layer, WirelessHART utilizes Time Division Multiple Access (TDMA), allotting individual time slots for each transmission. ZigBee applies Carrier Sense Multiple Access with Collision Detection (CSMA/CD)."], "r": "See lecture 11 (Connectivity Technologies-III) @ 15:07"}, {"q": "NFC works on the principal of", "o": ["Pressure", "Magnetic Induction", "Both (a) and (b)", "None of these"], "a": 1, "s": ["NFC works on the principle of magnetic induction."], "r": "See lecture 11 (Connectivity Technologies-III) @ 20:02"}, {"q": "Bluetooth technology is based on Ad-hoc technology also known as?", "o": ["Ad-hoc Piconets", "Ad-hoc Micronets", "Ad-hoc Nanonets", "None of these"], "a": 0, "s": ["Bluetooth technology is based on Ad-hoc technology also known as Ad- hoc Piconets."], "r": "See lecture 12 (Connectivity Technologies-IV) @ 04:05"}, {"q": "Class 2 Bluetooth radios have a range of about?", "o": ["1 m", "2 m - 5 m", "10 m", "None of these"], "a": 2, "s": ["Class 2 radios are most commonly found in mobile devices and have a range of 10 meters."], "r": "See lecture 12 (Connectivity Technologies-IV) @ 05:16"}, {"q": "Which of the following is NOT a phase in Bluetooth connection establishment?", "o": ["Inquiry", "Booking", "Paging", "Connection"], "a": 1, "s": ["The three phases of Bluetooth connection establishment are –<br>• Inquiry<br>• Paging<br>• Connection"], "r": "See lecture 12 (Connectivity Technologies-IV) @ 05:33"}, {"q": "Zwave can support ___________ number of nodes in a network?", "o": ["232", "233", "234", "235"], "a": 0, "s": ["In Zwave, mesh network topology is the main mode of operation, and can support 232 nodes in a network."], "r": "See lecture 13 (Connectivity Technologies-V) @ 03:54"}, {"q": "Topologies allowed in ISA 100.11A are?", "o": ["Ring Only", "Mesh and Hybrid", "Mesh and Ring", "Mesh and Star/Tree"], "a": 3, "s": ["The ISA 100.11A support the Mesh and Star/Tree topologies."], "r": "See lecture 13 (Connectivity Technologies-V) @ 15:44"}, {"q": "An example of an Operating System (OS) that a sensor node can have is?", "o": ["MicronOS", "TinyOS", "Both (a) and (b)", "None of these"], "a": 1, "s": ["Sensor nodes can have OS such as TinyOS."], "r": "See lecture 14 (Sensor Networks-I) @ 12:06"}, {"q": "Which of the following is NOT a constraint on sensor nodes?", "o": ["Must consume extremely low power", "Be non-autonomous", "Be adaptive to environment", "None of these"], "a": 1, "s": ["Constraints on sensor nodes –<br>• Must consume extremely low power<br>• Be autonomous<br>• Be adaptive to the environment"], "r": "See lecture 14 (Sensor Networks-I) @ 14:36"}, {"q": "Nodes in WSNs that exhibit features of failed nodes but they can also send false routing messages which are a threat to the integrity of the network are called?", "o": ["Normal Nodes", "Badly Failed Nodes", "Failed Nodes", "Selfish Nodes"], "a": 1, "s": ["Nodes in WSNs that exhibit features of failed nodes but they can also send false routing messages which are a threat to the integrity of the network are called Badly Failed Nodes."], "r": "See lecture 15 (Sensor Networks-II) @ 03:53"}, {"q": "Which of the following are the two popular schemes to re-establish the connectivity between dumb nodes with others?", "o": ["CoARD and CoRD", "CoRAD and CoARD", "CoRD and CoRAD", "None of these"], "a": 2, "s": ["CoRD and CoRAD are the two popular schemes to re-establish the connectivity between dumb nodes with others."], "r": "See lecture 15 (Sensor Networks-II) @ 09:20"}, {"q": "Full form of WBAN is?", "o": ["Wireless Body Area Network", "Wirelessed Body Area Network", "Wireless Bodily Area Network", "None of these"], "a": 0, "s": ["Wireless Body Area Network (WBAN)."], "r": "See lecture 15 (Sensor Networks-II) @ 21:21"}]});
addSet('iot',202404,{"title": "", "label": "2024 · Week 4", "tag": "’24 W4", "group": "2024", "questions": [{"q": "When an intruder enters into the agricultural field through the boundary (perimeter) of the field, a/an ___________ sensor can be used to detect the object and a/an _____________ sensor can be used to sense the distance at which the object is located.", "o": ["PIR, Ultrasonic", "Ultrasonic, PIR", "Humidity, PIR", "None of these"], "a": 0, "s": ["When an intruder enters into the agricultural field through the boundary (perimeter) of the field, a PIR sensor can be used to detect the object and an Ultrasonic sensor can be used to sense the distance at which the object is located."], "r": "See lecture 16 (Sensor Networks-III) @ 15:40"}, {"q": "____________ is defined as, all the nodes are connected in the network, so that sensed data can reach to sink node?", "o": ["Coverage", "Connectivity", "Both (a) and (b)", "None of these"], "a": 1, "s": ["Connectivity is defined as, all the nodes are connected in the network, so that sensed data can reach to sink node."], "r": "See lecture 17 (Sensor Networks-IV) @ 02:14"}, {"q": "The objective of coverage in WSN is.", "o": ["To use a minimum number of sensors and maximize the network lifetime", "To use a maximum number of sensors and maximize the network lifetime", "To use a minimum number of sensors and minimize the network lifetime", "To use a maximum number of sensors and minimize the network lifetime"], "a": 0, "s": ["The objective of coverage is to use a minimum number of sensors and maximize the network lifetime."], "r": "See lecture 17 (Sensor Networks-IV) @ 08:48"}, {"q": "State True or False Statement-I: If transmission range ≤ 2* sensing range, coverage implies connectivity.", "o": ["Statement-I is True", "Statement-I is False"], "a": 1, "s": ["If transmission range ≥ 2* sensing range, coverage implies connectivity."], "r": "See lecture 17 (Sensor Networks-IV) @ 05:46"}, {"q": "A mobile entity that collects the data from sensor nodes goes to the sink, and delivers the collected data from different sensor nodes are called?", "o": ["Data Molecule", "Static Node", "Data Mules", "None of these"], "a": 2, "s": ["A mobile entity that collects the data from sensor nodes goes to the sink, and delivers the collected data from different sensor nodes are called Data Mules."], "r": "See lecture 18 (Sensor Networks-V) @ 07:11"}, {"q": "Human-centric Sensing is possible because of?", "o": ["Smartphone and PDAs", "Miniaturization and Proliferation of devices", "Both (a) and (b)", "None of these"], "a": 2, "s": ["Human-centric Sensing is possible because of Smartphone, PDAs, Miniaturization, and Proliferation of devices."], "r": "See lecture 18 (Sensor Networks-V) @ 10:51"}, {"q": "Which of the following are the roles played by humans in Human-centric Sensing?", "o": ["Sensing Targets", "Sensor Operators", "Data Source", "All of these"], "a": 3, "s": ["The three distinct roles (not necessarily mutually exclusive) played by humans are –<br>• Sensing Targets<br>• Sensor Operators<br>• Data Source"], "r": "See lecture 18 (Sensor Networks-V) @ 12:35"}, {"q": "Which of the following is/are NOT goal of Participatory Sensing?", "o": ["To only collect data", "Not just collect data, but allow common people to access data and share knowledge", "To only access data", "Both (a) and (c)"], "a": 3, "s": ["The goal of Participatory Sensing is not just collect data, but allow common people to access data and share knowledge."], "r": "See lecture 18 (Sensor Networks-V) @ 13:00"}, {"q": "The two popular network topologies in UAV networks are", "o": ["Ring", "Mesh and Star", "Bus", "All of these"], "a": 1, "s": ["The two popular network topologies in UAV networks are Mesh and Star topologies."], "r": "See lecture 19 (UAV Networks) @ 03:26"}, {"q": "Which of the following is NOT an issue in UAV networks?", "o": ["Slow change in network topology", "Malfunctioning of UAVs", "Intermittent link nature", "Relative position of UAV may change"], "a": 0, "s": ["Key issues in UAV networks are –<br>• Frequently change in network topology<br>• Relative position of UAV may change<br>• Malfunctioning of UAV<br>• Intermittent link nature"], "r": "See lecture 19 (UAV Networks) @ 05:23"}, {"q": "The scalability in single UAV system as compared to multi-UAV system is?", "o": ["Limited", "High", "Very High", "None of these"], "a": 0, "s": ["The scalability in single UAV system as compared to multi-UAV system is limited."], "r": "See lecture 19 (UAV Networks) @ 07:47"}, {"q": "Typical types of mesh networks in UAV networks are", "o": ["Solid Mesh and Hierarchical Mesh", "Plane Mesh and Solid Mesh", "Flat Mesh and Hierarchical Mesh", "None of these"], "a": 2, "s": ["Typical types of mesh networks in UAV networks are –<br>• Flat Mesh<br>• Hierarchical Mesh"], "r": "See lecture 19 (UAV Networks) @ 12:48"}, {"q": "State True or False Statement-I: SCADA is designed for isolated systems using proprietary solutions, whereas M2M is designed for cross-platform integration.", "o": ["False", "True"], "a": 1, "s": ["SCADA is designed for isolated systems using proprietary solutions, whereas M2M is designed for cross-platform integration."], "r": "See lecture 20 (Machine to Machine Communication) @ 5:25"}, {"q": "Which of the following is NOT a feature of M2M?", "o": ["Large number of nodes or devices", "High cost", "Energy efficient", "Small traffic per machine/device"], "a": 1, "s": ["Features of M2M –<br>• Large number of nodes or devices<br>• Low cost<br>• Energy efficient<br>• Small traffic per machine/device"], "r": "See lecture 20 (Machine to Machine Communication) @ 9:24"}, {"q": "Which of the following is NOT an M2M node type?", "o": ["Low End Node", "High End Node", "Out End Node", "None of these"], "a": 2, "s": ["The three node types of M2M are –<br>• Low end node<br>• Mid end node<br>• High end node"], "r": "See lecture 20 (Machine to Machine Communication) @ 10:35"}]});
addSet('iot',202405,{"title": "", "label": "2024 · Week 5", "tag": "’24 W5", "group": "2024", "questions": [{"q": "Suppose that an IoT sensor node A works on wireless WiFi and senses pressure as a physical parameter in integer number, and another IoT node B operates on IEEE 802.15.4 Zigbee and senses humidity as a floating point (decimal) number. In this context, which among the following correctly describes the issues with the deployment.", "o": ["Heterogeneity", "Interoperability", "Both heterogeneity and interoperability", "Neither heterogeneity and interoperability"], "a": 2, "s": ["Since the two sensors sense different parameters in different formats and communicates with different protocols, this is an issue of both heterogeneity and interoperability. Refer lecture 21 on"], "r": ""}, {"q": "RESTful web services are utilized for _________.", "o": ["Syntactic interoperability for device interaction", "Semantic interoperability for device interaction", "Both (a) and (b)", "None of the above"], "a": 0, "s": ["Service-oriented computing-based architecture, RESTful web services, open standard protocols (IEEE 802.15.4), and closed protocols (Z-wave) are the popular approaches utilized towards syntactic interoperability for device interaction."], "r": "See lecture 21 @ 17:40"}, {"q": "Which UMB interoperability component is responsible for converting physical devices into virtually abstracted ones?", "o": ["UMB Adaptor", "UMB Core", "UMB Hypervisor", "UMB Abstractor"], "a": 0, "s": ["UMB-A is responsible for converting physical devices into virtually abstracted ones. (Please refer Lecture 21@27:16)"], "r": ""}, {"q": "User interoperability is the interoperability problem between an user and ____________.", "o": ["Another user", "Device", "Both user and device", "None of these"], "a": 1, "s": ["In user interoperability, the issue of interoperability is between the user and device."], "r": "Refer lecture 21, ppt No. 7, types of interoperability"}, {"q": "Which of the following is an open, global, multi-sector standard for efficient, accurate, flexible classification of products and services?", "o": ["eCl@ss", "UNSPSC", "EPC", "Both UNSPSC and EPC"], "a": 1, "s": ["UNSPC stands for United Nations Standard Products and Services Code. It is one of the device classification solutions. eCl@ss is the standard utilized for classification and clear description of cross-industry products. Electronic Product Code (EPC) is used to generate unique addresses for device identification. See lecture 21 @ 16:30"], "r": ""}, {"q": "What does the routing component in UMB-C use for routing the metadata messages?", "o": ["Flow Table", "Routing Table", "Middleware Routing Table", "Middleware Flow Table"], "a": 2, "s": ["UMB-C uses Middleware Routing Table for routing metadata messages among the devices. (Please refer Lecture 21@28:16)"], "r": ""}, {"q": "Which among the following are components of an Arduino UNO Board?", "o": ["LED Power Indicator", "Digital I/O Pins", "Analog IN Pins", "All of these"], "a": 3, "s": ["An Arduino UNO board contains several components, which also contain the ones listed above. Refer lecture 22 on Arduino Board details."], "r": ""}, {"q": "The tool used to select a particular COM port for connecting Arduino to a serial connector is called a sketch.", "o": ["True", "False"], "a": 1, "s": ["Sketch in Arduino is the program that is coded in Arduino IDE. Refer lecture 22, ppt No. 9"], "r": ""}, {"q": "Which kind of conflict occur when different processing logic are applied to same IoT networked devices or applications?", "o": ["Semantic conflict.", "Syntactic conflict.", "System conflict.", "Device conflict."], "a": 0, "s": ["Semantic conflict occurs when different processing logics are applied to same IoT networked devices or applications. See lecture 21@5:20"], "r": ""}, {"q": "Which of the following is TRUE for the sketch command given below? delay(3000);", "o": ["Provides a delay of 3000 seconds", "Provides a delay of 3 seconds", "Provides a delay of 3000 nano seconds", "Provides a delay of 3000 simulation time"], "a": 1, "s": ["As per the basics of Arduino programming."], "r": ""}, {"q": "How many types of loops will you find in Arduino Programming?", "o": ["1", "2", "3", "4"], "a": 2, "s": ["Like C programming, Arduino sketches also have 3 types of loops, for, while and do- while loops."], "r": ""}, {"q": "How many digital I/O pins are there in Arduino Uno.", "o": ["14", "54", "11", "16"], "a": 0, "s": ["From the basics of Arduino Uno.Refer to the book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT. Cambridge University Press."], "r": ""}, {"q": "Servo motors that you connect to Arduino, are an example of", "o": ["Sensors", "Actuators", "Gateways", "Routers"], "a": 1, "s": ["Servo motors, along with other different types of motors are examples of Actuators in IoT network. Refer lecture 25 on Integration of Arduino with Sensors and Actuators."], "r": ""}, {"q": "Which of the following functions exist by default in Arduino IDE?", "o": ["main()", "loop() and main()", "setup() and loop()", "setup() and main()"], "a": 2, "s": ["By default Arduino IDE consists of 2 functions - setup() and loop(). See lecture 22 @ 10:40"], "r": ""}, {"q": "Choose the right option for if/conditional operator.", "o": ["Val = (condition)?(Statement 1):(Statement 2)", "Val = (condition)?(Statement 2):(Statement 1)", "Val = (condition):(Statement 1)?(Statement 2)", "Val = (condition):(Statement 2)?(Statement 1)"], "a": 0, "s": ["Conditional operator may also be written as Val = (condition)?(Statement 1):(Statement 2). (Please refer Lecture 23@2:01)"], "r": ""}]});
addSet('iot',202406,{"title": "", "label": "2024 · Week 6", "tag": "’24 W6", "group": "2024", "questions": [{"q": "Python’s installation comes with an integrated development environment for programming.", "o": ["True", "False"], "a": 0, "s": ["As per Python program. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I @ 3:40)"], "r": ""}, {"q": "Fill in the blanks. Python IDE is available for installation into PC with __________.", "o": ["Windows", "Linux", "Mac", "All of these"], "a": 3, "s": ["As per Python program. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I @ 4:50)"], "r": ""}, {"q": "How many data type/s are available in Python?", "o": ["1", "2", "5", "None of these"], "a": 2, "s": ["As per Python program (Please refer to lecture INTRODUCTION TO RASPBERRY PI-I @ 9:00)."], "r": ""}, {"q": "What is the output of the following piece of Python code? ls= {1: \"abc\", \"key\": \"2\", \"year\": 2023} print(ls[\"key\"]", "o": ["abc", "2", "2023", "“abc\""], "a": 1, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "The variable that is declared inside the function in Python is called a Global variable.", "o": ["True", "False"], "a": 1, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "Which of the following is used to read a text file in Python?", "o": ["file = open('data.txt ', 'r ')", "file = open_text('data.txt ', 'r ')", "file = read_text('data.txt ', 'r ')", "file = read('data.txt ', 'r ')"], "a": 0, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "Which of the following libraries in Python is used for processing images.", "o": ["Pillow", "Numpy", "Panda", "None of these"], "a": 0, "s": ["In python programming PIL, OpenCV, Pillow are common image processing libraries. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- II @ 18:08 )"], "r": ""}, {"q": "In python, images cannot be converted to greyscale.", "o": ["True", "False"], "a": 1, "s": ["As per the basics of Python programming (Please refer to lecture"], "r": ""}, {"q": "Which of the following shortcut exits the nano editor?", "o": ["Ctrl + E", "Ctrl + O", "Ctrl+V", "None of these"], "a": 3, "s": ["Ctrl + O writes the code to a file. Ctrl + X exits the nano editor."], "r": "See lecture 29"}, {"q": "Which of the following is an unordered data type in Python?", "o": ["List", "Dictionary", "Both List and Dictionary", "Tuple"], "a": 1, "s": ["As per basics of Python programming."], "r": "See lecture 26 @ 15:36"}, {"q": "Sensors can be analog or digital. Is the statement true?", "o": ["Yes", "No"], "a": 0, "s": ["Sensors can be analog or digital. See lecture 30 @ 03:27"], "r": ""}, {"q": "Is relay a type of mechanical switch?", "o": ["No", "Yes"], "a": 1, "s": ["Relay is a type of mechanical/electromechanical switch. See lecture 30 @ 05:53"], "r": ""}, {"q": "Which of the following converts energy to motion?", "o": ["Actuator", "Raspberry Pi", "Sensor", "None of these"], "a": 0, "s": ["Actuator converts energy to motion."], "r": "See lecture 30 @ 03:37"}, {"q": "Python does not follow strict indentation.", "o": ["True", "False"], "a": 1, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "Functions cannot be reassigned to the variables in Python.", "o": ["True", "False"], "a": 1, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}]});
addSet('iot',202407,{"title": "", "label": "2024 · Week 7", "tag": "’24 W7", "group": "2024", "questions": [{"q": "The switches in a non-Software Defined Network (SDN) environment do not have a global view of the network.", "o": ["True", "False"], "a": 0, "s": ["Switches in non-SDN do not have global view of the network. (Please refer Lecture 33@6:53)"], "r": ""}, {"q": "Which of the following is not a function of the Application Plane in Software Defined Network architecture?", "o": ["Business Logic implementation", "Security", "Traffic Engineering", "Forwarding"], "a": 3, "s": ["The Data Plane in SDN is responsible for data forwarding. (Please refer Lecture 33@12:25)"], "r": ""}, {"q": "In Socket programming, the parameter AF_INET stands for ___________.", "o": ["Unix protocols", "Internet Protocol (IP)", "File sharing", "Time slicing"], "a": 1, "s": ["The AF_INET specifies the rules and standards of the Internet protocol, hence the socket acts as an IP socket. (Please refer Lecture 31@14:13)"], "r": ""}, {"q": "During remote server access by a Raspberry Pi, where the Raspberry Pi acts as a client, the client needs the following?", "o": ["Only IP address of server", "Only port number", "Both server IP address and port number", "Client’s IP address"], "a": 2, "s": ["A client can communicate with a server only if both IP address and port numbers are known. (Please refer Lecture 31@14:13)"], "r": ""}, {"q": "Fill in the blank: Controllers in SDN receive requests from the _______________.", "o": ["Repeaters", "Gateways", "Switches", "Routers"], "a": 2, "s": ["SDN controllers should be able to handle all requests from the SDN switches (Please"], "r": "refer Lecture 34@2:41)"}, {"q": "During remote server access using socket programming what is the utility of the &lt;socket_name&gt;.listen() function?", "o": ["To create a new socket", "To bind the socket to connection", "To wait for clients to connect", "To close the connection"], "a": 2, "s": ["listen() function makes the server wait for incoming client connections (Refer Lecture 31 ppt no 13)"], "r": ""}, {"q": "With respect to client-server model of socket programming, in which of the following does the function &lt;socket_name&gt;.bind() reside?", "o": ["Client", "Server", "Both client and server", "None of client and server"], "a": 1, "s": ["The bind() function binds the socket name to the socket connection at the server side (Refer lecture 31 on socket programming)"], "r": ""}, {"q": "Which among the following are valid data processing activities", "o": ["Data Splitting", "Data filtering", "Data plotting", "All of the given"], "a": 3, "s": ["As per the basics of Python programming (Please refer to lecture"], "r": ""}, {"q": "Which among the following is the correct direction for PACKET_IN type messages in SDN?", "o": ["From controller to switch", "From switch to controller", "Between two switches", "Between two controllers"], "a": 1, "s": ["PACKET_IN messages are sent from switches to the controller upon receipt of new unknown packets. Refer lecture 33, ppt no 20."], "r": ""}, {"q": "Suppose a particular flow-rule has a soft time-out of 5s and a hard time-out of 3s. Is this association correct?", "o": ["Yes", "No"], "a": 1, "s": ["Hard time-outs of flow rules are always greater than soft time-outs, not the other way round. Refer lecture 33, OpenFlow Protocol III"], "r": ""}, {"q": "In SDN Backup Controllers are required for which among the following?", "o": ["To act as backup of the main controller all the time", "To act as backup when the main controller fails", "To replace the main controller all together", "None of the stated."], "a": 1, "s": ["Backup controllers acts as backup when the main controller is down Refer lecture 34."], "r": ""}, {"q": "Which of the following is true?", "o": ["Traditional Network: Routing Table, Software Defined Network: Routing Table", "Traditional Network: Flow Table, Software Defined Network: Routing Table", "Traditional Network: Routing Table, Software Defined Network: Flow Table", "Traditional Network: Flow Table, Software Defined Network: Flow Table"], "a": 2, "s": ["All switches in traditional network have routing tables and those in Software Defined Network have flow tables (Please refer Lecture 33@17:15)"], "r": ""}, {"q": "What are the benefits of using SDN over IoT?", "o": ["Management of device heterogeneity", "Management of end-device mobility and dynamic flow rules", "Software control of end-devices, i.e sensors and actuators", "All of the given"], "a": 3, "s": ["SDN over IoT can be used to solve a plethora of issues and problems in a dynamic and efficient manner. Refer lecture 35, SDN over IoT"], "r": ""}, {"q": "Sensor OpenFlow, Soft-WSN and SDN-WISE are examples of ____________.", "o": ["Traditional routing protocols.", "Various SDN protocols for wired LANs", "Various implementations of the concept of Software Defined IoT", "Traditional IoT protocol examples."], "a": 2, "s": ["The given names are all examples of various implementations of different concepts of Software Defined IoT by various research groups across the world. (Please refer Lecture 35@8:46 onwards)"], "r": ""}, {"q": "Consider the following python script using the split() function, what will be the correct print output (SEE the options VERY carefully including the quotation marks) dat = 'Apple,Guava#Banana' var = dat.split(‘#’) print(var)", "o": ["['Apple','Guava','Banana']", "['Apple','Guava']", "['Guava','Banana']", "['Apple,Guava','Banana']"], "a": 3, "s": ["The split(‘#’) method splits the string into two parts with respect to the ‘#’ character. (Please refer Lecture 32@8:02)"], "r": ""}]});
addSet('iot',202408,{"title": "", "label": "2024 · Week 8", "tag": "’24 W8", "group": "2024", "questions": [{"q": "Which among the following are core challenges of traditional mobile networks?", "o": ["Scalability", "Flexibility", "Manageability", "All of the given"], "a": 3, "s": ["Traditional mobile networks suffer from a lot of problems, few of which are as given in the options. Refer lecture 36, Traditional (Wireless) Mobile Network"], "r": ""}, {"q": "Network virtualization enables ______________ of physical resources", "o": ["Movement", "Abstraction", "Removal", "Creation"], "a": 1, "s": ["Abstraction of physical resources from network services is one of the core functionality of virtualization. Refer lecture 36, ppt No. 5"], "r": ""}, {"q": "In comparison to Software-Defined Networks, traditional networks are cost expensive with respect to which of the following?", "o": ["Both capex and opex", "Capex but not opex", "Opex but not capex", "Neither capex nor opex"], "a": 0, "s": ["Detailed Answer: Traditional networks are cost expensive with respect to both capex and opex in comparison to SDN. (Please refer Lecture 36@2:46)"], "r": ""}, {"q": "General OpenFlow supports both wireless and wired connections.", "o": ["True", "False"], "a": 1, "s": ["Detailed Answer: A modified OpenFlow is necessary for supporting wireless connections. (Please refer Lecture 36@8:18)"], "r": ""}, {"q": "With respect to Software Defined Data Centre Networking (SD-DCN), ____________ can use wild cards and _________________ uses exact match rules.", "o": ["Mice flows, Elephant flows", "Elephant flows, Mice flows", "Mice flows, traditional flows", "Traditional flows, Elephant flows"], "a": 0, "s": ["Refer to ppt No. 19 of lecture 36 on Data Centre Networking"], "r": ""}, {"q": "In cloud computing model, which among the following are characteristics of computing resources?", "o": ["On-demand", "Shared", "Configurable", "All of these"], "a": 3, "s": ["“Cloud computing is a model for enabling convenient, on-demand network access to a shared pool of configurable computing resources (e.g., network infrastructures, servers, storage, applications, etc.)” – NIST. Refer Lecture 37, Introduction to Cloud Computing."], "r": ""}, {"q": "Iaas, PaaS and SaaS are examples of what type of cloud models?", "o": ["Cloud deployment model", "Cloud service model", "Cloud access model", "Cloud virtualization model"], "a": 1, "s": ["Iaas, PaaS and SaaS are three major types of cloud service models. Refer lecture 37, Introduction to Cloud Computing"], "r": ""}, {"q": "An organization A wants to deploy a cloud infrastructure, whereby it wants to push majority of the data to a cloud whose servers can be situated anywhere within the globe, but it wants certain private data to be pushed only to cloud servers that are present on-premise and are accessible by only authenticated members of the organization. In this context which among the following deployment model should be used?", "o": ["Private Cloud", "Public Cloud", "Hybrid Cloud", "Any of these"], "a": 2, "s": ["Hybrid cloud deployment model supports both the features of public and private cloud. Refer lecture 37, ppt No. 18."], "r": ""}, {"q": "Which of the following type of client requires constant communication/connection with the cloud server?", "o": ["Thin client", "Thick client", "Both thin and thick clients", "None of these"], "a": 0, "s": ["Detailed Answer: A thin client is a network computer without a hard disk drive and high configurations. They act as simple terminals and require constant communication with the servers. (Please refer Lecture 37@20:00)"], "r": ""}, {"q": "Fill in the blank: Typically, cloud computing have _____ components?", "o": ["4", "5", "6", "7"], "a": 2, "s": ["Detailed Answer: Cloud computing has 6 components. They are clients, services, applications, platforms, storage, and infrastructure. (Please refer Lecture 37@23:31)"], "r": ""}, {"q": "What does ‘CIA’ in cloud data security stand for?", "o": ["Confidentiality, Integrity, Availability", "Confidentiality, Inheritance, Automation", "Congestion, Integrity, Authentication", "Criticality, Integrity, Accountability"], "a": 0, "s": ["‘CIA’ stands for ‘Confidentiality, Integrity and Availability’. (Please refer Lecture 39@21:01)"], "r": ""}, {"q": "In SaaS model of cloud computing, which of the following acts as the thin-client?", "o": ["Cloud gateway", "Web monitor", "Web browser", "Local firewall"], "a": 2, "s": ["Web browsers at the client side act as thin-clients which makes connection to the cloud to receive the services provided by the SaaS model. Refer lecture 38 on SaaS, ppt No. 21."], "r": ""}, {"q": "Data in __________ and Data at _______________ are two important aspects of data security", "o": ["past, present", "time, place", "transit, rest", "None of these"], "a": 2, "s": ["Data in transit and Data at rest are two important aspects of data security within cloud computing framework. Refer lecture 39 on Data Security, ppt No. 18"], "r": ""}, {"q": "Which among the following is a metric for Service Level Agreement (SLA) in Cloud Computing?", "o": ["Availability", "Portability", "Response Time", "All of these"], "a": 3, "s": ["Availability, Portability, Response Time, Problem Reporting and Penalty are various SLA metrics for Cloud Computing. Refer Chapter 10 (Page 245) of “Introduction to IoT” by Sudip Misra, Anandarup Mukherjee, Arijit Roy, Cambridge University Press."], "r": ""}, {"q": "Which of the following cloud computing models does AWS EC2 belong to?", "o": ["IaaS", "PaaS", "SaaS", "None of these"], "a": 0, "s": ["AWS EC2 is a popular example of IaaS."], "r": ""}]});
addSet('iot',202409,{"title": "", "label": "2024 · Week 9", "tag": "’24 W9", "group": "2024", "questions": [{"q": "Openstack is a free open source software for cloud framework simulation and experimentation with various cloud applications.", "o": ["True", "False"], "a": 0, "s": ["Openstack is a free open source software for cloud framework simulation and experimentation with various cloud applications. It can be downloaded and installed for free. Refer Lecture 41."], "r": ""}, {"q": "Which among the following is NOT a component of OpenStack.", "o": ["Horizon", "Heat", "Plasma", "Neutron"], "a": 2, "s": ["Plasma is not a component of OpenStack. The rest are various components, including Nova, Glance, Swift etc. Refer lecture 41, ppt No. 4"], "r": ""}, {"q": "You cannot ping your OpenStack instance from an outside network unless you connect your instance with the public network through a ____________", "o": ["Router", "Firewall", "Repeater", "Load balancer"], "a": 0, "s": ["You are supposed to connect your virtual OpenStack instance with the public network through a router (Please refer Lecture 41@17:41)"], "r": ""}, {"q": "Virtualized resources within the OpenStack simulator that you can define, set parameters of and deploy within OpenStack are also known as", "o": ["Instances", "Files", "Hypervisors", "Sketches"], "a": 0, "s": ["In OpenStack instances refer to the virtual resources that you define, initialize and deploy. Refer Lecture 41@15:36"], "r": ""}, {"q": "The SCSP in sensor clouds is responsible for caching the data in the databases.", "o": ["True", "False"], "a": 0, "s": ["Detailed Answer: The SCSP in sensor clouds is responsible for caching the data in the databases. (Please"], "r": "refer Lecture 42@14:25)"}, {"q": "Select the correct option for replacing the box (in red) in the following architecture for sensor cloud user organization view.", "o": ["User credentials", "Template display", "Template view", "User view"], "a": 2, "s": ["The browser interface sends template view and sensed information to the user organization module in the sensor cloud user organization view. (Please refer Lecture 42@15:16)"], "r": "", "img": "assets/iot/2024-w9-q6-1.png"}, {"q": "Which among the following is the principal feature of sensor clouds, with respect to sensor nodes?", "o": ["Sensor monitoring", "Sensor instantiation", "Sensor virtualization", "Sensor collection"], "a": 2, "s": ["Sensor virtualization is the principal feature of sensor clouds and their utility."], "r": "Refer lecture 42 and 43 on Sensor cloud"}, {"q": "Caching in sensor cloud provide no benefit over regions with slow environmental monitoring rate.", "o": ["True", "False"], "a": 1, "s": ["To prevent unnecessarily energy wastage in continuous sensing operation, sensor cloud uses caching. Refer lecture 42 and 43."], "r": ""}, {"q": "How many different types of caching mechanism are there in sensor cloud?", "o": ["1", "4", "2", "3"], "a": 2, "s": ["Detailed Answer: Internal Cache (IC) and External Cache (EC) are two different types of caching mechanisms used in sensor cloud. Refer lecture 43, ppt No. 13"], "r": ""}, {"q": "Virtual sensors within a sensor cloud have communication interfaces with _______________.", "o": ["Only the physical sensors below them", "Only the end-user applications above them.", "Both physical sensors below and applications above.", "Neither the physical sensors, nor the applications above."], "a": 2, "s": ["Virtual sensor layer sits in the middle having interface to both physical sensors as well as applications. (Please refer Lecture 3@9:24 and 28:01)"], "r": ""}, {"q": "Data from an IoT device is transferred to cloud via a network, which is then processed at the cloud and then a response is sent back to the IoT device from the cloud after processing. The time it takes for one-way data transfer between the node and cloud is 10s and the data processing time at the cloud is ‘x’ seconds. It takes a total of 25s for the entire to and fro transfer of data between the sensor and cloud along with processing at the cloud. What is the value of x?", "o": ["10s", "5s", "15s", "20s"], "a": 1, "s": ["Time taken for one-way data transfer between the node and cloud is 10s. Total time taken for the data transfer is 25s. So 25=10+x+10 (transfer from node to cloud+processing at cloud+transfer from cloud to node). Thus x = 5s."], "r": ""}, {"q": "In IoT, temporal sensitivity of data plays an important role", "o": ["True", "False"], "a": 0, "s": ["IoT data can be classified in to time sensitive data, less time sensitive data and data not sensitive to time. Hence time sensitivity plays a big role in IOT data classification. Refer lecture 44 on Fog Computing."], "r": ""}, {"q": "Extremely time sensitive data in IoT should be processed and analyzed ____________.", "o": ["Farthest away from source", "Closest to the source", "Distance between source and place of analysis does not matter", "None of these"], "a": 1, "s": ["Extremely time sensitive data should be processed and analyzed closest to the source, so that prompt action can be taken immediately. Refer lecture 44 on Fog Computing, ppt No. 17."], "r": ""}, {"q": "Which among the following is a view of a Fog Computing Architecture?", "o": ["Node View", "System View", "Software View", "All of these"], "a": 3, "s": ["Fog Computing Architectural framework has several views, node, system and software among them. Refer Chapter 11 (Page 260 - 263) of “Introduction to IoT” by Sudip Misra, Anandarup Mukherjee, Arijit Roy, Cambridge University Press."], "r": ""}, {"q": "Which among the following is true?", "o": ["Fog computing acts as a complement to cloud computing.", "Fog computing is a replacement for cloud computing.", "Fog computing and cloud computing are the same.", "Fog computing is more powerful than cloud computing (with respect to resources)."], "a": 0, "s": ["Fog computing and cloud computing are complementary technologies. Fog helps in bringing the cloud closer to the IoT devices. (Please refer Lecture 45@1:06)"], "r": ""}]});
addSet('iot',202410,{"title": "", "label": "2024 · Week 10", "tag": "’24 W10", "group": "2024", "questions": [{"q": "A smart city _____________.", "o": ["Is an urban system", "Uses ICT", "Makes infrastructure more reliable", "All of these"], "a": 3, "s": ["A smart city is an urban system, uses ICT and makes infrastructure more reliable. (Please refer Lecture 46@8:29)"], "r": ""}, {"q": "Collective data is more intelligent than the single sources.", "o": ["True", "False"], "a": 0, "s": ["Collective data is rich in information and generates better intelligence than the single sources. (Please refer Lecture 47@10:18)"], "r": ""}, {"q": "Which of the following is one of the challenges of Data fusion?", "o": ["Imperfection", "Conflicts", "Ambiguity", "All of these"], "a": 3, "s": ["The challenges of data fusion involves Imperfection, Conflicts and Ambiguity. (Please refer Lecture 47@9:16)"], "r": ""}, {"q": "Which of the following are challenges for IoT in smart cities?", "o": ["Security and Reliability", "Small scale", "Homogeneity", "None of these"], "a": 0, "s": ["Security and Reliability are two challenges of IoT in smart cities. (Please refer Lecture 46 @32:28)"], "r": ""}, {"q": "Fill in the blank. ___________ combines information from multiple sensors.", "o": ["Data storage", "Data cleaning", "Data fusion", "None of these"], "a": 2, "s": ["Data fusion combines information from multiple sensors. (Please"], "r": "refer Lecture 47 @6:36)"}, {"q": "Which of the following are the functional layers in smart parking?", "o": ["Information collection", "System Deployment", "Service Dissemination", "All of these"], "a": 3, "s": ["Information collection, System Deployment and Service Dissemination are the three functional layers in smart parking (Please refer Lecture 47@17:25)"], "r": ""}, {"q": "Which of the following statements are true about the different components present in a smart home? Statement I: Sensor networks and communication network infrastructure Statement II: Intelligent control and management Statement III: Manual instead of automatic access of devices", "o": ["Statements I and II", "Statements I and III", "Statements II and III", "Statements I, II and III"], "a": 0, "s": ["The different components of smart home include communication network infrastructure, Intelligent control and management, Sensor networks, smart features and automatic response. (Please refer Lecture 48@7:04)"], "r": ""}, {"q": "Which of the following are included in the Service Dissemination in smart parking? Statement I: Dynamic Pricing Statement II: Infrastructure-free and infrastructure-based information Statement III: Parking Choice", "o": ["Statement I and II", "Statement II and III", "Statement I and III", "Statement I, II and III"], "a": 3, "s": ["Service Dissemination in smart parking includes Dynamic Pricing, parking choice and infrastructure- free information and infrastructure-based information. (Please refer Lecture 47@19:07)"], "r": ""}, {"q": "Fill in the blank. ____________ is a network contained within a home.", "o": ["Local area network", "Home area network", "Personal area network", "Metropolitan area network"], "a": 1, "s": ["Home area network is a network contained within a home (Please"], "r": "refer Lecture 48@8:38)"}, {"q": "Fill in the blank. In Vehicle-to-Human / Human-to-Vehicle interaction, the human communicating with the vehicle ____________.", "o": ["Is present in another vehicle", "Is present in the same vehicle", "Is present outside the vehicle on the roadside", "All of these"], "a": 2, "s": ["In V2H/H2V, the human is present outside the vehicle on the roadside. (Please refer Lecture 49@3:13)"], "r": ""}, {"q": "Wired HAN provides easy integration with pre-existing house infrastructure.", "o": ["True", "False"], "a": 0, "s": ["Wired HAN provides easy integration with pre-existing house infrastructure like existing telephone systems, cables and so on (Please refer Lecture 48@10:20)"], "r": ""}, {"q": "Which of the following statement(s) is/are true about Konnex?", "o": ["Utilizes only short ranges in home", "Can be used before configuration", "Does not have standards for building networks", "None of these"], "a": 3, "s": ["The Konnex is an important standard for home and building networks. It utilizes full range of home communication. It must be setup and configured before its proper usage (Please refer Lecture 48@14:41)"], "r": ""}, {"q": "Which of the following is the reason for failures of TCP/IP in V2X?", "o": ["TCP/IP handles information exchange between multiple pair of entities", "The increase in the number of wireless devices restricts the mobility", "TCP/IP can identify the addresses of the endpoints", "Information exchange does not depend on the location of the data"], "a": 1, "s": ["The increase in the number of wireless devices restricts the mobility is one of the reasons of the failures of TCP/IP in V2X (Please refer Lecture 49@13:09)"], "r": ""}, {"q": "CCN is derived from ICN architecture.", "o": ["True", "False"], "a": 0, "s": ["CCN (Content Centric Networking) is derived from Information Centric Networking (ICN) (Please refer Lecture 49@15:32)"], "r": ""}, {"q": "What are the disadvantages of V2X communication?", "o": ["Increased traffic safety", "Tracking of movement", "Efficient use of fuel", "None of these"], "a": 1, "s": ["Disadvantages of V2X communication includes tracking of movement, violation of privacy, loss of data control, etc. (Please refer Lecture 50@21:04)"], "r": ""}]});
addSet('iot',202411,{"title": "", "label": "2024 · Week 11", "tag": "’24 W11", "group": "2024", "questions": [{"q": "Which of the following is not done in traditional electrical grids?", "o": ["Manual energy monitoring", "Unidirectional energy distribution", "Unidirectional communication", "Distributed power plants"], "a": 3, "s": ["In Traditional electrical grids, the energy generation is done in centralized power plants. (Please refer Lecture 51@5:45)"], "r": ""}, {"q": "Smart Grid is also named as—", "o": ["Electronet", "Energy service", "Grid with a brain", "Smart internet"], "a": 0, "s": ["Electronet is another name for smart grids (Please refer Lecture 51@7:41)"], "r": ""}, {"q": "Which of the following is not a property of smart grids?", "o": ["Bidirectional flow of energy", "Two-way communication", "Unreliable and insecure electricity", "Control Capabilities"], "a": 2, "s": ["Smart Grids uses information technology to deliver electricity efficiently, reliably and securely (Please refer Lecture 51@7:41)"], "r": ""}, {"q": "Which of the following is the benefit of using Smart Grids for stakeholders?", "o": ["Reduces inefficiencies in energy delivery", "Different pricing options", "Lower Energy bills", "All of these"], "a": 0, "s": ["The smart grids reduce inefficiencies in energy delivery. This is one of the benefits for stakeholders. The other benefits are for the customers (Please refer Lecture 51 @18:28)"], "r": ""}, {"q": "Fill in the blank. ___________ samples voltage and current with a fixed sample rate at the installed location.", "o": ["PEVs", "DAUs", "PMUs", "None of these"], "a": 2, "s": ["PMUs or Phasor Measurement Unit samples voltage and current with a fixed sample rate at the installed location (Please refer Lecture 52 @2:44)"], "r": ""}, {"q": "Which of the following is a cloud application of smart grid?", "o": ["Information management", "Energy management", "Security", "All of these"], "a": 3, "s": ["Energy management, information management and security are all the cloud applications in smart grid (Please refer Lecture 52@21:55)"], "r": ""}, {"q": "Which of the following statements are true about MDMSs? Statement I: Decide the price per unit energy to be paid by the customers Statement II: Handled by the energy service providers Statement III: Aggregate the energy consumption or energy request of certain geographical area", "o": ["Statements I and II", "Statements I and III", "Statements II and III", "Statements I, II and III"], "a": 0, "s": ["The Meter Data Management Systems (MDMS) decide the price per unit energy to be paid by the customers AND are handled by the energy service providers. (Please refer Lecture 52@16:02)"], "r": ""}, {"q": "Which of the following are included in the Smart Grid security issues of integrity? Statement I: System Damage Statement II: Data injection attacks Statement III: Time synchronization attacks", "o": ["Statement I and II", "Statement II and III", "Statement I and III", "Statement I, II and III"], "a": 3, "s": ["System Damage, data injection attacks and time synchronization attacks are the types of integrity issues in Smart Grids (Please refer Lecture 52@18:55)"], "r": ""}, {"q": "Fill in the blank. ____________ is a primary challenge in IIoT.", "o": ["Worker health and safety", "Optimized operations", "Regulatory compliance", "Integrating existing infrastructure into new IIoT infrastructure"], "a": 3, "s": ["Integrating existing infrastructure into new IIoT infrastructure is one of the primary challenges of IIoT. (Please refer Lecture 54@14:02)"], "r": ""}, {"q": "Fill in the blank. Rt Tech particularizes in software which____________.", "o": ["Improves industrial facilities’ efficiency", "Improves productivity", "Automates managing of energy consumption", "All of these"], "a": 3, "s": ["Rt Tech improves industrial facilities efficiency and productivity. It automates the process of mapping and managing energy consumption (Please refer Lecture 54@20:30)"], "r": ""}, {"q": "Lack of vision and leadership is not a hindrance in the path of success of IIoT.", "o": ["True", "False"], "a": 1, "s": ["Lack of vision and leadership is one of the hindrances in the path of success of IIoT. (Please refer Lecture 54@18:44)"], "r": ""}, {"q": "Which of the following is not a vulnerability of Smart Grid?", "o": ["Integrity", "Physical threats", "Dynamic system attacks", "None of these"], "a": 3, "s": ["Integrity, physical threats and dynamic system attacks are all the vulnerabilities of smart grids (Please refer Lecture 52@16:56)"], "r": ""}, {"q": "Which of the following is a characteristic of Big Data?", "o": ["Veracity", "Variability", "Velocity", "All of these"], "a": 3, "s": ["Big Data is characterized by 7 Vs, Veracity, Variability and Velocity included (Please refer Lecture 55@10:41)"], "r": ""}, {"q": "Variety refers to the category to which the data belongs.", "o": ["True", "False"], "a": 0, "s": ["Variety refers to the category to which the data belongs. Examples: Pure text, images, audio, etc. (Please refer Lecture 55@12:58)"], "r": ""}, {"q": "What is the Flow of data?", "o": ["Acquisition&gt;Generation&gt;Storage&gt;Analysis", "Generation&gt;Storage&gt;Analysis&gt;Acquisition", "Generation&gt;Acquisition&gt;Storage&gt;Analysis", "None of these"], "a": 2, "s": ["The flow of the data is Generation, Acquisition, Storage and Analysis (Please"], "r": "refer Lecture 55@19:29)"}]});
addSet('iot',202412,{"title": "", "label": "2024 · Week 12", "tag": "’24 W12", "group": "2024", "questions": [{"q": "Quantitative analysis does not involve descriptive statistics such as mean.", "o": ["True", "False"], "a": 1, "s": ["Quantitative analysis involves descriptive statistics such as mean, median and standard deviation. (Please refer Lecture 56@4:26)"], "r": ""}, {"q": "Fill in the blank. To perform an ANOVA, we must have a _______ response variable and at least one _____ factor.", "o": ["Discrete, categorical", "Continuous, quantitative", "Discrete, quantitative", "Continuous, categorical"], "a": 3, "s": ["To perform an ANOVA, we must have a continuous response variable and at least one categorical factor. (Please refer Lecture 56@9:24)"], "r": ""}, {"q": "Select the statement(s) that denote the example of dispersion measure. Statement I: Range, Variable and Standard deviation Statement II: Range and average absolute deviation Statement III: Variance, Standard deviation and average absolute deviation", "o": ["Statement I", "Statement II", "Statements I, II and III", "None of these"], "a": 2, "s": ["The example of dispersion measure includes Range, Variable and Standard deviation and average absolute deviation (Please refer Lecture 56@13:36)"], "r": ""}, {"q": "The different components of AgriSens includes –", "o": ["Sensor and actuator unit", "Wireless communication unit", "Power management unit", "All of these"], "a": 3, "s": ["The different components of AgriSens includes sensor and actuator unit, wireless communication unit, and power management unit. (Please refer Lecture 57@7:44)"], "r": ""}, {"q": "The two most relevant sensors directly used in agricultures are __________.", "o": ["Soil moisture and proximity sensor", "Soil moisture and water level sensor", "ECG sensor and water level sensor", "All of these"], "a": 1, "s": ["Soil moisture and water level sensors are the necessary sensors generally used in agriculture. (Please refer Lecture 57@13:11)"], "r": ""}, {"q": "The sensor node of AgriSens sense the average soil moisture in ______________.", "o": ["Vegetative phase", "Reproductive phase", "Maturity phase", "All of these"], "a": 3, "s": ["The sensor node of AgriSens sensed the average soil moisture in vegetative phase, reproductive phase and maturity phase (Please refer Lecture 57@18:33)"], "r": ""}, {"q": "Select the correct order of the component layers present in the IoT healthcare.", "o": ["Sensing layer, cloud platform layer, aggregated layer, processing layer", "Sensing layer, aggregated layer, processing layer, cloud platform layer", "Aggregated layer, sensing layer, processing layer, cloud platform layer", "Sensing layer, processing layer, aggregated layer, cloud platform layer"], "a": 1, "s": ["The sensing layer senses data and transmit it o the aggregation layer where the data are aggregated. The aggregated layer further transfers the data to the processing layer the data are processed and final sent to the cloud platform. (Please refer Lecture 58@8:25)"], "r": ""}, {"q": "Which of the following communication protocol is used in AmbuSens?", "o": ["IEEE 802.15.4", "6LoWPAN", "IEEE 802.15.1", "IEEE 802.15.2"], "a": 2, "s": ["In AmbuSens, the communication protocol used is Bluetooth i.e., IEEE 802.15.1 (Please refer Lecture 58@22:09)"], "r": ""}, {"q": "Wireless IoT driven solutions for remote healthcare facility provisioning brings healthcare to patients than bringing patients to healthcare.", "o": ["True", "False"], "a": 0, "s": ["In IoT healthcare, wireless IoT driven solutions brings healthcare to patients than bringing patients to healthcare. (Please refer Lecture 58@11:40)"], "r": ""}, {"q": "Fill in the blank. The physical activity tracking is a necessary component for _____________.", "o": ["Activity monitoring", "Vehicle monitoring", "Agriculture monitoring", "All of these"], "a": 0, "s": ["The physical activity tracking is a necessary component for activity monitoring (Please refer Lecture 59@6:39)"], "r": ""}, {"q": "Which of the following handheld devices are used for activity monitoring?", "o": ["EEG and GPS", "Accelerometer and EEG", "Accelerometer and GPS", "All of these"], "a": 2, "s": ["High end smartphones are likely to have accelerometer, compass, and gyroscope. (Please refer Lecture 59@15:29)"], "r": ""}, {"q": "Which of the following is the primary disadvantage of using camera-based activity tracking?", "o": ["Accurate", "Process intensive", "Expensive", "None of these"], "a": 1, "s": ["Camera based activity tracking is very much process intensive. (Please refer Lecture 59@17:43)"], "r": ""}, {"q": "By performing continuous monitoring of a person’s activity, it is not possible to observe his/her behavior or to identify any repetitive pattern in his/her day-to-day activity.", "o": ["True", "False"], "a": 1, "s": ["Continuous monitoring of activity results in daily observations of human behavior and repetitive patterns in their activity. (Please refer Lecture 59@14:33)"], "r": ""}, {"q": "Which of the following are the inbuilt sensors that are present in high end smartphones?", "o": ["ECG and EEG", "Accelerometer, proximity sensor, and EEG", "Accelerometer, Compass and Gyroscope", "Pressure sensor and NPK sensor"], "a": 2, "s": ["High end smartphones are likely to have accelerometer, compass, and gyroscope. (Please refer Lecture 60@2:28)"], "r": ""}, {"q": "Fill in the blank. Processing the handheld activity device data with artificial intelligence can be used for ________.", "o": ["Fall detection", "Heart rate detection", "Vehicle detection", "All of these"], "a": 0, "s": ["Processing the handheld activity device data with artificial intelligence can be used for detecting sudden fall of a person. (Please refer Lecture 60@11:56)"], "r": ""}]});
addSet('iot',202300,{"title": "", "label": "2023 · Week 0", "tag": "’23 W0", "group": "2023", "questions": [{"q": "Which of the following allows us to identify objects and extract information?", "o": ["RFID", "Sensors", "Actuators", "IoT Nodes"], "a": 0, "s": ["RFID Technology allows us to automatically identify and track tags that are attached to the objects. It extracts information from the tags through electromagnetic fields."], "r": "See lecture 1 @ 12:57"}, {"q": "How many layers does Zigbee consist of?", "o": ["1", "2", "3", "4"], "a": 3, "s": ["Zigbee consists of 4 layers: Physical, Medium Access Control, Network, and Application."], "r": "See lecture 48 @ 16:11"}, {"q": "Which of the following is not a component of cloud computing?", "o": ["Clients", "Local Servers", "Services", "Applications"], "a": 1, "s": ["Cloud computing components include clients, services, applications, platform, storage, and infrastructure."], "r": "See lecture 37 @ 23:29"}, {"q": "Which of the following is a distance measuring sensor module?", "o": ["DHT22", "HC-SR04", "TSL2591", "HC-SR505"], "a": 1, "s": ["HC-SR04 is the distance measuring module ultrasonic sensor, which measures the distance between 2cm~450cm."], "r": "See lecture 3 @ 5:00"}, {"q": "Which of the following is a component in a typical sensor network?", "o": ["Sink", "Gateway", "Router", "All of these"], "a": 3, "s": ["A typical sensor network comprises of sensor nodes, routers, gateway, and sink."], "r": ""}, {"q": "Which of the following sensors are responsible for measuring orientation and angular velocity?", "o": ["Accelerometer", "GPS", "Temperature", "None of these"], "a": 3, "s": ["A gyroscope is responsible for measuring orientation and angular velocity."], "r": "See lecture 59 @ 15:41"}, {"q": "“ISA 100.11A” is a wireless networking technology standard. ISA stands for _______.", "o": ["International Society of Automation", "International Society of Advancement", "Industrial Society of Automation", "Industrial Society of Advancement"], "a": 0, "s": ["ISA100.11a is a wireless networking technology standard developed by the International Society of Automation (ISA)."], "r": "See lecture 13@ 15:55"}, {"q": "Which of the following is not a difference between traditional data center and cloud computing?", "o": ["Scalability", "Flexibility", "Elasticity", "Storage"], "a": 3, "s": ["Major differences between traditional data center and cloud computing include scalability, flexibility, elasticity, automation, running costs, and security"], "r": "See lecture 39 @ 11:02"}, {"q": "Smart grid is also known as the energy internet.", "o": ["True", "False"], "a": 0, "s": ["Smart grid is also known as the energy internet."], "r": "See lecture 51 @ 7:51"}, {"q": "Can a point of node failure result in the partition of the network in the stationary sensor network?", "o": ["Yes", "No"], "a": 0, "s": ["If there is a failure in the stationary sensor network then it is likely that the point of failure can partition the network into two or more fragments."], "r": "See lecture 18 @ 01:10"}]});
addSet('iot',202301,{"title": "", "label": "2023 · Week 1", "tag": "’23 W1", "group": "2023", "questions": [{"q": "Which of the following are the enablers of IoT?", "o": ["RFID", "Nanotechnology", "Sensors", "All of the these"], "a": 3, "s": ["The enablers of IoT are – a. RFID b. Nanotechnology c. Sensors"], "r": "See lecture 1 (Introduction to IoT – Part - I) @ 12:41"}, {"q": "Which of the following is/are NOT a characteristic of IoT?", "o": ["Efficient, scalable and associated architecture.", "Ambiguous naming and addressing.", "Abundance of sleeping nodes, mobile and non-IP devices.", "None of these"], "a": 1, "s": ["The characteristics of IoT are – a. Efficient, scalable and associated architecture b. Unambiguous naming and addressing c. Abundance of sleeping nodes, mobile and non-IP devices"], "r": "See lecture 1 (Introduction to IoT – Part - I) @ 16:02"}, {"q": "State whether the following statement is True or False. Statement: The increasing number of devices in IoT is expected to result in an address crunch.", "o": ["True", "False"], "a": 0, "s": ["The increasing number of devices in IoT is expected to result in an address crunch."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 01:19"}, {"q": "State whether the following statement is True or False. Statement: The gateway has a unique network prefix, which can be used to identify them globally.", "o": ["True", "False"], "a": 0, "s": ["The gateway has a unique network prefix, which can be used to identify them globally."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 6:58"}, {"q": "Sometimes, when there is a need for the nodes to communicate directly to the Internet, ______________ can be used.", "o": ["Sensors", "Actuators", "Tunneling", "None of these"], "a": 2, "s": ["Sometimes,there is a need for the nodes to communicate directly to the Internet. This is achieved by tunneling."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 11:44"}, {"q": "In _______________ a node/network is connected to multiple networks for improved reliability.", "o": ["Transparent roaming", "Multi-homing", "None of these", "Both (a) and (b)"], "a": 1, "s": ["In multi-homing, a node/network is connected to multiple networks for improved reliability."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 15:22"}, {"q": "The IPv6 notation uses ___________________ values.", "o": ["Roman", "Hexadecimal", "Both (a) and (b)", "None of these"], "a": 1, "s": ["The IPv6 notation uses hexadecimal values."], "r": "See lecture 2 (Introduction to IoT – Part - II) @ 16:33"}, {"q": "A _____________ detects (senses) changes in the ambient conditions or in the state of another device or a system, and forwards or processes this information in a certain manner.", "o": ["Sensor", "Actuator", "Both (a) and (b)", "None of these"], "a": 0, "s": ["A sensor detects (senses) changes in the ambient conditions or in the state of another device or a system, and forwards or processes this information in a certain manner.."], "r": "See lecture3 (Sensing) @ 03:17"}, {"q": "A microphone is an example of an _____________.", "o": ["Input device and actuator", "Only actuator", "Only Transducer", "Input device and transducer"], "a": 3, "s": ["A microphone is an example of an input device and transducer."], "r": "See lecture 3 (Sensing) @ 10:31"}, {"q": "The ________________ of a sensor is the smallest change it can detect in the quantity that it is measuring.", "o": ["Resolution", "Bias", "Noise", "None of these"], "a": 0, "s": ["The resolution of a sensor is the smallest change it can detect in the quantity that it is measuring. ."], "r": "See lecture 3 (Sensing) @ 12:33"}, {"q": "Based on the data type, sensors are classified as _______________________.", "o": ["Scalar and Vector/Multimedia", "Only scalar", "Both (a) and (b)", "Only vector"], "a": 0, "s": ["Based on the data type, sensors are classified as Scalar and Vector/Multimedia."], "r": "See lecture 3 (Sensing) @ 13:05"}, {"q": "Solenoid valve is an example of ______________________.", "o": ["Sensor", "Actuator", "Processing unit", "None of these"], "a": 1, "s": ["Solenoid valve is an example of actuator."], "r": "See lecture 4 (Actuation) @ 02:49"}, {"q": "An actuator requires a ______________________ and ______________________.", "o": ["Control signal and a bias signal", "Control signal and a source of energy", "Noise signal and a source of energy", "None of these"], "a": 1, "s": ["An actuator requires a control signal and source of energy."], "r": "See lecture 4 (Actuation) @ 03:50"}, {"q": "State whether the following statement is True or False. Statement: Pneumatic rack and pinion actuators are used for valve controls of water pipes.", "o": ["True", "False"], "a": 0, "s": ["Pneumatic rack and pinion actuators are used for valve controls of water pipes. See lecture 4 (Actuation)@ 07:52"], "r": ""}, {"q": "Which of the following is NOT a function of an IoT gateway?", "o": ["Switching", "Routing", "Protocol conversion", "Generating noise"], "a": 3, "s": ["Switching, routing, and protocol conversion are the functions of an IoT gateway."], "r": "See lecture 5 (Basics of IoT Networking – Part - I) @ 19:27"}]});
addSet('iot',202302,{"title": "", "label": "2023 · Week 2", "tag": "’23 W2", "group": "2023", "questions": [{"q": "The full form of MQTT is", "o": ["Message Queue Telemetry Transport", "Message Query Telemetry Transport", "Message Queue Telemedicine Transport", "None of these"], "a": 0, "s": ["The full form of MQTT is Message Queue Telemetry Transport."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 01:51"}, {"q": "In MQTT, a ________________ controls the publish-subscribe messaging pattern.", "o": ["Publishers", "Message Broker", "Subscribers", "All of these"], "a": 1, "s": ["In MQTT, a message broker controls the publish-subscribe messaging pattern.."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 03:33"}, {"q": "Which of the following is NOT a component of MQTT?", "o": ["Publishers", "Users", "Brokers", "None of these"], "a": 1, "s": ["The three components of MQTT are – a) Publishers b) Subscribers c) Brokers"], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 04:50"}, {"q": "______________ is an extension of MQTT which uses lightweight attribute based encryption. It has ___________ main stages.", "o": ["SMQTT, three", "BMQTT, three", "SMQTT, four", "None of these"], "a": 2, "s": ["SMQTT is an extension of MQTT which uses lightweight attribute based encryption. It has four main stages."], "r": "See lecture 6 (Basics of IoT Networking – Part II) @ 13:45"}, {"q": "Which of the following is based on Request-Response model between end-points.", "o": ["MQTT", "CoAP", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 1, "s": ["CoAP is based on Request-Response model between end-points."], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 00:31"}, {"q": "The two sub-layers of CoAP are -", "o": ["Messaging and Holding", "Messaging and Backoff", "Messaging and Teardown", "Messaging and Request/response"], "a": 3, "s": ["CoAP has two sub-layers which are – a) Messaging b) Request/response"], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 04:44"}, {"q": "Which of the following is used for real-time exchange of structured data?", "o": ["MQTT", "SMQTT", "XMPP", "CoAP"], "a": 2, "s": ["XMPP is used for real-time exchange of structured data."], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 11:28"}, {"q": "XMPP uses the ________________ architecture.", "o": ["Publish-subscribe", "Client-server", "Both (a) and (b)", "Neither (a) nor (b)"], "a": 1, "s": ["XMPP uses the client-server architecture."], "r": "See lecture 7 (Basics of IoT Networking – Part III) @ 12:03"}, {"q": "With respect to AMQP, which of the following message delivery guarantees allow for each message to be delivered certainly as well as to be delivered multiple times.", "o": ["At-least-once", "At-most-once", "Exactly-once", "Both (a) and (b)"], "a": 0, "s": ["The message delivery guarantees of AMQP are –<br>• At-most-once – each message is delivered once or never.<br>• At-least-once – each message is certain to be delivered, but may do so multiple times.<br>• Exactly-once – message will always certainly arrive and do so only once."], "r": "See lecture 8 (Basics of IoT Networking – Part IV) @ 05:35"}, {"q": "Which of the following is/are NOT an AMQP frame type?", "o": ["Open", "Close", "End", "None of these"], "a": 3, "s": ["Open, close, and end are valid frame types of the AMQP protocol."], "r": "See lecture 8 (Basics of IoT Networking – Part IV) @ 06:34"}, {"q": "Which of the following is/are NOT the function/functions of the Bindings component of the AMQP protocol?", "o": ["Receives messages and routes them to queues", "Separate queues for separate business process", "Consumer receive messages from queues", "All of these"], "a": 3, "s": ["The Bindings component of the AMQP protocol manages the rules for distributing messages (who can access what messages, destination of the message)"], "r": "See lecture 8 (Basics of IoT Networking – Part IV) @ 08:05"}, {"q": "Which of the following is/are NOT exchange types in AMQP?", "o": ["Direct", "Indirect", "Fan-out", "Topic"], "a": 1, "s": ["The AMQP exchange types are – a) Direct b) Fan-out c) Topic d) Header"], "r": "See lecture 8 (Basics of IoT Networking – Part IV) @ 08:56"}, {"q": "State whether the following statement is True or False. Statement: The IEEE 802.15.4 is a well-known standard for low data-rate Wireless Personal Area Network (WPAN).", "o": ["True", "False"], "a": 0, "s": ["The IEEE 802.15.4 is a well-known standard for low data-rate Wireless Personal Area Network (WPAN)."], "r": "See lecture 9 (Connectivity Technologies – Part-I) @ 02:57"}, {"q": "The networking topologies supported in the IEEE 802.15.4 are -", "o": ["Only Star", "Star and Mesh", "Only Mesh", "None of these"], "a": 1, "s": ["The networking topologies defined in IEEE 802.15.4 are star and mesh."], "r": "See lecture 9 (Connectivity Technologies – Part-I) @ 08:56"}, {"q": "State whether the following statement is True or False. Statement: Periodic transmission of beacon messages does not occur in beacon enabled networks (IEEE 802.15.4).", "o": ["False", "True"], "a": 0, "s": ["Periodic transmission of beacon messages occur in beacon enabled networks (IEEE 802.15.4)."], "r": "See lecture 9 (Connectivity Technologies – Part-I) @ 13:21"}]});
addSet('iot',202303,{"title": "", "label": "2023 · Week 3", "tag": "’23 W3", "group": "2023", "questions": [{"q": "State whether the following statement is true or false. Statement: Wired HART lacks a network layer.", "o": ["True", "False"], "a": 0, "s": ["Wired HART lacks a network layer."], "r": "See lecture 11 (Connectivity Technologies-III) @ 05:22"}, {"q": "The HART physical layer is derived from ____________ protocol and operates only in __________ GHz ISM band.", "o": ["IEEE 802.15.4, 2.4", "IEEE 802.15.4, 4.8", "IEEE 802.16.5, 4.8", "None of these"], "a": 0, "s": ["The HART physical layer is derived from IEEE 802.15.4 protocol and operates only in 2.4 GHz ISM band."], "r": "See lecture 11 (Connectivity Technologies-III) @ 05:43"}, {"q": "State whether the following statement is True or False Statement: Super-frames in HART consist of grouped 20ms wide timeslots.", "o": ["True", "False"], "a": 1, "s": ["Super-frames in HART consist of grouped 10ms wide timeslots."], "r": "See lecture 11 (Connectivity Technologies-III) @ 07:05"}, {"q": "_________________ identifies channels consistently affected by interference and removes themfrom use.", "o": ["Channel hopping", "Channel aggregating", "Channel blacklisting", "Frequency aggregating"], "a": 2, "s": ["Channel Blacklisting identifies channels consistently affected by interference and removes them from use."], "r": "See lecture 11 (Connectivity Technologies-III) @ 07:30"}, {"q": "The _________________ supervises each node in the network and guides them on when and where to send packets.", "o": ["Application manager", "Network manager", "Trust manager", "None of these"], "a": 1, "s": ["The Network manager supervises each node in the network and guides them on when and where to send packets.."], "r": "See lecture 11 (Connectivity Technologies-III) @ 12:14"}, {"q": "NFC is designed for use by devices within _________ to each other?", "o": ["Close proximity", "No near contact", "Both (a) and (b)", "None of these"], "a": 0, "s": ["NFC is designed for use by devices within close proximity to each other."], "r": "See lecture 11 (Connectivity Technologies-III) @ 17:43"}, {"q": "______________ contain information which is readable by other devices, however it cannot read information itself.", "o": ["Active NFC devices", "Dumb NFC devices", "Passive NFC devices", "None of these"], "a": 2, "s": ["Passive NFC devices contain information which is readable by other devices, however it cannot read information itself."], "r": "See lecture 11 (Connectivity Technologies-III) @ 18:33"}, {"q": "NFC devices work on the principle of ___________________?", "o": ["Magnetic introduction", "Magnetic induction", "Both (a) and (b)", "None of these"], "a": 1, "s": ["NFC devices work on the principle of magnetic induction."], "r": "See lecture 11 (Connectivity Technologies-III) @ 20:00"}, {"q": "Which of these is NOT a mode of operation NFC?", "o": ["Server-to-Server", "Peer-to-Peer", "Read/Write", "Card emulation"], "a": 0, "s": ["There are primarily three modes of operation in NFC as – a. Peer-to-peer b. Read/Write c. Card emulation"], "r": "See lecture 11 (Connectivity Technologies-III) @ 23:00"}, {"q": "State whether the following statement is true or false Statement: Paging in Bluetooth is the process of forming a connection between two Bluetooth devices.", "o": ["True", "False"], "a": 0, "s": ["Paging in Bluetooth is the process of forming a connection between two Bluetooth devices."], "r": "See lecture 12 (Connectivity Technologies-IV) @ 05:32"}, {"q": "There are ______ modes of operation in Bluetooth.", "o": ["3", "4", "5", "None of these"], "a": 1, "s": ["There are 4 modes of operation in Bluetooth."], "r": "See lecture 12 (Connectivity Technologies-IV) @ 06:48"}, {"q": "Zwave uses __________ for signaling and control?", "o": ["Light", "RF", "Sound", "None of these"], "a": 1, "s": ["Zwave uses RF for signaling and control."], "r": "See lecture 13 (Connectivity Technologies-V) @ 2:40"}, {"q": "Which of the following is/are not a constraint on sensor nodes?", "o": ["Must consume high power", "Not be adaptive to the environment", "Both (a) and (b)", "None of these"], "a": 2, "s": ["Sensor nodes - a. Must consume extremely low power b. Be adaptive to the environment"], "r": "See lecture 14 (Sensor Networks-I) @ 14:35"}, {"q": "___________ are simply those that are unable to perform an operation; this could be because of power failure and environmental events.", "o": ["Normal nodes", "Failed nodes", "Badly failed nodes", "None of these"], "a": 1, "s": ["Failed nodes are simply those that are unable to perform an operation; this could be because of power failure and environmental events."], "r": "See lecture 15 (Sensor Networks-II) @ 03:52"}, {"q": "Dumb behavior of sensor nodes is _______________ in nature (as it is dependent on the effects of the environmental conditions).", "o": ["Temporal", "Spatial", "Both (a) and (b)", "None of these"], "a": 0, "s": ["Dumb behavior of sensor nodes is Temporal in nature (as it is dependent on the effects of the environmental conditions)."], "r": "See lecture 15 (Sensor Networks-II) @05:40"}]});
addSet('iot',202304,{"title": "", "label": "2023 · Week 4", "tag": "’23 W4", "group": "2023", "questions": [{"q": "State whether the following statement is true or false. Statement: Coverage in WSN is defined as the area-of-interest is covered satisfactorily.", "o": ["True", "False"], "a": 0, "s": ["Coverage in WSN is defined as the area-of-interest is covered satisfactorily."], "r": "See lecture 17 (Sensor Networks-IV) @ 01:44"}, {"q": "If transmission range &gt;= 2* sensing range,", "o": ["Coverage implies greater coverage", "Coverage implies connectivity", "Both (a) and (b)", "None of these"], "a": 1, "s": ["If transmission range &gt;= 2* sensing range, coverage implies connectivity."], "r": "See lecture 17 (Sensor Networks-IV) @ 04:14"}, {"q": "The two types of reporting in WSN are -", "o": ["Event driven and machine driven", "Event driven and weather driven", "Event driven and on demand", "None of these"], "a": 2, "s": ["The two types of reporting in WSN are Event driven and on demand"], "r": "See lecture 17 (Sensor Networks-IV) @ 08:09"}, {"q": "The objective of coverage in WSN is to use a _______________ number of sensors and _______________ the network lifetime.", "o": ["minimum, minimize", "minimum, maximize", "maximum, minimize,", "maximum, maximize"], "a": 1, "s": ["The objective of coverage in WSN is to use minimum number of sensors and maximize the network lifetime."], "r": "See lecture 17 (Sensor Networks-IV) @ 08:47"}, {"q": "State true or false. The disadvantages of stationary Wireless Sensor Networks are - Statement-I: Node failure may result in partition of networks. Statement-II: Topology cannot change automatically.", "o": ["Statement-I True, Statement-II False", "Both Statements are False", "Both Statements are True", "None of these"], "a": 2, "s": ["The disadvantages of stationary Wireless Sensor Networks are – a. Node failure may result in partition of networks. b. Topology cannot change automatically."], "r": "See lecture 18 (Sensor Networks-V) @ 1:11"}, {"q": "A _________________ in MWSN moves in order to collect data from sensor nodes and goes to the sink and delivers the collected data from different sensor nodes.", "o": ["Drop", "Molecule", "Mule", "None of these"], "a": 2, "s": ["A mule in MWSN moves in order to collect data from sensor nodes and goes to the sink and delivers the collected data from different sensor nodes."], "r": "See lecture 18 (Sensor Networks-V) @ 07:12"}, {"q": "________________ allows distributed sensing carried by humans and the goal is not just to collect data but to allow the common people to assess and share the knowledge.", "o": ["Voluntary sensing", "Compressive sensing", "Dynamic sensing", "Participatory sensing"], "a": 3, "s": ["Participatory sensing allows distributed sensing carried by humans and the goal is not just to collect data but to allow the common people to assess and share the knowledge."], "r": "See lecture 18 (Sensor Networks-V) @ 13:01"}, {"q": "Which of the following is/are NOT feature/features of UAV networks?", "o": ["Mesh or star networks", "Multi-tasking", "Large coverage area", "None of these"], "a": 3, "s": ["The following are the features of UAV networks - a. Mesh or star networks b. Multi-tasking c. Large coverage area"], "r": "See lecture 19 (UAV Networks) @ 02:43"}, {"q": "Which of the following is NOT a UAV network constraint?", "o": ["Frequent link breakages", "Prone to malfunction", "Very Complex", "None of these"], "a": 3, "s": ["The following are UAV network constraints - a. Frequent link breakages b. Prone to malfunction c. Very Complex"], "r": "See lecture 19 (UAV Networks) @ 09:32"}, {"q": "In _____________________ configuration, UAVs form multiple star topology. One node from each group connects to the ground station.", "o": ["Multi-star", "Ring", "Both (a) and (b)", "None of these"], "a": 0, "s": ["In multi-star configuration, UAVs form multiple star topology. One node from each group connects to the ground station."], "r": "See lecture 19 (UAV Networks) @ 12:03"}, {"q": "The full form of FANET is?", "o": ["Flying Ad Hoc Network", "Fast Ad Hoc Network", "Fidelity Ad Hoc Network", "None of these"], "a": 0, "s": ["The full form of FANET is Flying Ad Hoc Network."], "r": "See lecture 19 (UAV Networks) @ 14:11"}, {"q": "Low-end sensor nodes are -", "o": ["Whose deployment has high density in order to increase network lifetime and survivability.", "Who perform basic functions such as data aggregation, auto configuration, and power saving.", "Both (a) and (b)", "None of these"], "a": 2, "s": ["Low-end sensor nodes are - a. Whose deployment has high density in order to increase network lifetime and survivability. b. Who perform basic functions such as data aggregation, auto configuration, and power saving."], "r": "See lecture 20 (Machine to Machine Communication) @ 10:46"}, {"q": "Which of the following are the components of the M2M ecosystem?", "o": ["Trees", "Ocean", "Device Providers", "Non-service users"], "a": 2, "s": ["The components of the M2M ecosystem are as follows – a. Device Providers b. Internet Service Providers (ISPs) c. Platform Providers d. Service Providers e. Service Users"], "r": "See lecture 20 (Machine to Machine Communication) @ 13:00"}, {"q": "State whether the following statement is true or false Statement: The M2M Device Platform enables access to objects connected to the Internet anywhere any time.", "o": ["True", "False"], "a": 0, "s": ["The M2M Device Platform enables access to objects connected to the Internet anywhere any time."], "r": "See lecture 20 (Machine to Machine Communication) @ 16:47"}, {"q": "State whether the following statement is true or false Statement: The M2M Application Platform provides integrated services based on device collected data-sets.", "o": ["True", "False"], "a": 0, "s": ["The M2M Application Platform provides integrated services based on device collected data-sets."], "r": "See lecture 20 (Machine to Machine Communication) @ 17:53"}]});
addSet('iot',202305,{"title": "", "label": "2023 · Week 5", "tag": "’23 W5", "group": "2023", "questions": [{"q": "Company ABC manufactures a room temperature monitor which sends data via protocol X and company MNO manufactures another kind of room temperature sensor which sends data via protocol Y. With respect to this, which among the following correctly captures the said scenario?", "o": ["Homogeneity of IoT", "Heterogeneity of IoT"], "a": 1, "s": ["IoT is characterized by heterogeneity where different kinds of devices, each communicating with different set of protocols are designed. Refer first part of Lecture 21."], "r": ""}, {"q": "When two IoT devices wish to communicate, semantic conflict in such a scenario in IoT interoperability refers to____________________.", "o": ["Two devices built by the same manufacturer", "Two devices sensing the same physical parameter", "Two devices having different deployment location", "Two devices having different processing and business logic"], "a": 3, "s": ["Semantic conflict refers to when different IoT devices have different processing and business execution logic. Refer Lecture 21@5:32"], "r": ""}, {"q": "Which of the following issues needs to be addressed while solving user interoperability?", "o": ["Device characterization and identification", "Syntactic interoperability", "Semantic interoperability", "All of these"], "a": 3, "s": ["All of the options given should be addressed while solving user interoperability issues. Refer Lecture 21@15:16."], "r": ""}, {"q": "Which UMB interoperability component is responsible for converting physical devices into virtually abstracted ones?", "o": ["UMB Adaptor", "UMB Core", "UMB Hypervisor", "UMB Abstractor"], "a": 0, "s": ["UMB-A is responsible for converting physical devices into virtually abstracted ones. (Please refer Lecture 21@27:16)"], "r": ""}, {"q": "A Protocol Translation Unit (PTU) acts as a middleware between two IoT devices with different native protocols to enable them communicate with each other by translating the language of one device to the other one and vice versa.", "o": ["True", "False"], "a": 0, "s": ["Refer Lecture 21@22:16 and onwards where PTU has been explained."], "r": ""}, {"q": "Suppose that a smart CCTV camera has been configured using C++ language. With respect to the device’s cosign identification as per the standard definition (A,B,C,D), which among the following the information “Configuration Lang:C++” will be most appropriately mapped ?", "o": ["A", "B", "C", "D"], "a": 3, "s": ["For a device’s cosign (A,B,C,D), ‘D’ refers to the definition of the object, hence is the most appropriate to which configuration language, which may be considered a definition will be mapped."], "r": "Refer Lecture 21@21:16."}, {"q": "Which among the following are components of an Arduino UNO Board?", "o": ["LED Power Indicator", "Digital I/O Pins", "Analog IN Pins", "All of these"], "a": 3, "s": ["An Arduino UNO board contains several components, which also contain the ones listed above. Refer Lecture 22 on Arduino Board details."], "r": ""}, {"q": "What is the series of micro controller chips powering Arduino UNO boards?", "o": ["ATM series", "X86 series", "ARM 64 series", "ATMEGA series"], "a": 3, "s": ["Arduino UNO micro controllers are powered by ATMEGA series. Refer to any standard documentation on Arduino UNO."], "r": ""}, {"q": "In Arduino IDE the ‘Verify’ and ‘Upload’ buttons perform the exact same task.", "o": ["False", "True"], "a": 0, "s": ["In Arduino IDE, ‘Verify’ compiles the sketch and checks for its correctness, while ‘Upload’ uploads the sketch to the Arduino board. Refer Lecture 22@13:22"], "r": ""}, {"q": "Suppose that an Arduino UNO board is connected to a pneumatic sensor which sends tyre pressure as floating point numbers. Which among the functions will you use to read from the sensor?", "o": ["digitalRead()", "analogWrite()", "analogRead()", "None of these"], "a": 2, "s": ["As per the basics of Arduino programming. When you have real numbers in analog format, you use analogRead(). Refer Lecture 22."], "r": ""}, {"q": "Consider the following Arduino sketch. What must be inserted in the place of ‘??’ within the second pinMode() function in void setup()?", "o": ["INPUT", "OUTPUT", "None of these", "Anyone of these is okay"], "a": 1, "s": ["Since pin ‘g’ is writing digital values, it is required to set in OUTPUT mode. Refer Lecture 22-23."], "r": "", "img": "assets/iot/2023-w5-q11-1.png"}, {"q": "For integrating different types of sensors (such as DHT) with Arduino, you would need to install and #include the sensor specific libraries in your sketch.", "o": ["True", "False"], "a": 0, "s": ["Each different type of sensor has its specific libraries and functions which must be included with the Arduino sketch. Refer Lecture 24."], "r": ""}, {"q": "Which of the following best describes the command given below? ServoDemo.write(180);", "o": ["Creates an instance of the servo", "Pin writes 180 to the servo", "Servo moves 180 degrees", "All of these"], "a": 2, "s": ["As per the basics of Arduino libraries. See lecture 25 @ 08:15"], "r": ""}, {"q": "In an Arduino sketch, for the default function void setup(), which of the following is true?", "o": ["Point where the code terminates.", "Point where the code starts.", "It iterates over the different tasks in the program.", "None of the above."], "a": 1, "s": ["As per the basics of Arduino programming.See lecture 22@13:52"], "r": ""}, {"q": "Which among the following can also be described as a relay, which is an actuator?", "o": ["Pneumatic actuator", "Motor type actuator", "Electro-mechanical switch", "Thermal switch"], "a": 2, "s": ["Relay is a type of electro-mechanical switch and is also an actuator. Refer Lecture 25@3:57"], "r": ""}]});
addSet('iot',202306,{"title": "", "label": "2023 · Week 6", "tag": "’23 W6", "group": "2023", "questions": [{"q": "Python doesn’t support strict rules for syntax and static variable declaration like C", "o": ["True", "False"], "a": 0, "s": ["As per Python program. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I @ 4:23)"], "r": ""}, {"q": "Fill in the blanks. __________ is a data-type in Python.", "o": ["List", "Tuple", "Dictionary", "All of these"], "a": 3, "s": ["As per Python program. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I @ 15:18)"], "r": ""}, {"q": "Fill in the blanks. __________are the variables declared inside a function.", "o": ["Immediate variables", "Global variables", "Local variables", "None of these"], "a": 2, "s": ["As per Python program (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I @ 25:41)."], "r": ""}, {"q": "What does the open() function return for file operations?", "o": ["File mode", "File object", "File name", "None of these"], "a": 1, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "Python does not follow rigid indentation.", "o": ["True", "False"], "a": 1, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "Which of the following is used to display an image in Python?", "o": ["image.show()", "image.open()", "image.name()", "image.mode()"], "a": 0, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "Which of the following models does python follow for networking.", "o": ["Client-server", "P2P", "All of these", "None of these"], "a": 0, "s": ["In python programming, python provides network services for client-server models. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- II @ 23:29 )"], "r": ""}, {"q": "In python, ”with” ensures the file is closed after the operation is completed, but not when an exception occurs.", "o": ["True", "False"], "a": 1, "s": ["As per the basics of Python programming (Please refer to lecture"], "r": ""}, {"q": "In Raspberry Pi, GPIO acts only as a digital output.", "o": ["True", "False"], "a": 1, "s": ["Raspberry Pi GPIO acts as both digital output and digital input. (Please refer to lecture 28@10:14)."], "r": ""}, {"q": "Which of the following exits the nano editor in the terminal?", "o": ["Ctrl+O", "Ctrl+X", "Ctrl+A", "None of these"], "a": 1, "s": ["Ctrl+X exists the editor."], "r": "See lecture 29 @ 10:25"}, {"q": "Does Raspberry Pi provide configuration options for cameras ?", "o": ["Yes", "No"], "a": 0, "s": ["Raspberry Camera can be configured using raspi-config. See lecture 29 @ 19:04"], "r": ""}, {"q": "Does python provide a module for pi-camera ?", "o": ["Yes", "No"], "a": 0, "s": ["Raspberry Camera can be configured using the Python camera module python-picamera. See lecture 29 @ 19:59."], "r": ""}, {"q": "Which of the following converts energy to motion?", "o": ["Actuator", "Raspberry Pi", "All of these", "None of these"], "a": 0, "s": ["Actuator converts energy to motion."], "r": "See lecture 30 @ 03:37"}, {"q": "Which of the following is a property of a Relay.", "o": ["Mechanical switch", "Electrochemical switch", "None of these", "All of these"], "a": 3, "s": ["Relay is a mechanical/electrochemical switch . (Please refer to lecture 30@ 6:20)"], "r": ""}, {"q": "Sensors can be neither analog nor digital.", "o": ["True", "False"], "a": 1, "s": ["Sensors can be analog or digital. (Please refer to lecture 30 @ 3:20)"], "r": ""}]});
addSet('iot',202307,{"title": "", "label": "2023 · Week 7", "tag": "’23 W7", "group": "2023", "questions": [{"q": "Raspberry Pi is like a mini computer which can perform a wide range of general purpose tasks.", "o": ["True", "False"], "a": 0, "s": ["Raspberry Pi devices act just like mini computers and can be configured to perform many things. Refer to the lectures on Raspberry Pi"], "r": ""}, {"q": "What is the complete form of GPIO pins on Raspberry Pi devices.", "o": ["General Public Input/Output", "Generative Purpose Input/Output", "General Purpose Input/Output", "Global Purpose Input/Output"], "a": 2, "s": ["GPIO stands for General Purpose Input/Output. Refer to any standard documentation on Raspberry Pi. Also visit (https://projects.raspberrypi.org/en/projects/physical-computing/1)"], "r": ""}, {"q": "The Python program which you execute on Raspberry Pi to read data from sensors and control actuators has the same syntax and style as any other Python program.", "o": ["False", "True"], "a": 1, "s": ["It does not matter for what a Python program is written, all Python programs follow the same syntax and style."], "r": ""}, {"q": "During remote server access by a Raspberry Pi, where the Raspberry Pi acts as a client, the client needs the following?", "o": ["Only IP address of server", "Only port number", "Both server IP address and port number", "Client’s IP address"], "a": 2, "s": ["A client can communicate with a server only if both IP address and port numbers are known. (Please refer Lecture 31@14:13)"], "r": ""}, {"q": "Which among the following are valid data processing activities", "o": ["Data Splitting", "Data filtering", "Data plotting", "All of the given"], "a": 3, "s": ["As per the basics of Python programming (Please refer to lecture"], "r": ""}, {"q": "Consider the following Python code snippet. Assume the syntax is correct and all required libraries are imported var = ‘Sensor@Actuator%Arduino’ pt = var.split(‘%’) print(pt) What will be the output (See every detail, including the apostrophes carefully)?", "o": ["[‘Sensor’,’Actuator’,’Arduino’]", "[‘Sensor@Actuator’,’Arduino’]", "[‘Sensor’,’Actuator%Arduino’]", "[‘Sensor@Actuator%Arduino’]"], "a": 1, "s": ["As per Python programming directives and the working of the split function()."], "r": "Refer Python documentation and Lecture 32@26:00"}, {"q": "Which among the following functions do you use while using MATPLOTLIB to add title to a plot?", "o": ["plot()", "add()", "label()", "title()"], "a": 3, "s": ["The title(&lt;name_of_title&gt;) functions adds title to a plot while using matplotlib."], "r": "Refer Lecture 32@12:00"}, {"q": "In traditional non software-defined network consisting of a network of switches, suppose OSPF is being used as the routing protocol. In this context which among the following is true.", "o": ["All the switches execute OSPF distributively", "Only one switch executes OSPF", "No switch executes OSPF", "All of these are true"], "a": 0, "s": ["Traditional networks are distributive, hence all the switches of the network execute OSPF. Refer Lecture 33 from 3:50 onwards."], "r": ""}, {"q": "In SDN, the Operating System (OS) is separated (i.e not strongly coupled) from the physical hardware for each switch.", "o": ["True", "False"], "a": 0, "s": ["SDN separates the physical and logical plane of the switch. So OS (part of logical plane) is separated from the hardware (part of the physical plane) for each switch. Refer Lecture 33 from 9:20 onwards."], "r": ""}, {"q": "Which among the following is a popular protocol implementing SDN?", "o": ["OpenSwitch", "OpenStack", "OpenFlow", "OpenEdge"], "a": 2, "s": ["OpenFlow by ONF is the most popular protocol implementing the principles of SDN. Refer to any standard documentation on OpwnFlow."], "r": ""}, {"q": "With respect to Software Defined Networking (SDN), which among the following is true?", "o": ["SDN couples the data plane and control plane.", "SDN has no relation to either data plane or control plane", "SDN separates the data plane and control plane.", "None of the stated."], "a": 2, "s": ["SDN separates the data plane and control plane. It is the fundamental principle of SDN. Refer Lecture 33 from 12:17 onwards, SDN Architecture."], "r": ""}, {"q": "Consider the following figure below. To which issue of SDN does this particular figure can be related to?", "o": ["Controller placement issue", "Flow Rule placement issue", "Hardware placement issue", "Analysis placement issue"], "a": 1, "s": ["The given figures shows the tabular structure of how flow rules are installed within SDN switches, so it pertains to flow rule placement issues. Refer Lecture 33@18:54, Rule Placement."], "r": "", "img": "assets/iot/2023-w7-q12-1.png"}, {"q": "Suppose that there are two LANs, each configured to be SDN enabled with their own set of switches and controller. Which among the following directional APIs will be used for communication between the two controllers?", "o": ["Northbound API", "East-Westbound API", "Southbound API", "Northeastbound API"], "a": 1, "s": ["East-Westbound APIs are responsible for communication between different SDN controllers and domains. Refer Lecture 34, APIs in SDN"], "r": ""}, {"q": "Which among the following is true?", "o": ["Backup Controllers have no use is SDN", "There is no difference between the main controller and backup controller", "Backup controllers take over when the main controller goes down", "It is not a good idea to keep backup controllers."], "a": 2, "s": ["Backup Controllers are required to take over the network control when the main controller fails. Refer Lecture 34@8:24"], "r": ""}, {"q": "IoT being data intensive and having a lot of security concerns, it is a good idea to integrate SDN with IoT to mitigate many of these issues.", "o": ["True", "False"], "a": 0, "s": ["SDN can be integrated with IoT to reap several benefits of both. Refer Lecture 35."], "r": ""}]});
addSet('iot',202308,{"title": "", "label": "2023 · Week 8", "tag": "’23 W8", "group": "2023", "questions": [{"q": "Traditional Wireless Mobile Networks are cost expensive in terms of _____________?", "o": ["Only CAPEX", "Only OPEX", "Both CAPEX and OPEX", "Neither CAPEX and OPEX"], "a": 2, "s": ["Traditional wireless mobile networks are cost expensive both with respect to capital expenditure (CAPEX) and Operational Expenditure (OPEX). Refer Lecture 36@2:45"], "r": ""}, {"q": "High mobility of users is one of the key challenges in rule placement for software defined wireless mobile networks.", "o": ["True", "False"], "a": 0, "s": ["Dynamic user mobility restricts the ease with which rules can be placed for software defined wireless mobile networks. Refer Lecture 36@8:43"], "r": ""}, {"q": "Which among the following is a solution for mobility-aware flow rule placement in SDIoT?", "o": ["Mobility-Flow", "Mobile-Flow", "Mobi-Flow", "M-Flow"], "a": 2, "s": ["Detailed Answer: Mobi-Flow has been proposed to provide a solution for mobility-aware flow rule placement. Refer Lecture 36@13:09 onwards"], "r": ""}, {"q": "Cloud, Utility, Grid and ______________________ have been the major trends in computing", "o": ["Clone", "Cluster", "Closure", "Cloud"], "a": 1, "s": ["Detailed Answer: Cloud, Utility, Grid and Cluster computing are some of the major trends in computing. Please refer Lecture 37@5:43 onwards"], "r": ""}, {"q": "Cloud computing models allow different users to share the same physical resources?", "o": ["True", "False"], "a": 0, "s": ["Cloud computing uses virtualization heavily and thus it allows different users to share the same underlying physical infrastructure."], "r": ""}, {"q": "As per NIST Visual Model of Cloud Computing, ‘Hybrid Cloud’ model and PaaS model both fall in the same category.", "o": ["True", "False"], "a": 1, "s": ["‘Hybrid Cloud’ is an example of cloud deployment model while ‘PaaS’ is an example of cloud service model. Refer Lecture 37@13:28"], "r": ""}, {"q": "When you are accessing Google docs or Microsoft Word online for accessing the features of a document writing software from your browser without specifically installing them, which among the following cloud service models is the most appropriate one that you are using.", "o": ["SaaS", "PaaS", "IaaS", "DaaS"], "a": 0, "s": ["This is an example of SaaS, since you are accessing a word/document processing software as a client over the network. The actual software itself runs on some remote cloud server (Please"], "r": "refer Lecture 37@26:14 AND 38@13:16)"}, {"q": "An organization A wants to deploy a cloud infrastructure, whereby it wants to push majority of the data to a cloud whose servers can be situated anywhere within the globe, but it wants certain private data to be pushed only to cloud servers that are present on-premise and are accessible by only authenticated members of the organization. In this context which among the following deployment model should be used?", "o": ["Private Cloud", "Public Cloud", "Hybrid Cloud", "Any of these"], "a": 2, "s": ["Hybrid cloud deployment model supports both the features of public and private cloud. Refer lecture 37, ppt No. 18."], "r": ""}, {"q": "Cloud services and resources should be rapidly ______________ in order to achieve their required performance", "o": ["entrusted", "elastic", "enterprise", "None of the given"], "a": 1, "s": ["Detailed Answer: Rapid elasticity is one of the key requirements for cloud computing paradigms and models. Refer Lecture 37@20:54"], "r": ""}, {"q": "Suppose that a start-up wants to enter into online book delivery business. It wants to create the user interface and the application by itself, but it does not have any networking or storage facility, so it wants to adopt the cloud computing practice. In this respect, which among the following cloud service models is most suitable for the start-up.", "o": ["Only SaaS", "Neither PaaS nor IaaS", "Both PaaS and IaaS can be adopted", "Neither SaaS, PaaS or IaaS"], "a": 2, "s": ["Detailed Answer: Since both IaaS and PaaS provides infrastructure and storage support to clients, either of PaaS or IaaS can be employed. Refer Lecture 38@3:00, comparision of different models."], "r": ""}, {"q": "Data security and client authentication is an issue in which of the following cloud service models?", "o": ["SaaS", "SaaS and PaaS", "IaaS", "All of them"], "a": 3, "s": ["Security is a pertinent issue in all of the cloud service models, which includes SaaS, PaaS and IaaS. Refer to any standard discussion on challenges and issues on cloud computing and Lecture 39."], "r": ""}, {"q": "Network, ___________________ and application level securities are the three aspects of cloud infrastructure securities.", "o": ["Client", "Web", "Host", "Wireless"], "a": 2, "s": ["Network, host and application level securities are the fundamental aspects of cloud infrastructure securities. Refer Lecture 39@16:42."], "r": ""}, {"q": "When a new user logs into a cloud framework, the first thing that needs to be done is ______________________________.", "o": ["User should be authenticated", "User should immediately be granted all the resources", "User should log off", "User should be penalized"], "a": 0, "s": ["User authentication is one of the primary security issue and any user which logs into the cloud framework must first be authenticated. Refer Lecture 39@26:53."], "r": ""}, {"q": "Service Level Agreements (SLAs) are mutually agreed by the client (customer) and cloud service provider (CSP) at the beginning. With respect to SLAs, what are the views that SLAs provide?", "o": ["Customer Point of View", "CSP Point of View", "Both Customer and CSP Point of View", "Neither Customer nor CSP Point of View"], "a": 2, "s": ["SLAs provide both the customer point of view and the CSP point of view between the customer and the CSP. Refer Chapter 10 (Page 245) of “Introduction to IoT” by Sudip Misra, Anandarup Mukherjee, Arijit Roy, Cambridge University Press."], "r": ""}, {"q": "CloudAnalyst simulation tool provides GUI and is written on top of CloudSim modules.", "o": ["Yes", "No"], "a": 0, "s": ["CloudAnalyst is built on top of CloudSim and also provides a GUI. Refer Lecture 40@12:02 onwards."], "r": ""}]});
addSet('iot',202309,{"title": "", "label": "2023 · Week 9", "tag": "’23 W9", "group": "2023", "questions": [{"q": "Which component of OpenStack do you use to access all the other components?", "o": ["Horizon", "Glance", "Neutron", "None of these"], "a": 0, "s": ["Horizon is the dashboard of OpenStack which provides the GUI and from where you can access other components. Please refer Lecture 41@3:54"], "r": ""}, {"q": "Which among the following is NOT a component of OpenStack?", "o": ["Horizon", "Heat", "Plasma", "Neutron"], "a": 2, "s": ["Plasma is not a component of OpenStack. The rest are various components, including Nova, Glance, Swift etc. Refer lecture 41, ppt No. 4"], "r": ""}, {"q": "Sensor cloud is simply dumping and organizing of sensor data on cloud computing platforms.", "o": ["True", "False"], "a": 1, "s": ["Sensor cloud incorporates many aspects and not simply dumping of senor data over cloud platforms. Refer Lecture 42@3:45 onwards"], "r": ""}, {"q": "Which among the following are limitations of traditional Wireless Sensor Networks (WSNs)?", "o": ["Procurement Issues", "Deployment Issues", "Maintenance Issues", "All of the given"], "a": 3, "s": ["For traditional WSNs, procurement, deployment and maintenance are all critical issues that needs to be taken care of. Refer Lecture 42@9:49 onwards."], "r": ""}, {"q": "In a typical sensor cloud architecture, the sensor cloud infrastructure that provides the virtualization lies ______________________________", "o": ["At the same layer as physical sensor devices", "At the application layer", "In between the physical sensor layer and the application layer", "Sensor cloud does not support virtualization"], "a": 2, "s": ["Detailed Answer: In a typical sensor cloud architecture, the sensor cloud infrastructure that provides the virtualization lies in between the physical sensor layer and the application layer. Refer Lecture 42@12:00 onwards."], "r": ""}, {"q": "Generally speaking, Sensor Cloud Service Providers (SCSPs) are also always the owners of the physical sensors", "o": ["Yes", "No"], "a": 1, "s": ["SCSPs are providers of the virtualized sensor services, but they may not the owners of the physical sensors in a typical deployment. Refer Lecture 42, ‘Actors in Sensor-cloud’."], "r": ""}, {"q": "In a typical sensor cloud architecture with virtualization, one virtual sensor can be associated with how many physical sensors?", "o": ["Only one", "One or more than one", "None", "Only two"], "a": 1, "s": ["One instance of a virtual sensor in sensor cloud architecture can be mapped with one, two or more physical sensors below. Refer Lecture 43, Optimal composition of virtual sensors"], "r": ""}, {"q": "Sensor virtualization aims to achieve more _________________________ in providing sensor based services", "o": ["Complexity", "Flexibility"], "a": 1, "s": ["Sensor virtualization and sensor cloud architecture are designed to provide more flexibility and convenience than traditional sensor based services. Refer to the lectures on Sensor Cloud and its motivation closely."], "r": ""}, {"q": "Suppose that you want to start a business to provide some IoT based application, but you do not have the means to develop the application layer logic, neither you have the means to purchase and deploy physical sensors. You can however, rent cloud servers for use and write interface logic for interfacing with other modules. Which among the following actors will be the most suitable for you?", "o": ["Physical sensor owner", "Application layer developer", "Sensor Cloud Service Provider (SCSP)", "You cannot start the business"], "a": 2, "s": ["Detailed Answer: SCSPs provide the sensor virtualization layer in between the application layer and the physical sensor layer and thus this is the best business model as per the requirements and constraints given."], "r": "Refer to the standard architecture of sensor cloud and utility of SCSPs."}, {"q": "Which among the following is implemented along with sensor cloud to make its services and performance better?", "o": ["Cashing", "Caching", "Casing", "Calling"], "a": 1, "s": ["Caching is very important in sensor cloud and is implemented along with sensor cloud to make the performances better. Refer Lecture 43@17:38 onwards."], "r": ""}, {"q": "Which among the following cases is most likely to reduce the overall price of sensor-cloud implementation provided that the data traverses through multiple sensor hops starting from the origin sensor to the sink node, and provided that all owners are honest and charge for only what is required?", "o": ["If physical sensors are owned by multiple owners with high profit margin", "If all physical sensors are owned by a single owner with uniform profit margin"], "a": 1, "s": ["If all the physical sensors are owned by a single owner, then the single owner will charge an uniform price for data traversing through the sensors. On the other hand, if multiple sensor owners are there, different owners will charge different rates, which may increase the price. Refer pricing in sensor-cloud, Lecture 43@25:40 onwards."], "r": ""}, {"q": "Fog computing is aimed to replace cloud computing completely and has no scope for integration with cloud", "o": ["True", "False"], "a": 1, "s": ["Fog computing is designed to assist and compliment cloud based technologies in providing better services, not remove cloud all together. Refer Lecture 44@3:46 onwards, Introduction to Fog, especially how it is connected to cloud computing."], "r": ""}, {"q": "Suppose data from an IoT device first goes to Fog layer for some basic processing, after which it goes to Cloud layer for advanced processing, then the processed data comes back to the Fog layer and then, it finally comes back to the origin sensor node. In the return journey no processing of data takes place anywhere, just transfer of data takes place. If ‘Tf’ is the time taken by the data to travel from sensor to fog and vice versa, and ‘Tc’ is the time taken by the data to travel from fog to cloud and vice versa, ‘Tfp’ is the data processing time at fog and ‘Tcp’ is the data processing time at cloud, what is the total round trip time ‘T’ taken by data starting from the origin sensor node, processing the data and then back to the sensor node after being processed.", "o": ["T = Tf + Tc + Tfp + Tcp", "b. T = Tf + Tc", "T = 2(Tf + Tc) + Tfp + Tcp", "T = 4(Tf + Tc + Tfp + Tcp)"], "a": 2, "s": ["Since data comes back to the origin sensor node, the traversal latency Tf and Tc will be counted twice. But, since processing takes place only once during onward journey, processing delay is only one time. Therefore, T = 2(Tf + Tc) + Tfp + Tcp. Refer to the lecture on cloud latency, Lecture 44@14:28 onwards."], "r": ""}, {"q": "Consider the standard Fog computing architecture. In which of the following layer will ‘very time sensitive data’ be processed?", "o": ["Nearest fog node", "Distant aggregate fog node", "Cloud", "Does not matter"], "a": 0, "s": ["Since the data is very time sensitive, it is required that the nearest fog node processes the data so that immediate action can taken. This is the benefit of having fog computing. Refer to Working of Fog, Lecture 45@13:20 onwards."], "r": ""}, {"q": "“Network, Accelerator, Compute and Storage” constitute the part of which view of fog computing architecture, as defined by OpenFog Consortium Architecture Working Group?", "o": ["System View", "Node View", "Software View", "None of these"], "a": 1, "s": ["Fog Computing Architectural framework has several views, node, system and software among them. Network, Accelerator, Compute and Storage” fall under Node View. Refer Chapter 11 (Page 260) of “Introduction to IoT” by Sudip Misra, Anandarup Mukherjee, Arijit Roy, Cambridge University Press, 2021."], "r": ""}]});
addSet('iot',202310,{"title": "", "label": "2023 · Week 10", "tag": "’23 W10", "group": "2023", "questions": [{"q": "Data fusion enables optimum utilization of massive data gathered from multiple sources.", "o": ["True", "False"], "a": 0, "s": ["Data fusion enables optimum utilization of massive data gathered from multiple sources. (Please refer Lecture 47@5:40)"], "r": ""}, {"q": "Which of the following is a stage in data fusion?", "o": ["Decision level", "Feature level", "Pixel level", "All of the above"], "a": 3, "s": ["Decision level, feature level, pixel level and signal level are the four stages of data fusion. (Please refer Lecture 47@11:00)"], "r": ""}, {"q": "Which of the following is one of the challenges of Data fusion?", "o": ["Imperfection", "Conflicts", "Ambiguity", "All of the above"], "a": 3, "s": ["The challenges of data fusion involves Imperfection, Conflicts and Ambiguity. (Please refer Lecture 47@9:16)"], "r": ""}, {"q": "Which of the following is one of the theory of evidence-based mathematical methods of data fusion?", "o": ["Belief function", "Bayesian analysis", "ANN", "None of these"], "a": 0, "s": ["Belief function is one of the theory of evidence-based mathematical methods of data fusion. (Please refer Lecture 47 @11:49)"], "r": ""}, {"q": "DLNA stands for Digital Living Network Alliance.", "o": ["True", "False"], "a": 0, "s": ["DLNA stands for Digital Living Network Alliance. (Please refer Lecture 48@13:45)"], "r": ""}, {"q": "Which of the following are the functional layers in smart parking?", "o": ["Information collection", "System Deployment", "Service Dissemination", "All of these"], "a": 3, "s": ["Information collection, System Deployment and Service Dissemination are the three functional layers in smart parking (Please refer Lecture 47@17:25)"], "r": ""}, {"q": "Which of the following statements are true about the HAN standards? Statement I: Physical and MAC layers are defined by IEEE802.15.4. Statement II: Network layer is defined by Zigbee. Statement III: Application layer is defined by IEEE802.15.4", "o": ["Statements I and II", "Statements I and III", "Statements II and III", "Statements I, II and III"], "a": 0, "s": ["Physical and MAC layers are defined by IEEE802.15.4. Network layer and Application layers are defined by Zigbee. (Please refer Lecture 48@16:11)"], "r": ""}, {"q": "Which of the following are true about X-10? Statement I: It allows remote control of compliant transmitters. Statement II: It has low speed and data rate. Statement III: It is adopted by GE.", "o": ["Statement I and II", "Statement II and III", "Statement I and III", "Statement I, II and III"], "a": 3, "s": ["X-10 allows remote control of compliant transmitters, has low speed and data rate and is adopted by GE. (Please refer Lecture 48@17:04)"], "r": ""}, {"q": "Fill in the blank. ____________enables vehicles to wirelessly share a diverse range of information.", "o": ["Local area network", "V2X Paradigm", "V2A Paradigm", "Metropolitan area network"], "a": 1, "s": ["V2X enables vehicles to wirelessly share a diverse range of information (Please refer Lecture 49@10:48)"], "r": ""}, {"q": "Which of the following is a property of Vehicular Ad-hoc Networks?", "o": ["Is based on DSRC", "Is based on WAVE", "Guaranteed low latency", "All of these"], "a": 3, "s": ["VANETs are based on DSRC and WAVE. They also have guaranteed low-latency in mobile environments. (Please refer Lecture 49@16:50)"], "r": ""}, {"q": "Knob is a switch type of INN.", "o": ["True", "False"], "a": 0, "s": ["Knob is a switch type of INN. (Please refer Lecture 49@23:56)"], "r": ""}, {"q": "Which of the following is responsible for central coordination in Body-brain architecture?", "o": ["Body", "INN", "Spinal cord", "None of these"], "a": 3, "s": ["The brain is responsible for central coordination in Body-brain architecture (Please refer Lecture 49@23:03)"], "r": ""}, {"q": "Which of the following stands for DSRC?", "o": ["Directed Short Range Communication", "Dedicated Short Range Communication", "Directed Small Range Communication", "Dedicated Small Range Communication"], "a": 1, "s": ["DSRC stands for Dedicated Short Range Communication (Please refer Lecture 50@7:27)"], "r": ""}, {"q": "Ad-hoc is a domain of VANET.", "o": ["True", "False"], "a": 0, "s": ["Ad-hoc is a domain of VANET. (Please refer Lecture 50@14:12)"], "r": ""}, {"q": "What are the disadvantages of V2X communication?", "o": ["Increased traffic safety", "Tracking of movement", "Efficient use of fuel", "None of these"], "a": 1, "s": ["Disadvantages of V2X communication includes tracking of movement, violation of privacy, loss of data control, etc. (Please refer Lecture 50@21:04)"], "r": ""}]});
addSet('iot',202311,{"title": "", "label": "2023 · Week 11", "tag": "’23 W11", "group": "2023", "questions": [{"q": "What are some of the other names of the smart grids?", "o": ["Electricity with a brain", "Energy internet", "Electronet", "All of these"], "a": 3, "s": ["Smart grids are also known as Electricity with a brain, Energy internet, and Electronet. (Please refer Lecture 51@8:33)"], "r": ""}, {"q": "Smart Grid follows which type of the flow of energy?", "o": ["Bidirectional", "Unidirectional", "All of these", "None of these"], "a": 0, "s": ["Smart grid is a modernized grid that enables bidirectional flow of energy. (Please refer Lecture 51@9:43)"], "r": ""}, {"q": "Which of the following is not a benefit associated with smart grids?", "o": ["Efficient transmission of electricity", "Lower electricity rates", "Unreliable and insecure electricity", "Improved security"], "a": 2, "s": ["Smart Grids provide efficient transmission of electricity, lower electricity rates and Improved security. (Please refer Lecture 51@11:26)"], "r": ""}, {"q": "Which of the following is a component of smart grid communication?", "o": ["Gateways", "Smart meters", "MDMSs", "All of these"], "a": 3, "s": ["The components of Smart Grid are Smart meters, Gateways, DAUs and MDMSs (Please refer Lecture 52 @12:16)"], "r": ""}, {"q": "Fill in the blank. ___________ can be used as an energy source in on-peak hours.", "o": ["PMUs", "DAUs", "PEVs", "None of these"], "a": 2, "s": ["PEVs or Plug-In Electric Vehicles can be used as an energy source in on-peak hours(Please refer Lecture 52 @6:29)"], "r": ""}, {"q": "Which of the following is a type of Dynamic System Attacks?", "o": ["Replay Attacks", "Dynamic data injection attacks", "Covert attacks", "All of these"], "a": 3, "s": ["Replay Attacks, Dynamic data injection attacks and Covert attacks are all types of Dynamic System Attacks (Please refer Lecture 52@19:55)"], "r": ""}, {"q": "Which of the following statements are true about gateways? Statement I: Each gateway connects a few closely located smart meters. Statement II: Gateways communicate mostly based on WiFi. Statement III: They help in two-way communication.", "o": ["Statements I and II", "Statements I and III", "Statements II and III", "Statement I, II and III"], "a": 3, "s": ["The gateways connect a few closely located smart meters, communicate mostly on WiFi and help in two-way communication. (Please refer Lecture 52@14:11)"], "r": ""}, {"q": "Fill in the blank. ____________ is a centralized coordinator for smart grid communication.", "o": ["Gateway", "Smart meter", "PMU", "MDMS"], "a": 3, "s": ["MDMS is a centralized coordinator for smart grid communication. (Please refer Lecture 52@15:32)"], "r": ""}, {"q": "Fill in the blank. ____________ are available protocols for smart home appliances.", "o": ["C-Bus", "DECT", "EnOcean", "All of these"], "a": 3, "s": ["C-Bus, DECT, EnOcean and Universal Powerline Bus (Please refer Lecture 52@12:35)"], "r": ""}, {"q": "Fill in the blank. IIoT is a network of____________.", "o": ["Physical objects", "Systems", "Platforms", "All of the above"], "a": 3, "s": ["IIoT is a network of physical objects, systems, platforms and applications (Please refer Lecture 53@15:24)"], "r": ""}, {"q": "IIoT is based on Rip &amp; Replace approach.", "o": ["True", "False"], "a": 1, "s": ["IIoT is based on wrap &amp; re-use approach. (Please refer Lecture 53@9:53)"], "r": ""}, {"q": "Which of the following happened in the 1st Revolution?", "o": ["Mass production", "Internet evolution", "Automation", "None of these"], "a": 3, "s": ["Mass production, internet evolution, automation happened in forth revolution. (Please refer Lecture 53@10:06)"], "r": ""}, {"q": "Which of the following is a challenge of IIoT?", "o": ["Worker health and safety", "Environmental production", "Optimized operations", "All of these"], "a": 3, "s": ["Worker health and safety, environmental production and optimized operations are all the safety challenges of IIoT. (Please refer Lecture 54@15:15)"], "r": ""}, {"q": "Monitoring and restoration of the traditional electrical grid is done manually.", "o": ["True", "False"], "a": 0, "s": ["Monitoring and restoration of the traditional electrical grid is done manually (Please refer Lecture 51@5:34)"], "r": ""}, {"q": "What is Hadoop used in?", "o": ["Distributed processing of large datasets", "Large clusters of computers", "All of these", "None of these"], "a": 2, "s": ["Hadoop is used for distributed processing of large datasets across Large clusters of computers (Please refer Lecture 55@23:18)"], "r": ""}]});
addSet('iot',202312,{"title": "", "label": "2023 · Week 12", "tag": "’23 W12", "group": "2023", "questions": [{"q": "The two types of data analysis are _____________.", "o": ["Qualitative and Quantitative", "Repetitive and Quantitative", "Repetitive and Qualitative", "All of these"], "a": 0, "s": ["Qualitative and Quantitative are the two types of data analysis. (Please"], "r": "refer Lecture 56@2:33)"}, {"q": "Which of the following is a principle of Qualitative analysis?", "o": ["Notice things", "Think about things", "Collect things", "All of these"], "a": 3, "s": ["The three principles of Qualitative analysis are: Notice things, think about things and collect things. (Please refer Lecture 56@4:12)"], "r": ""}, {"q": "Select the statement(s) that denote the type of ANOVA. Statement I: One way analysis Statement II: Two way analysis Statement III: K-way analysis", "o": ["Statement I", "Statement II", "Statements I, II, and III", "None of these"], "a": 2, "s": ["The types of ANOVA includes One way analysis, Two way analysis and K-way analysis (Please refer Lecture 56@11:57)"], "r": ""}, {"q": "What is the type of the data dispersion?", "o": ["Range", "Average absolute deviation", "Variance", "All of these"], "a": 3, "s": ["Range, average absolute deviation and variation are the type of data dispersions. (Please refer Lecture 56@13:43)"], "r": ""}, {"q": "The process by which numerical data is analyzed is known as __________.", "o": ["Qualitative analysis", "Quantitative analysis", "None of these", "All of these"], "a": 1, "s": ["Quantitative analysis is the process by which numerical data is analyzed. (Please refer Lecture 56@4:47)"], "r": ""}, {"q": "The mathematical equation that is formulated in the form of relationships between variables is known as __________.", "o": ["Logical model", "Relational model", "Data dispersion", "Statistical model"], "a": 3, "s": ["The mathematical equation that is formulated in the form of relationships between variables is known as Statistical model (Please refer Lecture 56@7:53)"], "r": ""}, {"q": "What are the two types of statistical models?", "o": ["Qualitative and quantitative", "Complete and incomplete", "Regression and dispersion", "None of these"], "a": 1, "s": ["Complete and incomplete are two types of statistical models (Please"], "r": "refer Lecture 56@8:11)"}, {"q": "Contingency table is also known as?", "o": ["Cross tabulation", "Cross table", "All of these", "None of these"], "a": 2, "s": ["Contingency table is also known as Cross tabulation and Cross table. (Please refer Lecture 56@14:36)"], "r": ""}, {"q": "Advances in sensor and connectivity have disabled preventive care.", "o": ["True", "False"], "a": 1, "s": ["Advances in sensor and connectivity have disabled preventive care. (Please refer Lecture 58@4:22)"], "r": ""}, {"q": "Which of the following is a feature of IoT Healthcare?.", "o": ["Non-invasive monitoring", "Cloud-based analytics", "Wireless transmission", "All of these"], "a": 3, "s": ["Non-invasive monitoring, Cloud-based analytics and Wireless transmission are all types of IoT healthcare. (Please refer Lecture 58@12:36)"], "r": ""}, {"q": "Which of the following are components of IoT?", "o": ["Sensing layer", "Aggregated layer", "Processing layer", "All of these"], "a": 3, "s": ["Sensing layer, Aggregated layer, Processing layer and cloud platform are components of IoT. (Please refer Lecture 58@8:17)"], "r": ""}, {"q": "Which of the following is the advantage of activity monitoring?", "o": ["Hard integration", "Long term monitoring", "Expensive", "None of these"], "a": 1, "s": ["Long term monitoring is one of the advantages of Activity monitoring. (Please refer Lecture 59@16:17)"], "r": ""}, {"q": "Deep learning based data analysis cannot be performed on videos", "o": ["True", "False"], "a": 1, "s": ["Deep learning based data analysis can be done on sensor data, images and videos. (Please refer Lecture 59@19:34)"], "r": ""}, {"q": "Which of the following is true for in-place activity monitoring data analysis?", "o": ["Low power", "Good network connection required", "On-device", "Group-based analytics"], "a": 2, "s": ["In-place activity monitoring data analysis is on-device and power intensive (Please refer Lecture 59@20:10)"], "r": ""}, {"q": "Fill in the blank. Processing the handheld activity device data with artificial intelligence can be used for ________.", "o": ["Fall detection", "Heart rate detection", "Vehicle detection", "All of these"], "a": 0, "s": ["Processing the handheld activity device data with artificial intelligence can be used for detecting sudden fall of a person. (Please refer Lecture 60@11:56)"], "r": ""}]});
addSet('iot',202201,{"title": "", "label": "2022 · Week 1", "tag": "’22 W1", "group": "2022", "questions": [{"q": "Which of the following is a static mechanism for address allocation of IoT nodes?", "o": ["Configuration over a management interface", "IPv6 address based on a hardware identifier", "Both configuration over a management interface &amp; based on a hardware identifier", "IoT nodes can’t be configured statically"], "a": 2, "s": ["IoT nodes can be statically configured in different ways, such as an address can be configured over a management interface, or a node may use IPv6 address based on a hardware identifier."], "r": "See lecture 2 (IPv6 Addressing Strategies)"}, {"q": "Which of the following error is commonly found in heating of metal strips?", "o": ["quantization error", "aliasing error", "hysteresis error", "None of these"], "a": 2, "s": ["A hysteresis error causes the sensor output value to vary depending on the sensor’s previous input values. It is typically found in analog sensors, magnetic sensors, heating of metal strips."], "r": "See lecture 3 (Sensing)"}, {"q": "Identify the component shown below.", "o": ["Gas sensor", "PIR sensor", "Light sensor", "Speaker"], "a": 1, "s": ["Passive infrared (PIR) sensors use a pair of pyroelectric sensors to detect infrared energy radiating from objects within their field of vision."], "r": "", "img": "assets/iot/2022-w1-q3-1.png"}, {"q": "“X” performs active application layer functions between IoT nodes and other entities. What is X?", "o": ["IoT node", "IoT proxy", "IoT gateway", "IoT Network"], "a": 1, "s": ["IoT proxy is an entity that performs an active application layer function between IoT nodes, and other entities. The IoT proxy can be collocated with the IoT gateway."], "r": "See lecture 2"}, {"q": "Which of the following field in IPv4 header format indicates that it is concerned with reliable transmission?", "o": ["Traffic class", "Hop limit", "Fragment offset", "Destination address"], "a": 2, "s": ["The IPv4 emphasizes more on reliable transmission, as is evident by fields, such as type of service, total length, id, offset, TTL, checksum fields."], "r": "See lecture 2"}, {"q": "Which of the following is a function of IoT Gateway?", "o": ["Data forwarding", "Device management", "Protocol conversion", "All of these"], "a": 3, "s": ["An IoT gateway performs several critical functions, like switching, routing, translating protocols, firewall &amp;VPN services, security, data forwarding, managing device, and filtering data."], "r": "See lecture 2 & 5"}, {"q": "Which of the following actuator converts pressure into force?", "o": ["Mechanical actuators", "Pneumatic actuators", "Electric actuators", "Magnetic actuators"], "a": 1, "s": ["Pneumatic actuators enable large forces to be produced from relatively small pressure changes (e.g., Pneumatic brakes are very responsive to small changes in pressure applied by the driver)"], "r": "See lecture 4 (Actuation)"}, {"q": "Which of the following mechanism for address autoconfiguration provide more control on the allocated addresses?", "o": ["DHCPv6", "SLAAC", "Both DHCPv6 and SLAAC", "None of these"], "a": 0, "s": ["DHCPv6 can be used to explicitly configure IPv6 addresses to nodes, thereby providing network administrators with added control over the nodes on their networks."], "r": "See lecture 2 (IPv6 Addressing Strategies)"}, {"q": "Which of the following can measure position?", "o": ["Potentiometer", "Encoder", "Both potentiometer &amp; encoder", "None of these"], "a": 2, "s": ["A potentiometer sensor measures the distance or displacement of an object in a linear or rotary motion and converts it into an electrical signal. An encoder is an electromechanical device that can measure motion or position."], "r": "See lecture 3 (Sensing)"}, {"q": "In a scenario when the IoT proxy has uplink connectivity, does the IoT LAN need global addressing mandatorily?", "o": ["Yes", "No", "Not applicable"], "a": 1, "s": ["When the IoT proxy has uplink connectivity, it proxies communication between the local IoT nodes and nodes in the external network. In this scenario, where all communications go through a proxy, the IoT LAN does not need global addressing, but can manage with link-local or ULA addresses, depending on the type of proxy."], "r": "See lecture 2 (IPv6 Addressing Strategies)"}, {"q": "Which of the following is TRUE?", "o": ["M2M is not a subset of IoT", "WoT and IoT are same", "IoT and M2M are same", "None of these"], "a": 3, "s": ["M2M is a part of the IoT, where IoT has a broader scope than M2M. Both are different since M2M uses point-to-point communication. IoT and WoT aren’t same."], "r": "See lecture 1"}, {"q": "Statement I: Aliasing error occurs if the input variable or added noise changes periodically at a frequency proportional to the multiple of the sampling rate. Statement II: If the signal is monitored digitally, the sampling frequency can cause a dynamic error triggering aliasing error.", "o": ["Both Statement I and II are false", "Both Statement I and II are true", "Statement I is false but Statement II is true", "Statement I is true but Statement II is false"], "a": 1, "s": ["If the signal is monitored digitally, the sampling frequency can cause a dynamic error, or if the input variable or added noise changes periodically at a frequency proportional to the multiple of the sampling rate, aliasing errors may occur."], "r": "See lecture 3 (Sensing)"}, {"q": "Does polymer-based actuator find application in manufacturing artificial muscles?", "o": ["Yes", "No"], "a": 0, "s": ["Shape memory polymer (SMP) actuators function similar to our muscles, even providing a response to a range of stimuli such as light, electrical, magnetic, heat, pH, and moisture changes."], "r": "See lecture 4"}, {"q": "Unique Local Addresses are intended to allow routing over a network that expands over multiple links and routing hops, and even can expand over multiple networks. Can these addresses prevent address collision?", "o": ["Yes", "No", "Not Applicable"], "a": 0, "s": ["Unique Local Addresses are designed to be used in local networks larger than a single link, but not for communications through the Internet. However, these are designed to provide adequate uniqueness in order to have extremely small risk of address collision."], "r": "See lecture 2 (IPv6 Addressing Strategies)"}, {"q": "Which of the following is an example of vector sensor?", "o": ["Pressure sensor", "Strain sensor", "Both pressure and strain sensors", "Sound sensor"], "a": 3, "s": ["Physical quantities such as sound, image, velocity, acceleration, orientation, etc. are all vector quantities, as only their magnitude is not sufficient to convey the complete information."], "r": "See lecture 3 (Sensing)"}]});
addSet('iot',202202,{"title": "", "label": "2022 · Week 2", "tag": "’22 W2", "group": "2022", "questions": [{"q": "Which of the following protocol is used to implement device management for mobile devices?", "o": ["OMA-DM", "Websocket", "Alljoyn", "DNS-SD"], "a": 0, "s": ["OMA-DM is a protocol specified by the Open Mobile Alliance and is often used in the context of complex structured mobile solutions. It is often preferred by service providers to implement device management for mobile devices."], "r": "See lecture 6"}, {"q": "In LOADng, can intermediate routers respond to Route Requests (RREQs)?", "o": ["Yes, in any case", "Yes, only when RREQ flooding occurs", "Yes, only if they have active routes to the sought destination", "No"], "a": 3, "s": ["Intermediate LOADng Routers are explicitly prohibited from responding to RREQs, even if they may have active routes to the sought destination."], "r": "See lecture 10"}, {"q": "Which of the following functions as the network bridge in IEEE 802.15.4 network?", "o": ["PAN Coordinator", "Router", "Device", "None of these"], "a": 0, "s": ["Every IEEE 802.15.4 network has a minimum of one coordinator device type who acts as the root; it also functions as the network bridge. The coordinator performs data handling and storing operations."], "r": "See lecture 9"}, {"q": "Which of the following allow communication between Zigbee and no-Zigbee devices?", "o": ["layer-5 application-level bridge", "layer-7 application-level gateway", "layer-7 application-level bridge", "layer-5 application-level gateway"], "a": 1, "s": ["In order to enable communication between Zigbee and no-Zigbee devices, a layer-7 application-level gateway has to be created, which is quite complex. Cambridge University Press."], "r": "Refer to the book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT."}, {"q": "Statement I: RFIDs are radio-frequency-based. Statement II: RFID devices can act as both readers as well as tags. Which one of the following is correct?", "o": ["Statement I is true but Statement II is false", "Statement I is false but Statement II is true", "Both the statements are true", "Both the statements are false"], "a": 0, "s": ["RFIDs are primarily radio-frequency-based, which can work even when they are not visible. These devices can’t act as both readers as well as tags."], "r": "See lecture 10"}, {"q": "In AMQP, which of the following functionality defines its component “exchange”?", "o": ["linkage between various queues", "receives messages from various queues", "defines rules for message routing to various queues", "routing the messages to various queues"], "a": 3, "s": ["Messages are not posted directly in the queue; rather, the user sends messages to the exchange. An exchange is responsible for routing the messages to the various queues."], "r": "See lecture 8"}, {"q": "Which of the following is designed to have low overhead and better scalability in terms of dense networks?", "o": ["LOADng", "RPL", "Both LOADng and RPL", "AODV"], "a": 1, "s": ["RPL is designed to have low overhead and better scalability in terms of dense networks. See lecture 10"], "r": ""}, {"q": "Which of the following AMQP frame type controls the message flow rate?", "o": ["Transfer", "Flow", "Control", "Disposition"], "a": 1, "s": ["“Flow” frame type controls the message flow rate. See lecture 8"], "r": ""}, {"q": "Does 6LoWPAN allow interoperability between IEEE802.15.4-based wireless devices and other IP-based devices?", "o": ["Yes", "No"], "a": 0, "s": ["6LoWPAN allows interoperability between IEEE802.15.4-based wireless devices, as well as other IP-based devices. 6LoWPAN simply uses a bridge to enable communication between other devices. Cambridge University Press."], "r": "Refer to the book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT."}, {"q": "In the context of XMPP, which of the following correctly defines BOSH?", "o": ["XML streaming", "HTTP binding", "Both XML streaming and HTTP binding", "Binary encoding"], "a": 1, "s": ["BOSH is the HTTP binding for XMPP communications that is intended to be used in situations where a device or client is unable to maintain a long-lived TCP connection to an XMPP server."], "r": "See lecture 7"}, {"q": "Does MQTT support event-driven architecture?", "o": ["Yes", "No"], "a": 0, "s": ["MQTT protocol uses a publish/subscribe architecture. Publish/subscribe is event‐driven and enables messages to be pushed to clients. See lecture 6"], "r": ""}, {"q": "Which of the following is the acronym for “Extensible Messaging and Presence Protocol”?", "o": ["EMPP", "XMLP", "XMPP", "XMP"], "a": 2, "s": ["XMPP stands for Extensible Messaging and Presence Protocol. See lecture 7"], "r": ""}, {"q": "An IoT network requires communication mechanism, which is capable of synchronous as well as asynchronous communication. The mechanism should support both request-response, as well as publish-subscribe models. Which of the following protocol would be best suited for such a mechanism?", "o": ["AMQP", "CoAP", "MQTT", "None of these"], "a": 1, "s": ["CoAP is capable of synchronous as well as asynchronous communication. It supports both request-response as well as publish-subscribe models. Cambridge University Press."], "r": "Refer to the book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT."}, {"q": "Which of the following technique is used to transmit data frames in Beacon-enabled IEEE 802.15.4 networks?", "o": ["unslotted CSMA/CA", "slotted CSMA/CA", "unslotted CSMA/CD", "slotted CSMA/CD"], "a": 1, "s": ["The periodic transmission of beacon messages characterizes beacon enabled networks. Here, the data frames are sent via slotted CSMA/CA with a super-frame structure managed by a personal area network (PAN) coordinator."], "r": "See lecture 9"}, {"q": "What is the maximum size of hop limit in 6LoWPAN packet format?", "o": ["8-bit unsigned integer", "16-bit unsigned integer", "8-bit signed integer", "16-bit signed integer"], "a": 0, "s": ["Hop limit in 6LoWPAN packet format allows up to 8-bit unsigned integer. Decremented by 1 by each node that forwards the packet. The packet is discarded if Hop Limit is decremented to zero."], "r": "See lecture 10"}]});
addSet('iot',202203,{"title": "", "label": "2022 · Week 3", "tag": "’22 W3", "group": "2022", "questions": [{"q": "Which of the following handles packets, paging and inquiry in Bluetooth?", "o": ["L2CAP", "Baseband", "RFComm", "Physical Radio"], "a": 1, "s": [""], "r": ""}, {"q": "Which of the following incorporates channel hopping after every packet transmission?", "o": ["Zigbee", "WirelessHART", "6LoWPAN", "None of these"], "a": 1, "s": [""], "r": ""}, {"q": "In “X” protocol, a central network controller device sets-up a network with 1 Network ID and multiple node IDs for the devices in it. The nodes with different Network IDs cannot communicate with each other. What is “X”?", "o": ["Z-wave", "Zigbee", "Bluetooth", "ISA 100.11A"], "a": 0, "s": [""], "r": ""}, {"q": "In the context of Sensor Web, SensorML stands for ____________.", "o": ["Sensor Modeling language", "Sensor Machine language", "Sensor Markup language", "None of the above"], "a": 0, "s": [""], "r": ""}, {"q": "Which of the following protocol is best suited to provide interference-free communication while minimizing latency and ensuring quality of service?", "o": ["WirelessHART", "ISA100.11A", "Both WirelessHART and ISA100.11A", "None of these"], "a": 1, "s": [""], "r": ""}, {"q": "Which of the following solution approach is used to overcome the limitation of ineffective wakeup and sensing under rare event monitoring scenario in social sensing?", "o": ["Duty-cycle management", "Sleep-cycle management", "Packet transmission management", "Both duty-cycle and sleep-cycle management"], "a": 0, "s": [""], "r": ""}, {"q": "Which of the following technique Bluetooth master uses to avoid collisions during transmission in a Piconet?", "o": ["Frequency Division Multiplexing", "Frequency Hopping Spread Spectrum", "Time Division Multiplexing", "Direct Sequence Spread Spectrum"], "a": 2, "s": [""], "r": ""}, {"q": "Which of the following limitation is faced by total co-operation in Wireless Ad Hoc and Sensor Networks?", "o": ["Decreasing network throughput", "Decreasing energy", "Both (a) and (b)", "No limitation exists"], "a": 1, "s": [""], "r": ""}, {"q": "Which of the following can function over a reliable packet transfer protocol?", "o": ["L2CAP", "Service Discovery Protocol", "RFComm", "Physical Radio"], "a": 1, "s": [""], "r": ""}, {"q": "In which of the following mode, NFC devices can act as both readers as well as tags?", "o": ["Reader/writer", "P2P", "Emulation", "NFC devices can’t act as both readers as well as tags"], "a": 2, "s": [""], "r": ""}, {"q": "In WSN, Information theoretic self-management (INTSEM) controls the transmission rate of a node by adjusting a node’s ____________.", "o": ["Duty cycle", "Lifetime", "Sleep time", "Can’t control the transmission rate"], "a": 2, "s": [""], "r": ""}, {"q": "Which of the following layer of ISA 100.11A supports mesh routing?", "o": ["Network layer", "Data link layer", "Transport layer", "MAC layer"], "a": 1, "s": [""], "r": ""}, {"q": "Which of the following is used to avoid interference-prone channels in HART?", "o": ["Channel blacklisting", "Channel switching", "Channel hopping", "Super-frames"], "a": 1, "s": [""], "r": ""}, {"q": "When the devices are not in range, messages are routed through different nodes to bypass obstructions created by household appliances or layouts. Which of the following exhibit such characteristic of avoiding radio dead-spots?", "o": ["Bluetooth", "6LoWPAN", "Z-wave", "Zigbee"], "a": 2, "s": [""], "r": ""}, {"q": "Which of the following is TRUE in terms of power (in mW) and range (in m) of the classes of Bluetooth devices?", "o": ["Class-1: Power=100mW, Range=100m", "Class-2: Power=2.5 mW, Range=100m", "Class-1: Power=2.5 mW, Range=100m", "Class-2: Power=100 mW, Range=100m"], "a": 0, "s": [""], "r": ""}]});
addSet('iot',202204,{"title": "", "label": "2022 · Week 4", "tag": "’22 W4", "group": "2022", "questions": [{"q": "Which of the following UAV topology is self-configuring?", "o": ["Mesh", "Star", "Both mesh and star", "Grid"], "a": 0, "s": ["Star topology is not self-configuring, while mesh topology is self- configuring."], "r": "See lecture 19"}, {"q": "In WMSNs application, which of the following deployment can provide better sensing and prolong network lifetime?", "o": ["Scalar sensor nodes", "Camera sensor nodes", "Both scalar and camera sensor nodes", "Vector sensor nodes"], "a": 2, "s": ["In WMSNs application, deployment of both camera sensor and scalar sensor nodes can provide better sensing and prolong network lifetime. Camera sensor"], "r": "See lecture 16"}, {"q": "In which of the following algorithms only a subset of nodes in the WASN participate in sensing, communication, and computation?", "o": ["Localized", "Distributed", "Centralized", "All of these"], "a": 0, "s": ["Localized algorithms are a special type of distributed algorithms where only a subset of nodes in the WASN participate in sensing, communication, and computation."], "r": "See lecture 17"}, {"q": "In general, the target-tracking problem consists of a WSN, whose nodes are strategically or randomly deployed across the sensor field. Is the statement true?", "o": ["Yes", "No"], "a": 0, "s": ["According to several authors, the target-tracking problem consists of a WSN, whose nodes are strategically or randomly deployed across the sensor field. Pazzi. \"Target tracking for sensor networks: A survey.\" ACM Computing Surveys (CSUR) 49, no. 2 (2016): 1-31.]"], "r": "See lecture 16 [Research Paper: Souza, Éfren L., Eduardo F. Nakamura, and Richard W."}, {"q": "In Ad-Hoc FANETs, which of the following set-up can be considered as ground network?", "o": ["Stationary WSNs", "Control stations", "VANETS", "All of these"], "a": 3, "s": ["In Ad-Hoc FANETs, ground networks may be stationary WSNs or VANETS or Control stations."], "r": "See lecture 19"}, {"q": "Which of the following components in M2M monitors the status of devices and M2M area networks, and controls them based on their status?", "o": ["M2M User Platform", "M2M Device Platform", "M2M Service Platform", "M2M Access Platform"], "a": 1, "s": ["M2M device platform manages device profiles, such as location, device type, address, and description. It monitors the status of devices and M2M area networks, and controls them based on their status."], "r": "See lecture 20"}, {"q": "In the guided target-tracking problem formulation, a tracker is added to the problem. The tracker follows the trajectory defined by beacon nodes to intercept the target. Which of the following objectives best define this tracking algorithm?", "o": ["to fuse data about the target", "to use the least amount of communication to reach the target", "to reach the target in the shortest possible time", "to increase the network lifetime"], "a": 2, "s": ["The tracker can be a person or a guided vehicle that receives the position of the target from the network so that it can move toward the target. The objective is to reach the target in the shortest possible time."], "r": "See lecture 16"}, {"q": "In gateway selection algorithm in FANETs, each UAV acquires the information of all UAVs within its ________ hop(s).", "o": ["One", "Two", "More than one", "Can’t be specific"], "a": 1, "s": ["In gateway selection algorithm in FANETs, gateway selection is initiated by selection of the most stable node in the sub‐area. Each UAV acquires the information of all UAVs within its 2 hops."], "r": "See lecture 19"}, {"q": "A crossing is covered if it is in the _________ region of at least one node’s coverage disk.", "o": ["exterior", "interior", "either exterior or interior", "boundary"], "a": 1, "s": ["Crossings are the intersection points between disk boundaries or between monitored space boundary and disk boundaries. A crossing is covered if it is in the interior region of at least one node’s coverage disk."], "r": "See lecture 17"}, {"q": "There are several major challenges related to target-tracking applications. Which of the following is NOT among those challenges?", "o": ["target recovery", "node non-cooperation", "future-position estimation", "energy management"], "a": 1, "s": ["Authors identified six major challenges related to target-tracking applications. These are target detection, target recovery, energy management, position computation, node cooperation, and future-position estimation. Node cooperation is one of the challenges, in which nodes cooperate and fuse data, reducing the number of messages."], "r": "See lecture 16"}, {"q": "Which of the following components in M2M manages inquiry?", "o": ["M2M User Platform", "M2M Device Platform", "M2M Service Platform", "M2M Access Platform"], "a": 0, "s": ["M2M User Platform manages M2M service user profiles and provides functionalities such as, user registration, modification, charging, and inquiry."], "r": "See lecture 20"}, {"q": "Which of the following is NOT regarded as one of the major scatters of underwater sound in Underwater Acoustic Sensor Networks?", "o": ["Non-linear internal waves", "Solitons", "Linear internal waves", "None of these"], "a": 2, "s": ["In a layered shallow oceanic region, the inclusion of the effect of internal solitons on the performance of the network is important. Based on various observations, it is proved that non-linear internal waves, i.e., Solitons are one of the major scatters of underwater sound."], "r": "See lecture 16"}, {"q": "In Optimal Geographical Density Control (OGDC) algorithm, a node _________ if its coverage area is completely covered.", "o": ["wakes up", "starts listening", "sleeps", "backs off"], "a": 2, "s": ["In OGDC, a node closest to the optimal location becomes active. A node sleeps if its coverage area is completely covered."], "r": "See lecture 17"}, {"q": "Which of the following elements of target-tracking algorithm can perform data fusion?", "o": ["Active node", "Inactive node", "Beacon node", "Sink node"], "a": 3, "s": ["A sink node is the intermediary between the network and application user. It is a special node with high processing power and storage. It can perform data fusion. Pazzi. \"Target tracking for sensor networks: A survey.\" ACM Computing Surveys (CSUR) 49, no. 2 (2016): 1-31.]"], "r": "See lecture 16 [Research Paper: Souza, Éfren L., Eduardo F. Nakamura, and Richard W."}, {"q": "Which of the following components of Mobile Wireless Sensor Networks (MWSN) moves in order to collect data from sensor nodes?", "o": ["Mobile sensor node", "Data mule", "Mobile sink", "Both data mule and mobile sink"], "a": 3, "s": ["Mobile Sink moves in order to collect data from sensor nodes. A data mule also moves to collect the data from sensor nodes and goes to the sink to deliver the collected data."], "r": "See lecture 18"}]});
addSet('iot',202205,{"title": "", "label": "2022 · Week 5", "tag": "’22 W5", "group": "2022", "questions": [{"q": "Fill in the blank. UMB consists of __________.", "o": ["UMB-A and UMB-C", "UMB-A and UMB-B", "UMB-B and UMB-C", "UMB-A and UMB-E"], "a": 0, "s": ["UMB consists of UMB-Core (UMB-C) and UMB-Adaptor (UMB-A)."], "r": "See lecture 21 @25:50."}, {"q": "Fill in the blank. UMB creates virtual maps among the __________ of all middleware home networks.", "o": ["Virtual devices", "Physical devices", "Heterogeneous devices", "Services"], "a": 1, "s": ["UMB creates virtual maps among the physical devices of all the home networks such as HAVI, Jini, LonWorks, and UPnP."], "r": "See lecture 21 @ 25:15."}, {"q": "Which of the following is the functionality of UMB adaptors?", "o": ["Translate local middleware’s message into global metadata’s message.", "Translate global middleware’s message into global metadata’s message.", "Translate local middleware’s message into local metadata’s message.", "Translate global middleware’s message into local meta-data’s message."], "a": 0, "s": ["UMB converts physical devices into virtually abstracted one and translates local middleware’s message into global metadata’s message."], "r": "See lecture 21 @ 27:17."}, {"q": "Which of the following is true?", "o": ["Relay is an actuator that uses electromagnetic effect to act as a switch.", "Relay can open and close circuit when electricity is passed through it.", "Relay can be used to control the power supply to any other connected device.", "All of these."], "a": 3, "s": ["From the basics of relay interface with NodeMCU. Cambridge University Press."], "r": "Refer to the book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT."}, {"q": "What is sketch?", "o": ["Program coded in IoT devices.", "Program coded in Arduino IDE.", "Services of Arduino Uno.", "Services of IoT devices"], "a": 1, "s": ["Sketch is the program coded in Arduino IDE which mainly consists of two parts setup() and loop."], "r": "See lecture 22 @ 12:15"}, {"q": "What is function setup()?", "o": ["Point where code terminates.", "Point where code starts.", "It iterates the task in the program.", "None of the above."], "a": 1, "s": ["As per the basics of Arduino programming."], "r": "See lecture 22@13:52"}, {"q": "Which of the following is true for the given command? random(10);", "o": ["Gives random number within the range [0, 10]", "Gives random number within the range [1, 10]", "Gives random number within the range [0, 9]", "Reset the pseudo-random number generator with seed value 10"], "a": 0, "s": ["As per the basics of Arduino programming."], "r": "See lecture 23 @ 10:10"}, {"q": "Which kind of conflict occur when different processing logics are applied to same IoT networked devices or applications?", "o": ["Semantic conflict.", "Syntactic conflict.", "System conflict.", "Device conflict."], "a": 0, "s": ["Semantic conflict occurs when different processing logics are applied to same IoT networked devices or applications."], "r": "See lecture 21@5:20"}, {"q": "Which of the following is TRUE for the sketch command given below? delay(3000);", "o": ["Provides a delay of 3000 seconds", "Provides a delay of 3 seconds", "Provides a delay of 3000 nano seconds", "Provides a delay of 3000 simulation time"], "a": 1, "s": ["As per the basics of Arduino programming."], "r": "See lecture 22@17:20"}, {"q": "Which of the following solutions are not responsible for generating unique address?", "o": ["Election Product Code (EPC)", "Unique Product Code (UPC)", "Uniform Resource Identifier (URI)", "IP Addresses"], "a": 1, "s": ["As per the basics of device identification and categorization."], "r": "See lecture 21@16:25"}, {"q": "How many digital I/O pins are there in Arduino Uno.", "o": ["14", "54", "11", "16"], "a": 0, "s": ["From the basics of Arduino Uno. Cambridge University Press."], "r": "Refer to the book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT."}, {"q": "Fill in the blank. The interoperability between devices and device user in term of message formats is called _________.", "o": ["Systematic interoperability.", "Semantic interoperability.", "Syntactic interoperability.", "Device interoperability."], "a": 2, "s": ["The interoperability in terms of message formats is called syntactic interoperability."], "r": "See lecture 21@17:00"}, {"q": "Fill in the blank. __________ dynamically maps physical devices with different domains.", "o": ["Collaborative concept", "Middleware technology", "End devices", "Cloud"], "a": 1, "s": ["Middleware technology dynamically maps physical devices with different domains and based on the map, the devices can be discovered and controlled remotely."], "r": "See lecture 21@18:45"}, {"q": "Which of the following ontology utilize previous data to estimate what is going to happen?", "o": ["Device ontology", "Physical domain ontology", "Estimation ontology", "Virtual domain ontology"], "a": 2, "s": ["As per the basics of semantic interoperability for device ineraction."], "r": "See lecture 21 @ 20:25"}, {"q": "Which component of UMB converts physical devices into virtually abstracted one, as described by Universal Device Template (UMB).", "o": ["UMB-A", "UMB-C", "UDT mapping", "UMB-B"], "a": 0, "s": ["As per the definition of UMB-A."], "r": "See lecture 21 @ 28:00"}]});
addSet('iot',202206,{"title": "", "label": "2022 · Week 6", "tag": "’22 W6", "group": "2022", "questions": [{"q": "What is the value that is assigned to the variable f in the given piece of python code? i, f, str=50, 50.68, “Welcome to python”", "o": ["50", "50.68", "Welcome to python", "All of these"], "a": 1, "s": ["As per program output. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I@ 09:07)"], "r": ""}, {"q": "What is the output of the following piece of python code? x='17' y='23' z=x+y print(z)", "o": ["40", "6", "1723", "30"], "a": 2, "s": ["As per program output. (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I@ 21:05)"], "r": ""}, {"q": "Fill in the blanks. Raspbian is a/n ___________", "o": ["Microcomputer", "Minicomputer", "Operating system", "Assembler"], "a": 2, "s": ["Raspbian is a free operating system for Raspberry Pi (Please refer to lecture INTRODUCTION TO RASPBERRY PI-I@ 12:14)."], "r": ""}, {"q": "What is the output of the following piece of Python code? t1 = 'Welcome to python coding' print(t1[8:14])", "o": ["to pyth", "SyntaxError: invalid syntax", "e to pyt", "to pyt"], "a": 3, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "Fill in the blanks. Raspberry Pi 3 Model B has a GPU support of _________", "o": ["400 MHz video core IV", "250 MHz video core IV", "Quad cortex A53@1.2GHz", "ARM 11 @ 1 GHz"], "a": 0, "s": ["Raspberry Pi 3 Model B has a GPU support of 400 MHz video core IV. (Please refer to lecture INTRODUCTION TO RASPBERRY PI-I @ 6:00)"], "r": ""}, {"q": "Which of the following represents the command used for rebooting Raspberry Pi?", "o": ["sudo reboot", "sudo apt-get rebooting", "pip install rebooting", "All of these"], "a": 0, "s": ["As per the basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "State whether true or false. It is not possible to return multiple values from a function in Python.", "o": ["True", "False"], "a": 1, "s": ["In python programming it is possible to return multiple values. (Please"], "r": "refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I @ 24:41)"}, {"q": "What is the data type of the variable ls in the following piece of Python code? ls= {1: \"item\", \"key\": \"21\", \"year\": 2022}", "o": ["dictionary", "list", "tuple", "All of these"], "a": 0, "s": ["As per the basics of Python programming (Please refer to lecture"], "r": ""}, {"q": "State whether true or false. A function in Python may or may not return a value.", "o": ["True", "False"], "a": 0, "s": ["As per the basics of Python programming (Please refer to lecture"], "r": ""}, {"q": "What are the basic modes to open a file in python?", "o": ["Read mode (r) and write mode (w)", "Append mode (a)", "Both read and write mode (r+)", "All of these"], "a": 3, "s": ["As per basics of Python programming (Please refer to lecture"], "r": ""}, {"q": "What are the socket types that exist in Python based socket programming?", "o": ["AF_DG and SOCK_SM", "AF_UNIX and AF_INET", "SOCK_UX and SOCK_IT", "SOCK_DGRAM and SOCK_STREAM"], "a": 3, "s": ["SOCK_DGRAM and SOCK_STREAM are the socket types whereas AF_UNIX and AF_INET are socket families (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING-II @ 23:57)."], "r": ""}, {"q": "Does Python support exception handling?", "o": ["Yes", "No"], "a": 0, "s": ["As per basics of Python programming. (Please refer to lecture"], "r": ""}, {"q": "Which of the following must be used to terminate a loop and move to the next code after the loop?", "o": ["list", "try", "continue", "break"], "a": 3, "s": ["As per basics of Python programming (Please refer to lecture"], "r": ""}, {"q": "Select the option that does not represent a keyword in Python language?", "o": ["while", "if", "try", "integer"], "a": 3, "s": ["integer is not a keyword (As per basics of Python programming)."], "r": ""}, {"q": "Raspberry Pi does not support any other language other than Python?", "o": ["True", "False"], "a": 1, "s": ["The default programming language installed in Raspberry Pi include Python, C , C++, JAVA, Scratch and Ruby (Please refer to lecture INTRODUCTION TO PYTHON PROGRAMMING- I @ 22:26)."], "r": ""}]});
addSet('iot',202207,{"title": "", "label": "2022 · Week 7", "tag": "’22 W7", "group": "2022", "questions": [{"q": "You have an IoT temperature sensor that is sensing temperature from a particular location and sending the data over the network to a server situated far away in another city for storage. This is an example of remote data logging.", "o": ["True", "False"], "a": 0, "s": ["Remote data logging refers to the process of sending data and information from a client/sensor over the network to a remote server located somewhere else. Refer to lecture 31."], "r": ""}, {"q": "For a two-way communication between a client and server, i.e both the client and the server send data to each other, it is important that both of them knows about the following about each other", "o": ["Only the IP address of server", "Only the port number of client", "Both the IP address and port number", "Neither the IP address nor the port number"], "a": 2, "s": ["Since it is a two-way communication, the client and server should both know about the IP address and the port number of each other in order to communicate. Refer to lecture 31."], "r": ""}, {"q": "If you are using Raspberry Pi (RPi) to connect standard IoT sensors (such as DHT temperature sensors), which among the following components of the Raspberry Pi do you use connect your Pi to your sensor for data transfer.", "o": ["HDMI port of the RPi", "MicroSD card slot of the RPi", "Ethernet LAN port of the RPi", "General Purpose Input Output (GPIO) pins of the RPi"], "a": 3, "s": ["The GPIO pins of the RPi board is responsible for connecting the RPi to any external sensor/actuator. Refer standard materials on RPi and Lecture 31"], "r": ""}, {"q": "It is possible to connect a single DHT temperature sensor with a suitable number of connection wires with two Raspberry Pis acting as a client for the same sensor.", "o": ["True", "False"], "a": 0, "s": ["You can connect any number of RPis to the same sensor, with each RPi acting as a separate client, provided you have suitable number of connection wires."], "r": ""}, {"q": "Which among the following denotes the correct connection order for a standard 4-PIN DHT sensor with the order of PIN numbers taken as 4,3,2,1 (from right to left)", "o": ["Data, Null, Ground, Power", "Ground, Data, Power, Null", "Ground, Null, Data, Power", "Power, Data, Null, Ground"], "a": 2, "s": ["This is the standard configuration for a 4-PIN DHT sensor. Refer Lecture 32@3:30"], "r": ""}, {"q": "Using the matplotlib library in Python, you are plotting a graph of pressure values versus time, with pressure taken in the vertical axis and time taken in the horizontal axis. While writing the code to plot the graph, which among the following is the correct parameter (denoted by ‘??’) that you can write within the function “ylabel(??)”", "o": ["Time", "Pressure", "Length", "Mass"], "a": 1, "s": ["The function ylabel() sets the name of the Y-axis, i.e the vertical axis of a graph. Since we are plotting pressure in the Y-axis, thus we should label it appropriately."], "r": ""}, {"q": "Lack of centralized control is a problem and limitation of traditional network architectures without Software Defined Networking (SDN) support", "o": ["True", "False"], "a": 0, "s": ["Traditional networks do not have a central authority over them, therefore many issues take time to get resolved with distributed algorithms. Refer Lecture 33,"], "r": ""}, {"q": "Detaching the physical hardware from the overlying software components, such as the Operating System (OS) and applications forms an important aspect of transitioning to SDN", "o": ["True", "False"], "a": 0, "s": ["Refer Lecture 33, Introduction to SDN."], "r": ""}, {"q": "Flow rules are stored within SDN switches that run the OpenFlow protocol in the following format.", "o": ["Images", "Files", "Tables", "None of these"], "a": 2, "s": ["Flow rules are stored in tabular formats within the switches based on which packets get routed. Refer Lecture 33, discussions on Rule Placement"], "r": ""}, {"q": "Among the following, which is the most unlikely to be considered as a suitable candidate for a match- field for flow rules in SDN", "o": ["Source port number of the packet", "Destination IP address of the packet", "Temperature of the switch motherboard", "Destination MAC address."], "a": 2, "s": ["The temperature of the motherboard of a switch generally has no role in deciding how a packet will be forwarded. Refer to discussions on Flow rules in Lecture 33."], "r": ""}, {"q": "In SDN, the central controller of one network can communicate with the central controller of another SDN network through which of the following directional APIs", "o": ["East-West bound APIs", "Southbound APIs", "Westbound APIs", "None of these."], "a": 0, "s": ["In SDN, East and West bound APIs are used for inter-controller communication in the control plane. Refer Lecture 34@1:56"], "r": ""}, {"q": "Suppose in SDN, there are two switches S1 and S2. The same packet P arrives in both the switches, S2 does not have the appropriate flow rule to forward this particular packet, whereas S1 has. Then with respect to the two switches, what is the correct action that is taken.", "o": ["S1 sends PACKET_IN to controller, S2 forwards the packet", "S2 sends PACKET_IN to controller, S1 forwards the packet", "Both S1 and S2 send PACKET_IN to controller", "Both S1 and S2 forward the packet."], "a": 1, "s": ["If a switch does not have an appropriate flow rule to process an incoming packet, it sends PACKET_IN message to the controller, whereas if the switch has the flow rule, it simply forwards the packet as per the flow rule. Refer lectures 33 and 34."], "r": ""}, {"q": "No matter how big an SDN network becomes, we can never have more than one SDN controller.", "o": ["True", "False"], "a": 1, "s": ["There is provision for splitting a single controller into multiple distributed but connected controllers in tree/ring/mesh topologies to manage a very large network. Refer Lecture 34, controller placement problem."], "r": ""}, {"q": "With Software Defined IoT, it is possible to control the individual physical sensor and actuator nodes as well as rule placement of the backbone network remotely by suitable orchestration and software.", "o": ["Yes", "No"], "a": 0, "s": ["SDIoT allows flexible control and management of the entire IoT network, from the physical devices to the backbone network. Refer Lecture 35, architecture of SDN for IoT."], "r": ""}, {"q": "Soft-WSN that has been proposed as one of the solutions to Software Defined IoT achieves the following", "o": ["Only Device Management", "Only Topology Management", "Both Device and Topology Management", "Neither Device nor Topology Management"], "a": 2, "s": ["Soft-WSN that has been proposed by Bera et. Al (IEEE SJ’16) achieves both device and topology management efficiently. Refer Lecture 35@10:00 to 11:20"], "r": ""}]});
addSet('iot',202208,{"title": "", "label": "2022 · Week 8", "tag": "’22 W8", "group": "2022", "questions": [{"q": "The process of abstracting physical network hardware and resources from the network services and use cases are known as", "o": ["Network Splitting", "Network Virtualization", "Network Scaling", "None of these"], "a": 1, "s": ["Network virtualization is the process by which various network services are abstracted from their underlying physical hardware for smooth management. Refer Lecture 36@4:00"], "r": ""}, {"q": "ODIN is one of the proposed solutions towards Software Defined WSN and mobility management. As per the architecture of ODIN, which component of ODIN is placed on top of the controller.", "o": ["ODIN master", "ODIN agent", "Both ODIN master and agent", "Neither ODIN Master and agent"], "a": 0, "s": ["ODIN Master is associated with the SDN controller. Refer Lecture 36@9:50 onwards"], "r": ""}, {"q": "Shared pool of resources with easy configurability are important aspects of cloud computing.", "o": ["True", "False"], "a": 0, "s": ["Cloud computing deals with easy access of configurability of shared pool of computing resources over network. Refer Lecture 37"], "r": ""}, {"q": "In cloud computing, the users have specific knowledge about the exact physical location of the computing hardware with respect to the cloud services.", "o": ["True", "False"], "a": 1, "s": ["In cloud computing, the users have no knowledge about the backend physical hardware orchestration and management. Refer Lecture 37."], "r": ""}, {"q": "Suppose there are two organizations, A and B both of which provide cloud services. Any user can access the cloud of A free of cost whereas only employees of organization B can access the cloud of B. Also organization B has set up its cloud for only its own needs. With respect to the type of cloud infrastructure provided by A and B, which among the following is true", "o": ["A: Private Cloud, B: Public Cloud", "A: Public Cloud, B: Private Cloud", "A: Public Cloud, B: Public Cloud", "A: Private Cloud, B: Private Cloud"], "a": 1, "s": ["Since anyone can access the cloud services of A, it is public, whereas as only employees can access the cloud of B, the latter is a private cloud. Refer Lecture 37."], "r": ""}, {"q": "Which among the following can be considered as a potential service model for cloud computing.", "o": ["Software as a Service", "Database as a Service", "Platform as a Service", "All of these"], "a": 3, "s": ["All of the given options are well defined cloud service models. Refer Lecture 37 and 38, cloud service models."], "r": ""}, {"q": "Which of the following component can be considered as optional for a sensor node?", "o": ["Sensing unit", "Transceiver", "Location finding unit", "None of the above"], "a": 2, "s": ["Location finding unit, such as GPS is an optional component for any sensor node."], "r": "See lecture 14 @ 08:30"}, {"q": "You have bought a spreadsheet processing software in the form of a CD-ROM which you would need to install yourself on your computer to run and then manage. Is it an example of SaaS in cloud computing?", "o": ["Yes", "No"], "a": 1, "s": ["Cloud computing service models allows you to have access to software over the Internet without the need to install them on your local computer. Refer lecture on cloud computing service models."], "r": ""}, {"q": "Suppose two persons A and B both wish to access a particular SaaS feature from a cloud service provider through their respective personal computers. Both of them log into the cloud at the same time. Then which among the following is true.", "o": ["Neither A nor B will be able to access the services", "A will be able to access the services but not B", "B will be able to access the services but not A.", "Both A and B will be able to access the services"], "a": 3, "s": ["Cloud services are provided in a many to one manner by the service provider simultaneously. So both will be able to access. Refer Lecture 38@13:50"], "r": ""}, {"q": "Along with Accounting, which among the following is an essential component of cloud service management.", "o": ["Virtualization", "Billing", "Deployment", "None of these"], "a": 1, "s": ["Billing and Accounting are two important cloud service management activities. Refer Lecture 39@5:36"], "r": ""}, {"q": "Which among the following security paradigms is concerned with securing the in-transit data between the users and the cloud through the Internet.", "o": ["Network Level Security", "Host Level Security", "Application Level Security", "None of these."], "a": 0, "s": ["Network level security is concerned with the security of the in-transit data through the network in cloud computing. Refer Lecture 39@17:10"], "r": ""}, {"q": "“Cloud Security ensures that _____________ users can access their data after proper ____________________” Choose which among the following should be the correct order of words to be filled in the blanks.", "o": ["legitimate, authentication", "illegitimate, authentication", "malicious, inaction", "malicious, attack"], "a": 0, "s": ["Cloud security ensures proper authorization and authentication of only legitimate users. Refer 39 on Cloud security models."], "r": ""}, {"q": "Which among the following should be protected with proper access control in cloud computing", "o": ["Database access", "Server access", "Virtual resource access", "All of these"], "a": 3, "s": ["Access control should be incorporated in all of the given access points in cloud security. Refer Lecture 39@24:09"], "r": ""}, {"q": "Before launching your cloud services as a product to customers, it is always a good idea to test your cloud applications on a cloud simulator first in the pre-deployment phase.", "o": ["True", "False"], "a": 0, "s": ["Testing your cloud applications on a simulator first in the pre-deployment phase can help you to correct many errors before actually launching them. Refer Lecture 40."], "r": ""}, {"q": "With respect to virtualization in cloud computing, which among the following can be considered as suitable virtualization paradigms.", "o": ["Storage virtualization", "Hardware virtualization", "Application virtualization", "All of these."], "a": 3, "s": ["All of the given options can be considered for virtualization in cloud architectures. Refer Chapter 10 of reference book ‘Introduction to IoT’ by Misra et. Al (Cambridge University Press’20)"], "r": ""}]});
addSet('iot',202209,{"title": "", "label": "2022 · Week 9", "tag": "’22 W9", "group": "2022", "questions": [{"q": "The OpenStack cloud simulation framework provides an interactive Graphical User Interface (GUI)", "o": ["True", "False"], "a": 0, "s": ["OpenStack provides a very interactive and efficient GUI. Refer Lecture 41 OpenStack demonstrations."], "r": ""}, {"q": "Virtualized resources within the OpenStack simulator that you can define, set parameters of and deploy within OpenStack are also known as", "o": ["Instances", "Files", "Hypervisors", "Sketches"], "a": 0, "s": ["In OpenStack instances refer to the virtual resources that you define, initialize and deploy. Refer Lecture 41@15:36"], "r": ""}, {"q": "If you want to connect your OpenStack instance with the external public network (like the Internet), you would need to connect the following between your instance and the public network", "o": ["Database", "File", "Memory", "Router"], "a": 3, "s": ["Your OpenStack instance is not connected by default to the public network, you would need to initialize a router that makes the connection. Refer Lecture 41@17:37 onwards"], "r": ""}, {"q": "Which among the following is NOT a part of a sensor node connected to a wireless sensor network.", "o": ["Sensing unit", "Gaming unit", "Processing unit", "Communication unit"], "a": 1, "s": ["Each sensor in a WSN is equipped with Sensing unit, Processing unit and Communication unit. Refer Lecture 42@5:29"], "r": ""}, {"q": "Consider that you have two types of sensors, soil monitoring sensor for smart farming and temperature sensor for smart industry. The concept that the correct (right) type of sensor must be deployed only at their correct and appropriate physical location suitable as per their functionalities is known as", "o": ["Right way of deployment", "Right place of deployment", "Right time of deployment", "None of these"], "a": 1, "s": ["The sensor nodes must always be deployed at their appropriate location. i.e place which is suitable as per their functionalities. Refer Lecture 42@9:53"], "r": ""}, {"q": "Sensor-as-a-Service (Se-aaS) is an exciting new concept that brings the service models of cloud computing to traditional IoT sensor networks. In this aspect, which among the following forms an essential component of a Se-aaS architecture.", "o": ["Sensor marketing", "Sensor division", "Sensor virtualization", "Sensor manufacturing"], "a": 2, "s": ["Sensor virtualization is the principal concept behind the architecture and orchestration of Se-aaS. Refer Chapter 10 of reference book ‘Introduction to IoT’ by Misra et. (Cambridge University Press’20) Al and Refer Lecture 42"], "r": ""}, {"q": "Considering the end-to-end architecture of a WSN, from the physical sensor nodes right up to the users, sensor-cloud supports different entities to have ownership of the different layers and components simultaneously.", "o": ["True", "False"], "a": 0, "s": ["Sensor Cloud supports distributed ownership of different components of the WSN architecture by different entities. Refer Lecture 42@13:19"], "r": ""}, {"q": "In sensor cloud architecture the Sensor Cloud Service Provider (SCSP) is logically situated at the following position of the architecture", "o": ["In the same level as the physical sensors", "In between the physical sensors and the user layer", "In the same level as the users", "None of these"], "a": 1, "s": ["The SCSP is concerned with providing the cloud based services to the virtual sensor layer, hence it sits in the middle of the physical sensors and the user application layer. Refer Lecture 42 sensor cloud architecture."], "r": ""}, {"q": "In sensor cloud, the association between virtual sensor instances and the corresponding physical sensors follows", "o": ["one to one mapping", "one to many mapping", "many to one mapping", "many to many mapping"], "a": 3, "s": ["One virtual sensor can be associated with multiple physical sensors, similarly one physical sensor can be associated with many virtual sensors. Hence the mapping is many-many. Refer Lecture 42@6:20 onwards"], "r": ""}, {"q": "Dynamic caching mechanism improves the flexibility and efficiency of sensor cloud.", "o": ["True", "False"], "a": 0, "s": ["Caching can improve in better handling the data movement and user requests in a sensor cloud. Refer Lecture 43 on Dynamic and Adaptive Data Caching mechanism."], "r": ""}, {"q": "With respect to the caching based architecture of a sensor cloud, the External Cache (EC) has a direct data connection with which among the following", "o": ["The Internal Cache (IC)", "The user applications", "Physical sensors", "Both physical sensors and Internal Cache (IC)"], "a": 3, "s": ["The external cache serves as the intermediate interconnection between the physical sensors below and the Internal Cache (IC) above."], "r": ""}, {"q": "Data from an IoT device is transferred to cloud via a network, which is then processed at the cloud and then a response is sent back to the IoT device from the cloud after processing. The time it takes for one- way data transfer between the node and cloud is 10s and the data processing time at the cloud is ‘x’ seconds. It takes a total of 25s for the entire to and fro transfer of data between the sensor and cloud along with processing at the cloud. What is the value of x?", "o": ["10s", "5s", "15s", "20s"], "a": 1, "s": ["Time taken for one-way data transfer between the node and cloud is 10s. Total time taken for the data transfer is 25s. So 25=10+x+10 (transfer from node to cloud+processing at cloud+transfer from cloud to node). Thus x=5s."], "r": ""}, {"q": "There are two types of sensor data, A and B. A is time sensitive that is required to be processed immediately, while B is not time sensitive and can tolerate longer time for processing. As per the standard utilities of cloud and fog computing, which among the following options show the correct processing locations for A and B.", "o": ["A:Cloud, B: Fog", "A: Fog, B: Cloud", "None of these", "Both of these"], "a": 1, "s": ["Time sensitive data are processed at the fog layer while data that can tolerate processing delay are processed at the cloud layer. Refer Lecture 45, the working of Fog."], "r": ""}, {"q": "There can be multiple fog nodes in between the physical sensor layer at the bottom and the cloud layer at the top. a: True b. False", "o": ["True", "False"], "a": 0, "s": ["There can be multiple fog nodes in between the cloud layer and the physical sensor nodes for efficient processing. Refer Lecture 45, Architecture of Fog."], "r": ""}, {"q": "Which among the following is/are a potential problem and challenge in fog computing?", "o": ["Power consumption", "Data security", "Reliability", "All of these"], "a": 3, "s": ["There are several key challenges in fog computing, some of which are the options as given above. Refer challenges of Fog computing in Lecture 45."], "r": ""}]});
addSet('iot',202211,{"title": "", "label": "2022 · Week 11", "tag": "’22 W11", "group": "2022", "questions": [{"q": "State whether true or false. In a smart grid, monitoring and restoration are performed manually.", "o": ["True", "False"], "a": 1, "s": ["In a traditional electrical grid, monitoring and restoration are performed manually. (Please refer to lecture SMART GRID- I@1:37)."], "r": ""}, {"q": "Smart home uses the emerging smart grid technologies to satisfy which of the following?", "o": ["Save energy", "Contribute to the smooth and efficient functioning of the electric grid", "Seek out the lowest rate", "All of these"], "a": 3, "s": ["Smart home uses the emerging smart grid technologies to save energy, seek out the lowest rate, and contribute to the smooth and efficient functioning of the electric grid (Please refer to lecture SMART GRID- I@27:12)."], "r": ""}, {"q": "What is/are the benefit/s of using a smart grid by customers?", "o": ["Updated information on their energy usage in real-time", "Single pricing option", "Disabling the smart appliances and smart devices from charging", "All of these"], "a": 0, "s": ["For customers, the benefit of using a smart grid includes, updated information on their energy usage in real-time, different pricing options, and enabling smart appliances and other smart devices to be charged (Please refer to lecture SMART GRID- I@14:34)."], "r": ""}, {"q": "What is the full form of NAN?", "o": ["Not Area Network", "Neighborhood Area Network", "National Area Network", "None of these"], "a": 1, "s": ["The full form of NAN is Neighborhood Area Network (Please refer to lecture SMART GRID- II@12:02)."], "r": ""}, {"q": "State whether true or false. In smart grid communication, the gateway acts as a link between the smart meter and the data aggregator unit.", "o": ["True", "False"], "a": 0, "s": ["In smart grid communication, the gateway acts as a link between the smart meter and the data aggregator unit. (Please refer to lecture SMART GRID- II @ 14:01)"], "r": ""}, {"q": "What is/are the vulnerability/vulnerabilities that may exist in the smart grid?", "o": ["Physical threats", "Availability", "Dynamic system attacks", "All of these"], "a": 3, "s": ["The vulnerability attacks that may exist in the smart grid include physical threats, availability, and dynamic system attacks. (Please refer to lecture SMART GRID- II @ 16:54)"], "r": ""}, {"q": "Does the Industrial Internet of things follow the “rip &amp; replace” approach?", "o": ["Yes", "No"], "a": 1, "s": ["Industrial Internet of things follows the “wrap &amp; re-use” approach. (Please refer to lecture INDUSTRIAL INTERNET OF THINGS- I @ 6:12)"], "r": ""}, {"q": "Match the following: Sensor Purpose 1. 1st Industrial revolution a. Mass production 2. 2nd Industrial revolution c. b. Mechanized production 3. 3rd Industrial revolution d. c. Industrial Internet of Things 4. 4th Industrial revolution d. Internet evolution and automation", "o": ["1-b, 2-a, 3-d, 4-c", "1-b, 2-d, 3-a, 4-c", "1-c, 2-a, 3-d, 4-b", "1-c, 2-a, 3-b, 4-d"], "a": 0, "s": ["The industrial evolution of IIoT is as follows. 1. 1st Industrial revolution- Mechanized production 2. 2nd Industrial revolution- Mass production 3. 3rd Industrial revolution- Internet evolution and automation 4. 4th Industrial revolution- Industrial Internet of Things (Please refer to lecture INDUSTRIAL INTERNET OF THINGS- I @ 10:12)"], "r": ""}, {"q": "The implanted on-body sensors on a patient’s body have led to which of the following facility/facilities?", "o": ["Better treatment outcome", "Reduction in cost", "Better accuracy in the collection of data", "All of these"], "a": 3, "s": ["Patients can be continuously monitored due to the implanted on-body sensors. This has led to – improved treatment outcomes, the cost has reduced, and improved accuracy in the collection of data. (Please refer to lecture INDUSTRIAL INTERNET OF THINGS- II @ 3:18)"], "r": ""}, {"q": "Which of the following is considered the primary challenges of IIoT?", "o": ["Managing a huge amount of data", "Environmental protection", "Handling hazardous substances", "None of these"], "a": 0, "s": ["The primary challenges of IIoT includes the management of a huge amount of data. Environmental protection falls under safety challenge and handling hazardous substances is considered a hazard (related) challenge (Please refer to lecture INDUSTRIAL"], "r": ""}, {"q": "Which of the following is/are provided by the Intelligent Transport System?", "o": ["Vehicle-to-vehicle connectivity", "Vehicle-to-sensor connectivity", "Vehicle-to-internet connectivity", "All of these"], "a": 3, "s": ["Intelligent Transport System provides vehicle-to-vehicle connectivity, vehicle-to-sensor connectivity, and vehicle-to-internet connectivity. (Please refer to lecture INDUSTRIAL INTERNET OF THINGS- II @ 4:41)"], "r": ""}, {"q": "Fill in the blanks. Structured Query Language is mainly used for managing _____________ data in database.", "o": ["Unstructured", "Structured", "Audio", "All of these"], "a": 1, "s": ["Structured Query Language is mainly used for managing structured data in a database (Please refer to lecture DATA HANDLING AND ANALYTICS- I @9:06)."], "r": ""}, {"q": "What is/are the advantage/s of the application of ML on IoT?", "o": ["Self-learner", "Increases human interaction", "Not self-guided", "All of these"], "a": 0, "s": ["Some of the advantages of applying ML in IoT includes self-learner, time-efficient, self-guided, and minimum human interaction requirement (Please refer to book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT. Cambridge University Press. Chapter no.-17, page no.-357)."], "r": ""}, {"q": "Which of the following represent/s the veracity characteristics of Big data?", "o": ["Noise", "Abnormality", "Biases", "All of these"], "a": 3, "s": ["Veracity (characteristics of big data) refers to noise, biases, and abnormality in data (Please refer to lecture DATA HANDLING AND ANALYTICS- I @13:50)."], "r": ""}, {"q": "State whether true or false. NoSQL databases can be used for storing unstructured data.", "o": ["True", "False"], "a": 0, "s": ["Querying languages such as NoSQL are generally used for unstructured data. (Please refer to book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT. Cambridge University Press. Chapter no.-6, page no.-117)."], "r": ""}]});
addSet('iot',202212,{"title": "", "label": "2022 · Week 12", "tag": "’22 W12", "group": "2022", "questions": [{"q": "State whether true or false. In general, the data collected from an interview can be analyzed through qualitative analysis.", "o": ["True", "False"], "a": 0, "s": ["In qualitative analysis, the data can be gathered by many methods like interviews, videos, and audios (Please refer lecture Data Handling and Analytics- Part II @ 3:32)."], "r": ""}, {"q": "Which of the following are often involved with quantitative analysis?", "o": ["Analysis of variables", "Precision", "Data dispersion", "All of these"], "a": 3, "s": ["Analysis of variables, Precision, and Data dispersion are often involved with quantitative analysis (Please refer lecture Data Handling and Analytics- Part II @ 4:41)."], "r": ""}, {"q": "State whether true or false. A complete model does not have the same number of variables as the number of equations.", "o": ["True", "False"], "a": 1, "s": ["A complete model does have the number of variables equal to the number of equations. (Please refer lecture Data Handling and Analytics- Part II @ 8:15)"], "r": ""}, {"q": "Which of the following model is mostly applied when it is necessary to compare more than 2 populations or samples?", "o": ["Analysis of variance", "Integration", "Trigonometry", "All of these"], "a": 0, "s": ["Analysis of variance is mostly applied when it is necessary to compare more than 2 populations or samples. (Please refer lecture Data Handling and Analytics- Part II @ 9:36)"], "r": ""}, {"q": "Fill in the blanks. The effect size for determining statistical significance is the standardized _________ difference between two groups.", "o": ["Median", "Mean", "Inter quartile range", "None of the above"], "a": 1, "s": ["The effect size is the standardized mean difference between two groups. (Please refer lecture Data Handling and Analytics- Part II @ 17:15)"], "r": ""}, {"q": "Which of the following is/are some of the future of the IoT applications in the agriculture?", "o": ["Soil moisture monitoring", "Automation in vermicomposting", "Automated weeding system", "All of these"], "a": 3, "s": ["Soil moisture monitoring, Automation in vermicomposting, and Automated weeding system are some of the futures of the IoT applications in the agriculture. (Please refer lecture Case study: Agriculture @ 2:15)"], "r": ""}, {"q": "Which of the following may be considered as the objective of smart water management using IoT?", "o": ["Less yield using greater water requirement", "Manual irrigation", "Not supporting remote monitoring and controlling", "None of these"], "a": 3, "s": ["Some of the objectives of smart water management using IoT include more yield using less water, automatic irrigation and remote monitoring and controlling. (Please refer lecture Case study: Agriculture @ 4:35)."], "r": ""}, {"q": "State whether true or false. With the advancement in the sensors and connectivity, it is feasible to enable preventive care along with collecting patient’s data.", "o": ["True", "False"], "a": 0, "s": ["With the advancement in the sensors and connectivity, it is feasible to enable preventive care along with collecting patient’s data (Please refer lecture Case study: Healthcare @ 6:30)."], "r": ""}, {"q": "Integrated design for remote server in AgriSens includes which of the following?", "o": ["Web server", "Repository data server", "Multi users server", "All of these"], "a": 3, "s": ["Integrated design for remote server in AgriSens includes Web server, Repository data server and Multi users server (Please refer lecture Case study: Agriculture @ 9:16)."], "r": ""}, {"q": "State whether true or false. The data sensed by the physiological sensors in an IoT-based healthcare system are of no use without proper connectivity and communication.", "o": ["True", "False"], "a": 0, "s": ["Without proper connectivity and communication, the data sensed by the physiological sensors are of no use in an IoT-based healthcare system. (Please refer book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT. Cambridge University Press. Chapter no.-14, page no.-295)"], "r": ""}, {"q": "Match the following: Sensor Purpose 1. GSR a. Measures the health of a muscle and a nerve cell 2. EMGc. b. Measures the electrical and muscular activity of the heart 3. ECGd . c. Measures the intensity of stress on a human 4. SpO 2 d. Measures the pulse and oxygen levels in blood", "o": ["1-a, 2-c, 3-b, 4-d", "1-b, 2-d, 3-a, 4-c", "1-b, 2-a, 3-d, 4-c", "1-c, 2-a, 3-b, 4-d"], "a": 3, "s": ["GSR measures the intensity of stress on a human, EMG measures the health of a muscle and a nerve cell, ECG measures the electrical and muscular activity of the heart, SpO2 measures the pulse and oxygen levels in blood. (Please refer book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT. Cambridge University Press. Chapter no.- 14, page no.-296)"], "r": ""}, {"q": "What is/are the risk/s involved in healthcare IoT?", "o": ["Loss of connectivity", "Security (e.g., data tampering and unauthorized access)", "Error (e.g., misinterpretation of symptoms)", "All of these"], "a": 3, "s": ["The risk involved in healthcare IoT includes loss of connectivity, security and error. (Please refer book: S. Misra, A. Mukherjee, and A. Roy, 2020. Introduction to IoT. Cambridge University Press. Chapter no.-14, page no.-300)"], "r": ""}, {"q": "State whether true or false. Activity monitoring, particularly in IoT scenario, plays a vital role for rendering better quality of life and safe guarding humans.", "o": ["True", "False"], "a": 0, "s": ["Particularly in IoT scenario, activity monitoring plays an important role for rendering better quality of life and safe guarding humans. (Please refer lecture Activity monitoring Case Study - I @ 10:00)."], "r": ""}, {"q": "Fill in the blanks. Processing the sensed data on the device itself is known as __________ approach.", "o": ["Network based", "In-place", "Out of the place", "None of these"], "a": 1, "s": ["Processing the sensed data on the device itself is known as in-place approach. (Please refer lecture Activity monitoring Case Study - I @ 20:19)."], "r": ""}, {"q": "What is/are the different purpose/s that made wearable sensors popular?", "o": ["Medical", "Elderly-care", "Child-care", "All of these"], "a": 3, "s": ["Wearable sensors have become popular for different purposes which includes Medical, child-care and elderly-care (Please refer lecture Activity monitoring (Case Study - I @ 2:15)."], "r": ""}]});
